        // Wait for 2 seconds
        sleep(2);
    }

    // Release GPIO lines
    gpiod_line_release(line);
    gpiod_line_release(line3);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
