#include <gpiod.h>

#define GPIO_PIN 2
#define GPIO_PIN_3 3

struct gpiod_chip *chip;
struct gpiod_line *line;
struct gpiod_line *line3;

void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (line) {
        gpiod_line_release(line);
    }
    if (line3) {
        gpiod_line_release(line3);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main() {
    int ret;
    int value;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(line, "gpio_control", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Get GPIO line 3
    line3 = gpiod_chip_get_line(chip, GPIO_PIN_3);
    if (!line3) {
        perror("Error getting GPIO line 3");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line 3 for output
    ret = gpiod_line_request_output(line3, "gpio_control_3", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 3 for output");
        gpiod_line_release(line);
        gpiod_line_release(line3);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("GPIO control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Set GPIO 2 HIGH
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("Error setting GPIO 2 HIGH");
            break;
        }
        printf("GPIO 2 set HIGH\n");

        // Set GPIO 3 HIGH
        ret = gpiod_line_set_value(line3, 1);
        if (ret < 0) {
            perror("Error setting GPIO 3 HIGH");
            break;
        }
        printf("GPIO 3 set HIGH\n");

        // Wait for 0.1 seconds
        sleep(1);

        // Set GPIO 2 LOW
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("Error setting GPIO 2 LOW");
            break;
        }
        printf("GPIO 2 set LOW\n");

        // Set GPIO 3 LOW
        ret = gpiod_line_set_value(line3, 0);
        if (ret < 0) {
            perror("Error setting GPIO 3 LOW");
            break;
        }
        printf("GPIO 3 set LOW\n");

        // Wait for 0.1 seconds
        sleep(1);
    }

    // Release GPIO lines and chip on exit
    gpiod_line_release(line);
    gpiod_line_release(line3);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define the GPIO pin connected to the output
#define GPIO_PIN 2

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pin as an output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop to control the output
    while (program_running) {
        // Generate a random value between 0 and 1
        int random_value = rand() % 2;

        // Set the GPIO pin to the generated value
        gpioWrite(GPIO_PIN, random_value);

        // Print the generated value to standard output
        printf("GPIO %d set to %d\n", GPIO_PIN, random_value);

        // Wait for 5 seconds
        sleep(5);
    }

    // Release the GPIO pin
    gpioWrite(GPIO_PIN, 0); // Set to LOW to avoid floating state
    gpioSetMode(GPIO_PIN, PI_INPUT); // Set to input to avoid floating state
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register settings
#define CONFIG_OS_SINGLE 0x8000  // Start a single conversion
#define CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define CONFIG_PGA_4_096V 0x0000 // +/-4.096V range
#define CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define CONFIG_DR_128SPS 0x0080  // 128 SPS
#define CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define CONFIG_COMP_POL_LOW 0x0000 // Active low comparator
#define CONFIG_COMP_LAT_NON 0x0000 // Non-latching comparator
#define CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

// Global variable for I2C file descriptor
int i2c_fd;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    // Close I2C device
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a byte to an ADS1115 register
int write_register(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;

    if (write(fd, buf, 3) != 3) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a byte from an ADS1115 register
int read_register(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[1];
    buf[0] = reg;

    if (write(fd, buf, 1) != 1) {
        perror("Error writing register address for reading");
        return -1;
    }

    if (read(fd, buf, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    *value = (buf[0] << 8) | buf[1];
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Specify slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Configure ADS1115 for single-shot mode, AIN0, +/-4.096V, 128 SPS
    uint16_t config = CONFIG_OS_SINGLE | CONFIG_MUX_SINGLE_0 | CONFIG_PGA_4_096V | CONFIG_MODE_SINGLE | CONFIG_DR_128SPS | CONFIG_COMP_MODE_TRAD | CONFIG_COMP_POL_LOW | CONFIG_COMP_LAT_NON | CONFIG_COMP_QUE_DISABLE;

    // Write configuration to the ADS1115
    if (write_register(i2c_fd, ADS1115_REG_CONFIG, config) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Main loop to read and print ADC values
    while (1) {
        uint16_t adc_value;

        // Read ADC value
        if (read_register(i2c_fd, ADS1115_REG_CONVERT, &adc_value) < 0) {
            close(i2c_fd);
            return 1;
        }

        // Convert ADC value to voltage (assuming +/-4.096V range)
        float voltage = (float)adc_value * 4.096 / 32768.0;

        // Print ADC value and voltage
        printf("ADC Value: %u, Voltage: %.3f V\n", adc_value, voltage);

        // Wait for 0.5 seconds
        sleep(0.5);
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness in case the loop is ever modified.
    close(i2c_fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define the I2C address of the MLX90614 sensor
#define MLX90614_ADDR 0x5a

// Define the register address for the temperature reading
#define MLX90614_TA_REG 0x06

// Global variable for the I2C handle
int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    // Close the I2C connection
    i2cClose(i2c_handle);
    // Terminate the pigpio library
    gpioTerminate();
    exit(0);
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C connection
    i2c_handle = i2cOpen(1, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop to read and print the temperature
    while (1) {
        // Read the temperature from the MLX90614
        int raw_temp = i2cReadWordData(i2c_handle, MLX90614_TA_REG);
        if (raw_temp < 0) {
            fprintf(stderr, "Failed to read temperature data: %d\n", raw_temp);
            // Attempt to re-initialize the I2C connection
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(1, MLX90614_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-open I2C device: %d\n", i2c_handle);
                // Exit if re-initialization fails
                gpioTerminate();
                return 1;
            }
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        // Convert the raw temperature to Celsius
        float temperature = (float)raw_temp * 0.02 - 273.15;

        // Print the temperature to the console
        printf("Temperature: %.2f °C\n", temperature);

        // Wait for 5 seconds
        gpioDelay(5000000);
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness and to avoid compiler warnings.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define GPIO_PIN_1 4
#define GPIO_PIN_2 17

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Global variables for GPIO lines
struct gpiod_line *gpio_line_1 = NULL;
struct gpiod_line *gpio_line_2 = NULL;

// Function prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_set_value(int pin, int value);
int gpio_get_value(int pin);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Unexport GPIO pins
    if (gpio_line_1) {
        gpiod_line_release(gpio_line_1);
    }
    if (gpio_line_2) {
        gpiod_line_release(gpio_line_2);
    }

    // Close GPIO chip
    gpiod_chip_close(gpio_line_1 ? gpio_line_1->chip : gpio_line_2->chip);

    exit(0);
}

// Function to export a GPIO pin
int gpio_export(int pin) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s\n", GPIO_CHIP);
        return -1;
    }

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d\n", pin);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request(line, "gpio_export", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %d\n", pin, ret);
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

// Function to unexport a GPIO pin
int gpio_unexport(int pin) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s\n", GPIO_CHIP);
        return -1;
    }

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d\n", pin);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_release(line);
    if (ret < 0) {
        fprintf(stderr, "Error releasing GPIO line %d: %d\n", pin, ret);
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

// Function to set the direction of a GPIO pin (in or out)
int gpio_set_direction(int pin, const char *direction) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s\n", GPIO_CHIP);
        return -1;
    }

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d\n", pin);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_set_direction(line, direction);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line %d direction to %s: %d\n", pin, direction, ret);
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

// Function to set the value of a GPIO pin (0 or 1)
int gpio_set_value(int pin, int value) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s\n", GPIO_CHIP);
        return -1;
    }

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d\n", pin);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line %d value to %d: %d\n", pin, value, ret);
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

// Function to get the value of a GPIO pin
int gpio_get_value(int pin) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int value;
    int ret;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s\n", GPIO_CHIP);
        return -1;
    }

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d\n", pin);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_get_value(line);
    if (ret < 0) {
        fprintf(stderr, "Error getting GPIO line %d value: %d\n", pin, ret);
        gpiod_chip_close(chip);
        return -1;
    }

    value = ret;
    gpiod_chip_close(chip);
    return value;
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Export GPIO pins
    if (gpio_export(GPIO_PIN_1) < 0 || gpio_export(GPIO_PIN_2) < 0) {
        fprintf(stderr, "Failed to export GPIO pins. Exiting.\n");
        return 1;
    }

    // Set GPIO direction to output
    if (gpio_set_direction(GPIO_PIN_1, "out") < 0 || gpio_set_direction(GPIO_PIN_2, "out") < 0) {
        fprintf(stderr, "Failed to set GPIO direction. Exiting.\n");
        gpio_unexport(GPIO_PIN_1);
        gpio_unexport(GPIO_PIN_2);
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO 1 to HIGH
        if (gpio_set_value(GPIO_PIN_1, 1) < 0) {
            fprintf(stderr, "Failed to set GPIO 1 value. Continuing.\n");
        }

        // Get GPIO 1 value
        int value_1 = gpio_get_value(GPIO_PIN_1);
        if (value_1 < 0) {
            fprintf(stderr, "Failed to get GPIO 1 value. Continuing.\n");
        } else {
            printf("GPIO 1: %d\n", value_1);
        }

        // Set GPIO 2 to LOW
        if (gpio_set_value(GPIO_PIN_2, 0) < 0) {
            fprintf(stderr, "Failed to set GPIO 2 value. Continuing.\n");
        }

        // Get GPIO 2 value
        int value_2 = gpio_get_value(GPIO_PIN_2);
        if (value_2 < 0) {
            fprintf(stderr, "Failed to get GPIO 2 value. Continuing.\n");
        } else {
            printf("GPIO 2: %d\n", value_2);
        }

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

