#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the HC-SR04 sensors
#define TRIGGER_PIN_1 17
#define ECHO_PIN_1 27
#define TRIGGER_PIN_2 22
#define ECHO_PIN_2 23
#define TRIGGER_PIN_3 24
#define ECHO_PIN_3 25

// Define the speed of sound in cm/s
#define SPEED_OF_SOUND 34300.0

// Define the timeout for the echo pulse in microseconds
#define TIMEOUT 500000 // 0.5 seconds

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to trigger the HC-SR04 sensor
void triggerSensor(int triggerPin) {
    gpioWrite(triggerPin, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(triggerPin, 0);
}

// Function to measure the echo pulse duration
long measureEcho(int echoPin) {
    long startTime = 0, endTime = 0;

    // Wait for the echo pin to go high (with timeout)
    int count = 0;
    while (gpioRead(echoPin) == 0 && count < TIMEOUT) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= TIMEOUT) {
        fprintf(stderr, "Error: Echo pulse timeout on pin %d\n", echoPin);
        return -1; // Indicate timeout error
    }

    startTime = gpioTick();

    // Wait for the echo pin to go low (with timeout)
    count = 0;
    while (gpioRead(echoPin) == 1 && count < TIMEOUT) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= TIMEOUT) {
        fprintf(stderr, "Error: Echo pulse timeout on pin %d\n", echoPin);
        return -1; // Indicate timeout error
    }

    endTime = gpioTick();

    return endTime - startTime;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulseDuration) {
    if (pulseDuration < 0) {
        return -1.0; // Indicate error
    }
    return (pulseDuration * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 for one-way distance
}

// Function to report the distance to the console
void reportDistance(int sensorNumber, float distance) {
    printf("Sensor %d: Distance = %.2f cm\n", sensorNumber, distance);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as output and input
    gpioSetMode(TRIGGER_PIN_1, PI_OUTPUT);
    gpioSetMode(ECHO_PIN_1, PI_INPUT);
    gpioSetMode(TRIGGER_PIN_2, PI_OUTPUT);
    gpioSetMode(ECHO_PIN_2, PI_INPUT);
    gpioSetMode(TRIGGER_PIN_3, PI_OUTPUT);
    gpioSetMode(ECHO_PIN_3, PI_INPUT);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("HC-SR04 Sensor Interface\n");
    printf("Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Trigger sensors 1, 2, and 3
        triggerSensor(TRIGGER_PIN_1);
        triggerSensor(TRIGGER_PIN_2);
        triggerSensor(TRIGGER_PIN_3);

        // Measure echo pulse durations
        long pulseDuration1 = measureEcho(ECHO_PIN_1);
        long pulseDuration2 = measureEcho(ECHO_PIN_2);
        long pulseDuration3 = measureEcho(ECHO_PIN_3);

        // Calculate distances
        float distance1 = calculateDistance(pulseDuration1);
        float distance2 = calculateDistance(pulseDuration2);
        float distance3 = calculateDistance(pulseDuration3);

        // Report distances
        reportDistance(1, distance1);
        reportDistance(2, distance2);
        reportDistance(3, distance3);

        // Wait for 60 seconds
        sleep(60);
    }

    // Release GPIO resources
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register settings
#define CONFIG_OS_SINGLE 0x8000  // Start a single conversion
#define CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define CONFIG_PGA_4_096V 0x0000 // +/-4.096V range
#define CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define CONFIG_DR_128SPS 0x0080  // 128 SPS
#define CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define CONFIG_COMP_POL_LOW 0x0000 // Active low comparator
#define CONFIG_COMP_LAT_NON 0x0000 // Non-latching comparator
#define CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int ads1115_init(int i2c_fd);
int16_t ads1115_read_conversion(int i2c_fd);
float ads1115_convert_to_voltage(int16_t raw_value);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the ADS1115 ADC
int ads1115_init(int i2c_fd) {
    uint16_t config = CONFIG_OS_SINGLE | CONFIG_MUX_SINGLE_0 | CONFIG_PGA_4_096V | CONFIG_MODE_SINGLE | CONFIG_DR_128SPS | CONFIG_COMP_MODE_TRAD | CONFIG_COMP_POL_LOW | CONFIG_COMP_LAT_NON | CONFIG_COMP_QUE_DISABLE;

    // Write the configuration register
    uint8_t buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    if (write(i2c_fd, buf, 3) != 3) {
        perror("Failed to write to ADS1115 configuration register");
        return -1;
    }

    return 0;
}

// Read the conversion result from the ADS1115
int16_t ads1115_read_conversion(int i2c_fd) {
    uint8_t buf[2];
    buf[0] = ADS1115_REG_CONVERT;

    if (write(i2c_fd, buf, 1) != 1) {
        perror("Failed to write to ADS1115 conversion register for reading");
        return -1;
    }

    if (read(i2c_fd, buf, 2) != 2) {
        perror("Failed to read from ADS1115 conversion register");
        return -1;
    }

    return (int16_t)((buf[0] << 8) | buf[1]);
}

// Convert the raw ADC reading to voltage
float ads1115_convert_to_voltage(int16_t raw_value) {
    // The ADS1115 returns a 16-bit signed integer, left-aligned.
    // The ADC range is +/- 4.096V, so each LSB is 4.096V / 32768.
    return (float)raw_value * 4.096 / 32768.0;
}

int main() {
    // Open I2C device
    char i2c_device[20];
    snprintf(i2c_device, 19, "/dev/i2c-1");
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize the ADS1115 ADC
    if (ads1115_init(i2c_fd) != 0) {
        fprintf(stderr, "ADS1115 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read the conversion result
        int16_t raw_value = ads1115_read_conversion(i2c_fd);

        // Check for read error
        if (raw_value == -1) {
            fprintf(stderr, "Failed to read conversion. Retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Convert the raw value to voltage
        float voltage = ads1115_convert_to_voltage(raw_value);

        // Print the voltage to standard output
        printf("Voltage: %.3f V\n", voltage);

        // Wait for 5 seconds
        sleep(5);
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

