#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define GPIO_DIRECTION "out"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

int main() {
    int ret;
    int value;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set GPIO direction to output
    ret = gpiod_line_request_output(line, GPIO_DIRECTION, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO direction: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        // Read GPIO value
        value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO value: %s\n", strerror(errno));
            break; // Exit loop on error
        }

        // Validate GPIO value
        if (value != 0 && value != 1) {
            fprintf(stderr, "Invalid GPIO value: %d\n", value);
            break; // Exit loop on invalid value
        }

        // Set GPIO value
        ret = gpiod_line_set_value(line, value);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO value: %s\n", strerror(errno));
            break; // Exit loop on error
        }

        // Print GPIO value
        printf("GPIO %d set to %d\n", GPIO_PIN, value);

        // Wait for 1 second
        sleep(1);
    }

    // Release GPIO line
    gpiod_line_release(line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

