#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define GPIO_4 4
#define GPIO_17 17
#define GPIO_22 22
#define GPIO_27 27

// Function prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_write(int pin, int value);
int gpio_read(int pin);
void cleanup(int signal);

// Global variable to track if the program should exit
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void cleanup(int signal) {
    program_running = 0;
    printf("\nCleaning up and exiting...\n");

    // Unexport GPIO pins
    gpio_unexport(GPIO_4);
    gpio_unexport(GPIO_17);
    gpio_unexport(GPIO_22);
    gpio_unexport(GPIO_27);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to export a GPIO pin
int gpio_export(int pin) {
    char buffer[64];
    int len;
    FILE *fp;

    fp = fopen("/sys/class/gpio/export", "w");
    if (fp == NULL) {
        perror("Failed to open /sys/class/gpio/export");
        return -1;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (fwrite(buffer, 1, len, fp) != len) {
        perror("Failed to write to /sys/class/gpio/export");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to unexport a GPIO pin
int gpio_unexport(int pin) {
    char buffer[64];
    int len;
    FILE *fp;

    fp = fopen("/sys/class/gpio/unexport", "w");
    if (fp == NULL) {
        perror("Failed to open /sys/class/gpio/unexport");
        return -1;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (fwrite(buffer, 1, len, fp) != len) {
        perror("Failed to write to /sys/class/gpio/unexport");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to set the direction of a GPIO pin (in or out)
int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    FILE *fp;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    fp = fopen(path, "w");
    if (fp == NULL) {
        perror("Failed to open GPIO direction file");
        return -1;
    }

    if (fprintf(fp, "%s", direction) < 0) {
        perror("Failed to write to GPIO direction file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to write a value to a GPIO pin (0 or 1)
int gpio_write(int pin, int value) {
    char path[64];
    FILE *fp;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fp = fopen(path, "w");
    if (fp == NULL) {
        perror("Failed to open GPIO value file");
        return -1;
    }

    if (fprintf(fp, "%d", value) < 0) {
        perror("Failed to write to GPIO value file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to read a value from a GPIO pin
int gpio_read(int pin) {
    char path[64];
    FILE *fp;
    char value_str[3];

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fp = fopen(path, "r");
    if (fp == NULL) {
        perror("Failed to open GPIO value file for reading");
        return -1;
    }

    if (fread(value_str, 1, 3, fp) < 0) {
        perror("Failed to read from GPIO value file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return atoi(value_str);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, cleanup);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Export GPIO pins
    if (gpio_export(GPIO_4) < 0 ||
        gpio_export(GPIO_17) < 0 ||
        gpio_export(GPIO_22) < 0 ||
        gpio_export(GPIO_27) < 0) {
        gpioTerminate();
        return 1;
    }

    // Set GPIO directions to output
    if (gpio_set_direction(GPIO_4, "out") < 0 ||
        gpio_set_direction(GPIO_17, "out") < 0 ||
        gpio_set_direction(GPIO_22, "out") < 0 ||
        gpio_set_direction(GPIO_27, "out") < 0) {
        gpio_unexport(GPIO_4);
        gpio_unexport(GPIO_17);
        gpio_unexport(GPIO_22);
        gpio_unexport(GPIO_27);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Set GPIO values
        if (gpio_write(GPIO_4, 1) < 0 ||
            gpio_write(GPIO_17, 0) < 0 ||
            gpio_write(GPIO_22, 1) < 0 ||
            gpio_write(GPIO_27, 0) < 0) {
            fprintf(stderr, "Error writing to GPIO pins\n");
            break;
        }

        // Read GPIO values
        int value_4 = gpio_read(GPIO_4);
        int value_17 = gpio_read(GPIO_17);
        int value_22 = gpio_read(GPIO_22);
        int value_27 = gpio_read(GPIO_27);

        if (value_4 < 0 || value_17 < 0 || value_22 < 0 || value_27 < 0) {
            fprintf(stderr, "Error reading from GPIO pins\n");
            break;
        }

        // Print GPIO values
        printf("GPIO 4: %d, GPIO 17: %d, GPIO 22: %d, GPIO 27: %d\n", value_4, value_17, value_22, value_27);

        // Wait for 2 seconds
        sleep(2);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    cleanup(0);

    return 0;
}

