#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_GPIO 2
#define RELAY2_GPIO 3

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the state of a relay
int set_relay_state(int gpio, int state) {
    if (gpioWrite(gpio, state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY2_GPIO, PI_OUTPUT);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop to control the relays
    while (program_running) {
        // Turn on Relay 1
        if (set_relay_state(RELAY1_GPIO, 1) != 0) {
            fprintf(stderr, "Error setting Relay 1 state\n");
            break;
        }
        printf("Relay 1 ON\n");
        sleep(5);

        // Turn off Relay 1
        if (set_relay_state(RELAY1_GPIO, 0) != 0) {
            fprintf(stderr, "Error setting Relay 1 state\n");
            break;
        }
        printf("Relay 1 OFF\n");
        sleep(5);

