#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SI7021_ADDR 0x40
#define MEASURE_TEMP_HOLD 0xE3
#define MEASURE_HUMID_HOLD 0xE5
#define ERROR_VALUE -1.0

// Global variables
int i2c_fd = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_open(const char *bus);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len);
float read_temperature(int fd);
float read_humidity(int fd);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function to open the I2C bus
int i2c_open(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to write a byte to an I2C register
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Function to read bytes from an I2C register
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address for read");
        return -1;
    }
    if (read(fd, buf, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// Function to read temperature from the sensor
float read_temperature(int fd) {
    if (i2c_write_byte(fd, MEASURE_TEMP_HOLD, 0) != 0) {
        fprintf(stderr, "Error writing temperature command\n");
        return ERROR_VALUE;
    }
    usleep(25000); // Wait for measurement (at least 25ms)

    uint8_t buf[2];
    if (i2c_read_bytes(fd, 0, buf, 2) != 0) {
        fprintf(stderr, "Error reading temperature data\n");
        return ERROR_VALUE;
    }

    uint16_t raw_temp = (buf[0] << 8) | buf[1];
    float temperature = (175.72 * raw_temp / 65536.0) - 46.85;
    return temperature;
}

// Function to read humidity from the sensor
float read_humidity(int fd) {
    if (i2c_write_byte(fd, MEASURE_HUMID_HOLD, 0) != 0) {
        fprintf(stderr, "Error writing humidity command\n");
        return ERROR_VALUE;
    }
    usleep(25000); // Wait for measurement (at least 25ms)

    uint8_t buf[2];
    if (i2c_read_bytes(fd, 0, buf, 2) != 0) {
        fprintf(stderr, "Error reading humidity data\n");
        return ERROR_VALUE;
    }

    uint16_t raw_humidity = (buf[0] << 8) | buf[1];
    float humidity = (125.0 * raw_humidity / 65536.0) - 6.0;
    return humidity;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = i2c_open(I2C_BUS);
    if (i2c_fd < 0) {
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read temperature and humidity
        float temperature = read_temperature(i2c_fd);
        float humidity = read_humidity(i2c_fd);

        // Check for errors
        if (temperature == ERROR_VALUE || humidity == ERROR_VALUE) {
            fprintf(stderr, "Error reading sensor data. Skipping this iteration.\n");
        } else {
            // Print the data
            printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register settings
#define CONFIG_OS_SINGLE 0x8000  // Start a single conversion
#define CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define CONFIG_PGA_4_096V 0x0000 // +/-4.096V range
#define CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define CONFIG_DR_128SPS 0x0080  // 128 SPS
#define CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define CONFIG_COMP_POL_LOW 0x0000 // Active low comparator
#define CONFIG_COMP_LAT_NON 0x0000 // Non-latching comparator
#define CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a byte to an ADS1115 register
int write_register(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;

    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read a word from an ADS1115 register
int read_register(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[1];
    buf[0] = reg;

    if (write(fd, buf, 1) != 1) {
        fprintf(stderr, "Error writing register address for reading: %s\n", strerror(errno));
        return -1;
    }

    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    *value = (buf[0] << 8) | buf[1];
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Specify slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Configure ADS1115 for single-shot mode, +/-4.096V range, 128 SPS
    uint16_t config_value = CONFIG_OS_SINGLE | CONFIG_MUX_SINGLE_0 | CONFIG_PGA_4_096V | CONFIG_MODE_SINGLE | CONFIG_DR_128SPS | CONFIG_COMP_MODE_TRAD | CONFIG_COMP_POL_LOW | CONFIG_COMP_LAT_NON | CONFIG_COMP_QUE_DISABLE;
    if (write_register(i2c_fd, ADS1115_REG_CONFIG, config_value) != 0) {
        fprintf(stderr, "Error configuring ADS1115\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        uint16_t conversion_value;
        if (read_register(i2c_fd, ADS1115_REG_CONVERT, &conversion_value) == 0) {
            // Convert raw value to voltage (assuming +/-4.096V range)
            float voltage = (float)conversion_value * 4.096 / 32768.0;
            printf("Voltage: %.3f V\n", voltage);
        } else {
            fprintf(stderr, "Error reading conversion value\n");
        }

        sleep(1);
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness and to avoid compiler warnings.
    close(i2c_fd);
    return 0;
}

