        fprintf(stderr, "Error opening GPIO chip: %m\n");
        return 1;
    }

    // Get GPIO lines
    struct gpiod_line *line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    struct gpiod_line *line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
