    if (!line1 || !line2 || !line3 || !line4 || !line5 || !line6) {
        fprintf(stderr, "Error getting GPIO line: %m\n");
        goto cleanup;
    }

    // Request GPIO lines as output
    int ret = gpiod_line_request_output(line1, "gpio_control", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %d\n", ret);
        goto cleanup;
    }
    ret = gpiod_line_request_output(line2, "gpio_control", 0);
