    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %d\n", ret);
        goto cleanup;
    }
    ret = gpiod_line_request_output(line4, "gpio_control", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %d\n", ret);
        goto cleanup;
    }
    ret = gpiod_line_request_output(line5, "gpio_control", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %d\n", ret);
        goto cleanup;
    }
    ret = gpiod_line_request_output(line6, "gpio_control", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %d\n", ret);
        goto cleanup;
    }

    // Main loop
    for (int i = 0; i < CYCLES && program_running; i++) {
        // Set GPIO states
        if (set_gpio_state(line1, 1) < 0) goto cleanup;
        if (set_gpio_state(line2, 0) < 0) goto cleanup;
        if (set_gpio_state(line3, 1) < 0) goto cleanup;
        if (set_gpio_state(line4, 0) < 0) goto cleanup;
        if (set_gpio_state(line5, 1) < 0) goto cleanup;
        if (set_gpio_state(line6, 0) < 0) goto cleanup;

        // Read GPIO states
        int state1 = read_gpio_state(line1);
        int state2 = read_gpio_state(line2);
        int state3 = read_gpio_state(line3);
        int state4 = read_gpio_state(line4);
        int state5 = read_gpio_state(line5);
        int state6 = read_gpio_state(line6);

        if (state1 < 0 || state2 < 0 || state3 < 0 || state4 < 0 || state5 < 0 || state6 < 0) {
            fprintf(stderr, "Error reading GPIO states, exiting...\n");
