        printf("GPIO %d: %d, GPIO %d: %d, GPIO %d: %d, GPIO %d: %d, GPIO %d: %d, GPIO %d: %d\n",
               GPIO_PIN_1, state1, GPIO_PIN_2, state2, GPIO_PIN_3, state3,
               GPIO_PIN_4, state4, GPIO_PIN_5, state5, GPIO_PIN_6, state6);

        // Delay for 100 milliseconds
        usleep(100000); // 100 milliseconds = 100000 microseconds
    }

cleanup:
