    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO state: %d\n", value);
        return -1;
    }
    return value;
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open GPIO lines
    struct gpiod_chip *chip;
