    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_17, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line18) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_18, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(line17);
        return 1;
    }

    line27 = gpiod_chip_get_line(chip, GPIO_27);
    if (!line27) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_27, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        return 1;
    }

    // Request GPIO lines as output
    if (gpiod_line_request_output(line17, "gpio_control", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_17, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        gpiod_line_release(line27);
        return 1;
    }

