#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the LEDs
#define LED1_PIN 2
#define LED2_PIN 3

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the state of an LED
int set_led_state(int gpio_pin, int state) {
    if (gpioWrite(gpio_pin, state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", gpio_pin);
        return -1;
    }
    return 0;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(LED1_PIN, PI_OUTPUT);
    gpioSetMode(LED2_PIN, PI_OUTPUT);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("LED control program started. Press Ctrl+C to exit.\n");

    // Main loop to control the LEDs
    while (program_running) {
        // Set LED 1 to HIGH
        if (set_led_state(LED1_PIN, 1) != 0) {
            fprintf(stderr, "Error setting LED 1 state, exiting.\n");
            break;
        }
        printf("LED 1 set to HIGH\n");

        // Wait for 0.5 seconds
        gpioDelay(500000); // 500 milliseconds

        // Set LED 1 to LOW
        if (set_led_state(LED1_PIN, 0) != 0) {
            fprintf(stderr, "Error setting LED 1 state, exiting.\n");
            break;
        }
        printf("LED 1 set to LOW\n");

        // Wait for 0.5 seconds
        gpioDelay(500000); // 500 milliseconds
    }

    // Clean up and exit
    gpioWrite(LED1_PIN, 0); // Turn off LED 1
    gpioWrite(LED2_PIN, 0); // Turn off LED 2
    gpioTerminate(); // Terminate the pigpio library
    printf("Program terminated.\n");
    return 0;
}

