#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the HC-SR04 sensors
#define TRIGGER_PIN_1 17
#define ECHO_PIN_1 18
#define TRIGGER_PIN_2 22
#define ECHO_PIN_2 23
#define TRIGGER_PIN_3 24
#define ECHO_PIN_3 25

// Define the speed of sound in cm/s
#define SPEED_OF_SOUND 34300.0

// Define the timeout for the echo pulse in microseconds
#define TIMEOUT 500000 // 0.5 seconds

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to trigger the HC-SR04 sensor
void trigger_sensor(int trigger_pin) {
    gpioWrite(trigger_pin, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(trigger_pin, 0);
}

// Function to measure the echo pulse duration
long measure_pulse_duration(int echo_pin) {
    long start_tick = 0, end_tick = 0;

    // Wait for the echo pin to go high (with timeout)
    int timeout_count = 0;
    while (gpioRead(echo_pin) == 0 && timeout_count < TIMEOUT) {
        timeout_count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (timeout_count >= TIMEOUT) {
        fprintf(stderr, "Error: Echo pin %d did not go high (timeout).\n", echo_pin);
        return -1; // Indicate timeout error
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low (with timeout)
    timeout_count = 0;
    while (gpioRead(echo_pin) == 1 && timeout_count < TIMEOUT) {
        timeout_count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (timeout_count >= TIMEOUT) {
        fprintf(stderr, "Error: Echo pin %d did not go low (timeout).\n", echo_pin);
        return -1; // Indicate timeout error
    }

    end_tick = gpioTick();

    return end_tick - start_tick;
}

// Function to calculate the distance in centimeters
float calculate_distance(long pulse_duration) {
    if (pulse_duration < 0) {
        return -1.0; // Indicate error
    }
    return (float)pulse_duration * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN_1, PI_OUTPUT);
    gpioSetMode(ECHO_PIN_1, PI_INPUT);
    gpioSetMode(TRIGGER_PIN_2, PI_OUTPUT);
    gpioSetMode(ECHO_PIN_2, PI_INPUT);
    gpioSetMode(TRIGGER_PIN_3, PI_OUTPUT);
    gpioSetMode(ECHO_PIN_3, PI_INPUT);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("HC-SR04 Sensor Interface\n");
    printf("Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Trigger sensors
        trigger_sensor(TRIGGER_PIN_1);
        trigger_sensor(TRIGGER_PIN_2);
        trigger_sensor(TRIGGER_PIN_3);

        // Measure pulse durations
        long pulse_duration_1 = measure_pulse_duration(ECHO_PIN_1);
        long pulse_duration_2 = measure_pulse_duration(ECHO_PIN_2);
        long pulse_duration_3 = measure_pulse_duration(ECHO_PIN_3);

        // Calculate distances
        float distance_1 = calculate_distance(pulse_duration_1);
        float distance_2 = calculate_distance(pulse_duration_2);
        float distance_3 = calculate_distance(pulse_duration_3);

        // Print sensor readings
        printf("Sensor 1: Distance = %.2f cm, Pulse Duration = %ld us\n", distance_1, pulse_duration_1);
        printf("Sensor 2: Distance = %.2f cm, Pulse Duration = %ld us\n", distance_2, pulse_duration_2);
        printf("Sensor 3: Distance = %.2f cm, Pulse Duration = %ld us\n", distance_3, pulse_duration_3);

        // Wait for 1 second
        gpioDelay(1000); // 1000 ms = 1 second
    }

    // Release GPIO resources
    gpioTerminate();

    return 0;
}

