// Function to set the state of a GPIO pin
int set_gpio_state(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO state: %d\n", ret);
        return -1;
    }
    return 0;
}

// Function to read the state of a GPIO pin
int read_gpio_state(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO state: %d\n", value);
        return -1;
    }
    return value;
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %m\n");
        return 1;
    }

    // Get GPIO lines
    struct gpiod_line *line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    struct gpiod_line *line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    struct gpiod_line *line3 = gpiod_chip_get_line(chip, GPIO_PIN_3);

    if (!line1 || !line2 || !line3) {
        fprintf(stderr, "Error getting GPIO line: %m\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines as output
    int ret = gpiod_line_request_output(line1, "gpio_control", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %d\n", ret);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line2, "gpio_control", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %d\n", ret);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line3, "gpio_control", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %d\n", ret);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Set GPIO states
        if (set_gpio_state(line1, 1) < 0) {
            break;
        }
        if (set_gpio_state(line2, 0) < 0) {
            break;
        }
        if (set_gpio_state(line3, 1) < 0) {
            break;
        }

        // Read GPIO states
        int state1 = read_gpio_state(line1);
        int state2 = read_gpio_state(line2);
        int state3 = read_gpio_state(line3);

        if (state1 < 0 || state2 < 0 || state3 < 0) {
            break;
        }

        // Print GPIO states
        printf("GPIO %d: %d, GPIO %d: %d, GPIO %d: %d\n", GPIO_PIN_1, state1, GPIO_PIN_2, state2, GPIO_PIN_3, state3);

        // Wait for 0.1 seconds
        usleep(100000); // 100 milliseconds
    }

    // Release GPIO lines
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_line_release(line3);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 17

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int gpio_handle;
    int gpio_value;

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as output
    gpio_handle = gpioSetMode(GPIO_PIN, PI_OUTPUT);
    if (gpio_handle < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    printf("GPIO %d set as output. Press Ctrl+C to exit.\n", GPIO_PIN);

    // Main loop to control the GPIO pin
    while (program_running) {
        // Set GPIO 17 HIGH
        gpio_value = gpioWrite(GPIO_PIN, 1);
        if (gpio_value < 0) {
            fprintf(stderr, "Failed to write HIGH to GPIO %d\n", GPIO_PIN);
            break;
        }
        printf("GPIO %d set HIGH\n", GPIO_PIN);

        // Wait for 0.001 seconds
        gpioDelay(100000); // 100000 microseconds = 0.001 seconds

        // Set GPIO 17 LOW
        gpio_value = gpioWrite(GPIO_PIN, 0);
        if (gpio_value < 0) {
            fprintf(stderr, "Failed to write LOW to GPIO %d\n", GPIO_PIN);
            break;
        }
        printf("GPIO %d set LOW\n", GPIO_PIN);

        // Wait for 0.001 seconds
        gpioDelay(100000); // 100000 microseconds = 0.001 seconds
    }

    // Release GPIO 17 on exit
    gpioWrite(GPIO_PIN, 0); // Ensure it's LOW
    gpioTerminate();

    printf("GPIO %d released. Exiting.\n", GPIO_PIN);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the LEDs
#define LED_PIN_1 2
#define LED_PIN_2 3

// Define the valid range for the LED states
#define MIN_LED_STATE 0
#define MAX_LED_STATE 1

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(LED_PIN_1, PI_OUTPUT);
    gpioSetMode(LED_PIN_2, PI_OUTPUT);

    return 0;
}

// Function to set the state of an LED
int set_led_state(int pin, int state) {
    if (state != MIN_LED_STATE && state != MAX_LED_STATE) {
        fprintf(stderr, "Invalid LED state: %d\n", state);
        return -1;
    }

    gpioWrite(pin, state);
    return 0;
}

// Function to validate the LED state
int validate_led_state(int state) {
    return (state == MIN_LED_STATE || state == MAX_LED_STATE);
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    gpioWrite(LED_PIN_1, 0); // Turn off LEDs
    gpioWrite(LED_PIN_2, 0);
    gpioTerminate();
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("LED control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Generate random LED states
        int led_state_1 = rand() % 2; // 0 or 1
        int led_state_2 = rand() % 2; // 0 or 1

        // Validate LED states
        if (!validate_led_state(led_state_1) || !validate_led_state(led_state_2)) {
            fprintf(stderr, "Invalid LED state(s) generated. Skipping this iteration.\n");
            sleep(5); // Wait 5 seconds before next iteration
            continue;
        }

        // Set LED states
        if (set_led_state(LED_PIN_1, led_state_1) != 0) {
            fprintf(stderr, "Error setting LED state on pin %d\n", LED_PIN_1);
        }
        if (set_led_state(LED_PIN_2, led_state_2) != 0) {
            fprintf(stderr, "Error setting LED state on pin %d\n", LED_PIN_2);
        }

        // Print the LED states to standard output
        printf("LED 1: %d, LED 2: %d\n", led_state_1, led_state_2);

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    printf("Program terminated.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 23
#define GPIO_DIRECTION "out"

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int main() {
    int ret;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIO_CHIP);
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %d\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set GPIO direction to output
    ret = gpiod_line_request_output(line, GPIO_DIRECTION, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO direction: %d\n", ret);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("GPIO %d set to output. Press Ctrl+C to exit.\n", GPIO_PIN);

    // Main loop
    while (!terminate) {
        // Set GPIO high
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO value: %d\n", ret);
            break;
        }
        printf("GPIO %d set to HIGH\n", GPIO_PIN);

        // Wait for 2 seconds
        sleep(2);

        // Set GPIO low
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO value: %d\n", ret);
            break;
        }
        printf("GPIO %d set to LOW\n", GPIO_PIN);

        // Wait for 2 seconds
        sleep(2);
    }

    // Release GPIO line
    gpiod_line_release(line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    printf("GPIO %d released and chip closed.\n", GPIO_PIN);

    return 0;
}

