#include <unistd.h>
#include <gpiod.h>

#define GPIO_PIN 2
#define GPIO_PIN_3 3

struct gpiod_chip *chip;
struct gpiod_line *line;
struct gpiod_line *line3;

void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (line) {
        gpiod_line_release(line);
    }
    if (line3) {
        gpiod_line_release(line3);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main() {
    int ret;
    int i;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %m\n");
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %m\n", GPIO_PIN, chip);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(line, "gpio_control", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output: %m\n", GPIO_PIN, chip);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Get GPIO line 3
    line3 = gpiod_chip_get_line(chip, GPIO_PIN_3);
