// Function to read data from the DHT11 sensor
int read_dht11(int gpio, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int laststate = PI_HIGH;
    int j = 0;

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, PI_HIGH);
    gpioDelay(500); // > 1ms
    gpioWrite(gpio, PI_LOW);
    gpioDelay(20); // 20us
    gpioWrite(gpio, PI_HIGH);
    gpioSetMode(gpio, PI_INPUT);

    // Wait for the DHT11 to pull the line low
    int timeout = 0;
    while (gpioRead(gpio) == PI_HIGH) {
        timeout++;
        if (timeout > DHT11_TIMEOUT) {
            fprintf(stderr, "DHT11 timeout waiting for start signal\n");
            return -1; // Timeout error
        }
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    // Wait for the DHT11 to pull the line high
    timeout = 0;
    while (gpioRead(gpio) == PI_LOW) {
        timeout++;
        if (timeout > DHT11_TIMEOUT) {
            fprintf(stderr, "DHT11 timeout waiting for end signal\n");
            return -1; // Timeout error
        }
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    // Read 40 bits of data
    for (int i = 0; i < 40; i++) {
        timeout = 0;
        while (gpioRead(gpio) == PI_LOW) {
            timeout++;
            if (timeout > DHT11_TIMEOUT) {
                fprintf(stderr, "DHT11 timeout waiting for bit start\n");
                return -1; // Timeout error
            }
            gpioDelay(1); // Small delay to prevent busy-waiting
        }

        // Measure the length of the high pulse
        timeout = 0;
        while (gpioRead(gpio) == PI_HIGH) {
            timeout++;
            if (timeout > DHT11_TIMEOUT) {
                fprintf(stderr, "DHT11 timeout waiting for bit end\n");
                return -1; // Timeout error
            }
            gpioDelay(1); // Small delay to prevent busy-waiting
        }

        // Determine if the pulse was long (50us) or short (26-70us)
        if (timeout > 40) {
            data[j / 8] |= (1 << (7 - (j % 8)));
        }
        j++;
    }

    // Verify checksum
    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        fprintf(stderr, "DHT11 checksum error\n");
        return -1; // Checksum error
    }

    // Convert data to temperature and humidity
    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature *= -1;
    }

    return 0; // Success
}

