        fprintf(stderr, "Error getting GPIO line %d value: %d\n", pin, ret);
        gpiod_chip_close(chip);
        return -1;
    }

    value = ret;
    gpiod_chip_close(chip);
    return value;
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Export GPIO pins
