#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define GPIO_4 4
#define GPIO_17 17
#define GPIO_18 18
#define GPIO_22 22
#define GPIO_27 27

// Function prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_write(int pin, int value);
void signal_handler(int signal);

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to export a GPIO pin
int gpio_export(int pin) {
    char buffer[64];
    int len;
    FILE *fp;

    fp = fopen("/sys/class/gpio/export", "w");
    if (fp == NULL) {
        perror("Failed to open /sys/class/gpio/export");
        return -1;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (fwrite(buffer, 1, len, fp) != len) {
        perror("Failed to write to /sys/class/gpio/export");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to unexport a GPIO pin
int gpio_unexport(int pin) {
    char buffer[64];
    int len;
    FILE *fp;

    fp = fopen("/sys/class/gpio/unexport", "w");
    if (fp == NULL) {
        perror("Failed to open /sys/class/gpio/unexport");
        return -1;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (fwrite(buffer, 1, len, fp) != len) {
        perror("Failed to write to /sys/class/gpio/unexport");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to set the direction of a GPIO pin (in or out)
int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    FILE *fp;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    fp = fopen(path, "w");
    if (fp == NULL) {
        perror("Failed to open GPIO direction file");
        return -1;
    }

    if (fprintf(fp, "%s", direction) < 0) {
        perror("Failed to write to GPIO direction file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to write a value to a GPIO pin (0 or 1)
int gpio_write(int pin, int value) {
    char path[64];
    FILE *fp;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fp = fopen(path, "w");
    if (fp == NULL) {
        perror("Failed to open GPIO value file");
        return -1;
    }

    if (fprintf(fp, "%d", value) < 0) {
        perror("Failed to write to GPIO value file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Export GPIO pins
    if (gpio_export(GPIO_4) != 0 ||
        gpio_export(GPIO_17) != 0 ||
        gpio_export(GPIO_18) != 0 ||
        gpio_export(GPIO_22) != 0 ||
        gpio_export(GPIO_27) != 0) {
        fprintf(stderr, "Failed to export GPIO pins\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO directions to output
    if (gpio_set_direction(GPIO_4, "out") != 0 ||
        gpio_set_direction(GPIO_17, "out") != 0 ||
        gpio_set_direction(GPIO_18, "out") != 0 ||
        gpio_set_direction(GPIO_22, "out") != 0 ||
        gpio_set_direction(GPIO_27, "out") != 0) {
        fprintf(stderr, "Failed to set GPIO directions\n");
        gpio_unexport(GPIO_4);
        gpio_unexport(GPIO_17);
        gpio_unexport(GPIO_18);
        gpio_unexport(GPIO_22);
        gpio_unexport(GPIO_27);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Set GPIO values
        if (gpio_write(GPIO_4, 1) != 0 ||
            gpio_write(GPIO_17, 1) != 0 ||
            gpio_write(GPIO_18, 1) != 0 ||
            gpio_write(GPIO_22, 1) != 0 ||
            gpio_write(GPIO_27, 1) != 0) {
            fprintf(stderr, "Failed to write to GPIO pins\n");
            break;
        }

        // Wait for 0.05 seconds
        gpioDelay(500000); // 500ms

        // Set GPIO values
        if (gpio_write(GPIO_4, 0) != 0 ||
            gpio_write(GPIO_17, 0) != 0 ||
            gpio_write(GPIO_18, 0) != 0 ||
            gpio_write(GPIO_22, 0) != 0 ||
            gpio_write(GPIO_27, 0) != 0) {
            fprintf(stderr, "Failed to write to GPIO pins\n");
            break;
        }

        // Wait for 0.05 seconds
        gpioDelay(500000); // 500ms
    }

    // Unexport GPIO pins before exiting
    gpio_unexport(GPIO_4);
    gpio_unexport(GPIO_17);
    gpio_unexport(GPIO_18);
    gpio_unexport(GPIO_22);
    gpio_unexport(GPIO_27);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

#include <stdio.h>
