#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for PWM output
#define PWM_PIN_1 2
#define PWM_PIN_2 3
#define PWM_PIN_3 18

// PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// PWM range (0-255)
#define PWM_RANGE 255

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_PIN_1, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_2, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_3, PWM_RANGE);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Set PWM duty cycle for GPIO 2 (50%)
        gpioPWM(PWM_PIN_2, 128);

        // Set PWM duty cycle for GPIO 3 (75%)
        gpioPWM(PWM_PIN_3, 191);

        // Set PWM duty cycle for GPIO 18 (25%)
        gpioPWM(PWM_PIN_1, 64);

        // Wait for 0.15 seconds
        gpioDelay(150000); // 150000 microseconds = 0.15 seconds
    }

    // Stop PWM output on all GPIO pins
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);

    // Release GPIO pins
    gpioSetMode(PWM_PIN_1, PI_INPUT); // Set to input to avoid floating
    gpioSetMode(PWM_PIN_2, PI_INPUT);
    gpioSetMode(PWM_PIN_3, PI_INPUT);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

