// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the state of an LED
int set_led_state(int gpio_pin, int state) {
    if (gpioWrite(gpio_pin, state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", gpio_pin);
        return -1;
    }
    return 0;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(LED_PIN_1, PI_OUTPUT);
    gpioSetMode(LED_PIN_2, PI_OUTPUT);
    gpioSetMode(LED_PIN_3, PI_OUTPUT);
    gpioSetMode(LED_PIN_4, PI_OUTPUT);
    gpioSetMode(LED_PIN_5, PI_OUTPUT);
    gpioSetMode(LED_PIN_6, PI_OUTPUT);
    gpioSetMode(LED_PIN_7, PI_OUTPUT);
    gpioSetMode(LED_PIN_8, PI_OUTPUT);
    gpioSetMode(LED_PIN_9, PI_OUTPUT);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop to control the LEDs
    while (program_running) {
        // Turn on all LEDs
        if (set_led_state(LED_PIN_1, 1) != 0) goto cleanup;
        if (set_led_state(LED_PIN_2, 1) != 0) goto cleanup;
        if (set_led_state(LED_PIN_3, 1) != 0) goto cleanup;
        if (set_led_state(LED_PIN_4, 1) != 0) goto cleanup;
        if (set_led_state(LED_PIN_5, 1) != 0) goto cleanup;
        if (set_led_state(LED_PIN_6, 1) != 0) goto cleanup;
        if (set_led_state(LED_PIN_7, 1) != 0) goto cleanup;
        if (set_led_state(LED_PIN_8, 1) != 0) goto cleanup;
        if (set_led_state(LED_PIN_9, 1) != 0) goto cleanup;

        // Wait for 0.05 seconds
        gpioDelay(500000); // 500ms

        // Turn off all LEDs
        if (set_led_state(LED_PIN_1, 0) != 0) goto cleanup;
        if (set_led_state(LED_PIN_2, 0) != 0) goto cleanup;
        if (set_led_state(LED_PIN_3, 0) != 0) goto cleanup;
        if (set_led_state(LED_PIN_4, 0) != 0) goto cleanup;
        if (set_led_state(LED_PIN_5, 0) != 0) goto cleanup;
        if (set_led_state(LED_PIN_6, 0) != 0) goto cleanup;
        if (set_led_state(LED_PIN_7, 0) != 0) goto cleanup;
        if (set_led_state(LED_PIN_8, 0) != 0) goto cleanup;
        if (set_led_state(LED_PIN_9, 0) != 0) goto cleanup;

        // Wait for 0.05 seconds
        gpioDelay(500000);
    }

cleanup:
    // Release GPIO pins
    gpioTerminate();

    return 0;
}

