#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define OPT3001_ADDR 0x44

// Define the register addresses
#define RESULT_REG 0x00
#define CONFIG_REG 0x01

// Define the configuration register values
#define CONFIG_CONTINUOUS 0x8000 // Continuous conversion mode
#define CONFIG_100MS_RES 0x0000 // 100ms conversion time, 12-bit resolution

// Global variable for the I2C file descriptor
int i2c_fd = -1;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the OPT3001 sensor
int init_opt3001() {
    // Configure the OPT3001 for continuous conversion mode and 100ms resolution
    uint16_t config_value = CONFIG_CONTINUOUS | CONFIG_100MS_RES;

    // Write the configuration value to the configuration register
    if (write_register(CONFIG_REG, config_value) != 0) {
        fprintf(stderr, "Error writing to configuration register.\n");
        return -1;
    }

    return 0;
}

// Function to read the result from the OPT3001 sensor
int read_opt3001(int *result) {
    uint16_t raw_result;

    // Read the result register
    if (read_register(RESULT_REG, &raw_result) != 0) {
        fprintf(stderr, "Error reading from result register.\n");
        return -1;
    }

    // Convert the raw result to millivolts
    *result = (int)((raw_result >> 4) * 0.0625);

    return 0;
}

// Function to write a value to a specific register
int write_register(uint8_t reg, uint16_t value) {
    uint8_t buffer[3];
    buffer[0] = reg;
    buffer[1] = (value >> 8) & 0xFF; // MSB
    buffer[2] = value & 0xFF;       // LSB

    if (write(i2c_fd, buffer, 3) != 3) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read a value from a specific register
int read_register(uint8_t reg, uint16_t *value) {
    uint8_t buffer[1];
    buffer[0] = reg;

    if (write(i2c_fd, buffer, 1) != 1) {
        fprintf(stderr, "Error writing register address for reading: %s\n", strerror(errno));
        return -1;
    }

    if (read(i2c_fd, buffer, 2) != 2) {
