        return 1;
    }
    if (gpio_export(GPIO_PIN_2) < 0) {
        fprintf(stderr, "Error: Failed to export GPIO %d\n", GPIO_PIN_2);
        gpio_unexport(GPIO_PIN_1);
        return 1;
    }

    // Set GPIO direction to output
    if (gpio_set_direction(GPIO_PIN_1, "out") < 0) {
        fprintf(stderr, "Error: Failed to set direction for GPIO %d\n", GPIO_PIN_1);
        gpio_unexport(GPIO_PIN_1);
