        // Print the values
        printf("GPIO %d: %d, GPIO %d: %d\n", GPIO_PIN_1, value_1, GPIO_PIN_2, value_2);

        // Wait for 1 second
        sleep(1);
    }

    // Unexport GPIO pins on exit
    gpio_unexport(GPIO_PIN_1);
    gpio_unexport(GPIO_PIN_2);

    return 0;
}

