#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define UART_DEVICE "/dev/ttyS0" // Or /dev/ttyAMA0
#define BAUD_RATE B9600
#define DATA_BITS 8
#define STOP_BITS 1
#define PARITY_NONE 'N'

int uart_fd = -1;
volatile sig_atomic_t program_running = 1;

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signum);
}

// Function to initialize the UART port
int init_uart(const char *device, speed_t baud_rate, int data_bits, int stop_bits, char parity) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 8N1, no parity, ignore modem controls
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0; // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read doesn't block
    tty.c_cc[VTIME] = 5; // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read data from the UART port
int read_uart_data(int fd, char *buffer, size_t buffer_size) {
    ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
    if (bytes_read == -1) {
        perror("Error reading from UART port");
        return -1;
    } else if (bytes_read == 0) {
        // No data available
        return 0;
    } else {
        buffer[bytes_read] = '\0'; // Null-terminate the buffer
        return bytes_read;
    }
}

// Function to write data to the UART port
int write_uart_data(int fd, const char *data) {
    ssize_t bytes_written = write(fd, data, strlen(data));
    if (bytes_written == -1) {
        perror("Error writing to UART port");
        return -1;
    }
    return bytes_written;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    uart_fd = init_uart(UART_DEVICE, BAUD_RATE, DATA_BITS, STOP_BITS, PARITY_NONE);
    if (uart_fd == -1) {
        fprintf(stderr, "UART initialization failed. Exiting.\n");
        return 1;
    }

    char buffer[256];
    int bytes_read;

    printf("UART initialized. Reading data from %s...\n", UART_DEVICE);

    while (program_running) {
        bytes_read = read_uart_data(uart_fd, buffer, sizeof(buffer));
        if (bytes_read > 0) {
            printf("Received: %s", buffer);
            // Simulate sending data back to the device
            if (write_uart_data(uart_fd, buffer) != bytes_read) {
                fprintf(stderr, "Error sending data back to device.\n");
            }
        } else if (bytes_read < 0) {
            // Error already handled by read_uart_data
            break; // Exit loop on error
        }
        usleep(100000); // Sleep for 100ms
    }

    // Close UART port
    if (uart_fd != -1) {
        close(uart_fd);
    }

    printf("UART port closed. Exiting.\n");
    return 0;
}

