#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

// Define the GPIO pin connected to the output
#define GPIO_PIN 2

// Define the valid range for the GPIO pin
#define GPIO_MIN_VALUE 0
#define GPIO_MAX_VALUE 1

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Ensure the pin is initially low

    return 0;
}

// Function to read the GPIO pin value
int read_gpio_value() {
    int value = gpioRead(GPIO_PIN);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO value\n");
        return -1; // Indicate an error
    }
    return value;
}

// Function to validate the GPIO pin value
int validate_gpio_value(int value) {
    if (value != GPIO_MIN_VALUE && value != GPIO_MAX_VALUE) {
        fprintf(stderr, "Invalid GPIO value: %d\n", value);
        return -1; // Indicate an error
    }
    return 0; // Indicate success
}

// Function to apply the GPIO pin value
void apply_gpio_value(int value) {
    gpioWrite(GPIO_PIN, value);
}

// Function to cleanup the GPIO pin
void cleanup_gpio() {
    gpioWrite(GPIO_PIN, 0); // Ensure the pin is low before exiting
    gpioTerminate();
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the GPIO pin
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("GPIO control program started. Press Ctrl+C to exit.\n");

    // Main loop to control the GPIO pin
    while (program_running) {
        // Generate a random value between 0 and 1
        int random_value = rand() % 2;

        // Validate the generated value
        if (validate_gpio_value(random_value) == 0) {
            // Apply the generated value to the GPIO pin
            apply_gpio_value(random_value);

            // Print the generated value to the console
            printf("GPIO value set to: %d\n", random_value);
        } else {
            fprintf(stderr, "Invalid GPIO value generated, skipping.\n");
        }

        // Wait for 60 seconds
        sleep(60);
    }

    // Cleanup the GPIO pin before exiting
    cleanup_gpio();

    return 0;
}

