// Define GPIO pins
#define GPIO_PIN_1 2
#define GPIO_PIN_2 3

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Global variables for GPIO lines
struct gpiod_line *gpio_line_1 = NULL;
struct gpiod_line *gpio_line_2 = NULL;

// Function prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_set_value(int pin, int value);
int gpio_get_value(int pin);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Unexport GPIO pins
    if (gpio_line_1) {
        gpiod_line_release(gpio_line_1);
    }
    if (gpio_line_2) {
        gpiod_line_release(gpio_line_2);
    }

    // Close GPIO chip
    gpiod_chip_close(gpio_line_1 ? gpio_line_1->chip : NULL);
    gpiod_chip_close(gpio_line_2 ? gpio_line_2->chip : NULL);

    exit(0);
}

// Function to export a GPIO pin
int gpio_export(int pin) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip %s\n", GPIO_CHIP);
        return -1;
    }

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get GPIO line %d\n", pin);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(line, "gpio_control", 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d as output\n", pin);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    gpio_line_1 = line; // Store the line for cleanup

    return 0;
}

// Function to unexport a GPIO pin
int gpio_unexport(int pin) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
