        return -1;
    }

    ret = gpiod_line_release(line);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not release GPIO line %d\n", pin);
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

