#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define GPIO_17 17
#define GPIO_22 22
#define GPIO_27 27

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to set the state of a GPIO pin
int set_gpio_state(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO state: %d\n", ret);
        return -1;
    }
    return 0;
}

// Function to export a GPIO pin
int export_gpio(struct gpiod_chip *chip, int pin) {
    int ret = gpiod_chip_export_line(chip, pin);
    if (ret < 0) {
        fprintf(stderr, "Error exporting GPIO %d: %d\n", pin, ret);
        return -1;
    }
    return 0;
}

// Function to unexport a GPIO pin
int unexport_gpio(struct gpiod_chip *chip, int pin) {
    int ret = gpiod_chip_unexport_line(chip, pin);
    if (ret < 0) {
        fprintf(stderr, "Error unexporting GPIO %d: %d\n", pin, ret);
        return -1;
    }
    return 0;
}

// Function to open a GPIO line
struct gpiod_line *open_gpio_line(struct gpiod_chip *chip, int pin) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d\n", pin);
        return NULL;
    }
    return line;
}

// Function to set the direction of a GPIO line
int set_gpio_direction(struct gpiod_line *line, const char *direction) {
    int ret = gpiod_line_set_direction(line, direction);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO direction to %s: %d\n", direction, ret);
        return -1;
    }
    return 0;
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return 1;
    }

    // Export GPIO pins
    if (export_gpio(chip, GPIO_17) || export_gpio(chip, GPIO_22) || export_gpio(chip, GPIO_27)) {
        gpiod_chip_close(chip);
        return 1;
    }

    // Open GPIO lines
    struct gpiod_line *line_17 = open_gpio_line(chip, GPIO_17);
    struct gpiod_line *line_22 = open_gpio_line(chip, GPIO_22);
    struct gpiod_line *line_27 = open_gpio_line(chip, GPIO_27);

    if (!line_17 || !line_22 || !line_27) {
        unexport_gpio(chip, GPIO_17);
        unexport_gpio(chip, GPIO_22);
        unexport_gpio(chip, GPIO_27);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set GPIO directions to output
    if (set_gpio_direction(line_17, "out") || set_gpio_direction(line_22, "out") || set_gpio_direction(line_27, "out")) {
        unexport_gpio(chip, GPIO_17);
        unexport_gpio(chip, GPIO_22);
        unexport_gpio(chip, GPIO_27);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Set GPIO states
        if (set_gpio_state(line_17, 1) || set_gpio_state(line_22, 0) || set_gpio_state(line_27, 1)) {
            break; // Exit loop on error
        }

        // Print GPIO states
        printf("GPIO %d: %d, GPIO %d: %d, GPIO %d: %d\n", GPIO_17, gpiod_line_get_value(line_17), GPIO_22, gpiod_line_get_value(line_22), GPIO_27, gpiod_line_get_value(line_27));

        // Wait for 0.1 seconds
        usleep(100000); // 100 milliseconds
    }

    // Unexport GPIO pins
    unexport_gpio(chip, GPIO_17);
    unexport_gpio(chip, GPIO_22);
    unexport_gpio(chip, GPIO_27);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

