#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for PWM output
#define PWM_PIN_1 4
#define PWM_PIN_2 12
#define PWM_PIN_3 18

// PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// PWM range (0-255)
#define PWM_RANGE 255

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the PWM duty cycle for a given GPIO pin
void set_pwm_duty_cycle(int gpio_pin, int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    gpioPWM(gpio_pin, duty_cycle);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PWM_PIN_1, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_2, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_3, PWM_RANGE);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Set PWM duty cycles for each GPIO pin
        set_pwm_duty_cycle(PWM_PIN_1, 128);
        set_pwm_duty_cycle(PWM_PIN_2, 192);
        set_pwm_duty_cycle(PWM_PIN_3, 255);

        // Print the PWM duty cycles to standard output
        printf("PWM Duty Cycle (GPIO %d): %d\n", PWM_PIN_1, 128);
        printf("PWM Duty Cycle (GPIO %d): %d\n", PWM_PIN_2, 192);
        printf("PWM Duty Cycle (GPIO %d): %d\n", PWM_PIN_3, 255);

        // Wait for 1 second
        sleep(1);
    }

    // Stop PWM output on all GPIO pins
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);

    // Release GPIO pins
    gpioSetMode(PWM_PIN_1, PI_INPUT); // Set to input to avoid floating
    gpioSetMode(PWM_PIN_2, PI_INPUT);
    gpioSetMode(PWM_PIN_3, PI_INPUT);

    // Terminate pigpio library
    gpioTerminate();

