#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for PWM output
#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 27

// PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// PWM range (0-255)
#define PWM_RANGE 255

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the PWM duty cycle for a given GPIO pin
void set_pwm_duty_cycle(int gpio_pin, int duty_cycle) {
    if (duty_cycle < 0) {
        duty_cycle = 0;
    } else if (duty_cycle > PWM_RANGE) {
        duty_cycle = PWM_RANGE;
    }
    gpioPWM(gpio_pin, duty_cycle);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PWM_PIN_1, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_2, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_3, PWM_RANGE);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Set PWM duty cycles for each GPIO pin
        set_pwm_duty_cycle(PWM_PIN_1, 100);
        set_pwm_duty_cycle(PWM_PIN_2, 150);
        set_pwm_duty_cycle(PWM_PIN_3, 200);

        // Print the PWM duty cycles to standard output
        printf("PWM Duty Cycle for GPIO %d: %d\n", PWM_PIN_1, 100);
        printf("PWM Duty Cycle for GPIO %d: %d\n", PWM_PIN_2, 150);
        printf("PWM Duty Cycle for GPIO %d: %d\n", PWM_PIN_3, 200);

        // Wait for 5 seconds
        sleep(5);

        // Set PWM duty cycles to 0 for each GPIO pin
        set_pwm_duty_cycle(PWM_PIN_1, 0);
        set_pwm_duty_cycle(PWM_PIN_2, 0);
        set_pwm_duty_cycle(PWM_PIN_3, 0);

        // Print the PWM duty cycles to standard output
        printf("PWM Duty Cycle for GPIO %d: %d\n", PWM_PIN_1, 0);
        printf("PWM Duty Cycle for GPIO %d: %d\n", PWM_PIN_2, 0);
        printf("PWM Duty Cycle for GPIO %d: %d\n", PWM_PIN_3, 0);

        // Wait for 5 seconds
        sleep(5);
    }

    // Release GPIO pins
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

// Define GPIO pins for the DS18B20 sensors
#define GPIO_4 4
#define GPIO_17 17
#define GPIO_18 18

// Define the path to the w1-gpio device
#define W1_GPIO_PATH "/sys/bus/w1/devices/"

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the temperature from a DS18B20 sensor
float read_temperature(int gpio_pin) {
    char sensor_path[64];
    char w1_slave_path[128];
    char w1_slave_data[256];
    int fd;
    float temperature = -999.0; // Initialize to an invalid value
    int retries = 3;

    // Construct the path to the w1-slave file for the sensor
    snprintf(sensor_path, sizeof(sensor_path), "%s%d/w1_slave", W1_GPIO_PATH, gpio_pin);

    // Construct the path to the w1-slave file for reading
    snprintf(w1_slave_path, sizeof(w1_slave_path), "%s%d/w1_slave", W1_GPIO_PATH, gpio_pin);

    // Open the w1-slave file for reading
    fd = open(w1_slave_path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening w1-slave file for GPIO %d: %s\n", gpio_pin, strerror(errno));
        return temperature; // Return the invalid temperature
    }

    // Read the w1-slave file
    ssize_t bytes_read = read(fd, w1_slave_data, sizeof(w1_slave_data) - 1);
    if (bytes_read < 0) {
        fprintf(stderr, "Error reading w1-slave file for GPIO %d: %s\n", gpio_pin, strerror(errno));
        close(fd);
        return temperature; // Return the invalid temperature
    }
    w1_slave_data[bytes_read] = '\0'; // Null-terminate the string

    close(fd);

    // Check for CRC errors
    if (strstr(w1_slave_data, "YES") == NULL) {
        fprintf(stderr, "CRC check failed for GPIO %d\n", gpio_pin);
        return temperature; // Return the invalid temperature
    }

    // Extract the temperature from the w1-slave file
    char *temp_str = strstr(w1_slave_data, "t=");
    if (temp_str == NULL) {
        fprintf(stderr, "Temperature data not found for GPIO %d\n", gpio_pin);
        return temperature; // Return the invalid temperature
    }

    long temp_raw = strtol(temp_str + 2, NULL, 10);
    temperature = (float)temp_raw / 1000.0;

    return temperature;
}

// Function to print the temperature readings
void print_temperatures(float temp_4, float temp_17, float temp_18) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - GPIO %d: %.2f °C, GPIO %d: %.2f °C, GPIO %d: %.2f °C\n",
           timestamp, GPIO_4, temp_4, GPIO_17, temp_17, GPIO_18, temp_18);
}

int main() {
    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read temperatures from each sensor
        float temp_4 = read_temperature(GPIO_4);
        float temp_17 = read_temperature(GPIO_17);
        float temp_18 = read_temperature(GPIO_18);

        // Print the temperatures
        print_temperatures(temp_4, temp_17, temp_18);

        // Wait for 5 seconds
        sleep(5);
    }

    // Cleanup GPIO pins (optional, but good practice)
    // This part is not included in the original code, but can be added if needed.
    // For example, you might need to unexport the GPIO pins.

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// HTU21D I2C address
#define HTU21D_ADDR 0x40

// HTU21D commands
#define HTU21D_MEASURE_TEMP 0xE3
#define HTU21D_MEASURE_HUMIDITY 0xE5

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_htu21d(sensor_data_t *data);
void validate_data(sensor_data_t *data);
void print_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, HTU21D_ADDR, 0); // Bus 1, address 0x40, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature and humidity from HTU21D
int read_htu21d(sensor_data_t *data) {
    char buf[3];
    int result;

    // Measure temperature
    result = i2cWriteByte(i2c_handle, HTU21D_MEASURE_TEMP);
    if (result != 0) {
        fprintf(stderr, "Error writing temperature command: %d\n", result);
        return -1;
    }
    gpioDelay(50); // Wait for measurement (at least 45ms)

    result = i2cReadDevice(i2c_handle, buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        return -1;
    }

    // Convert temperature
    uint16_t temp_raw = (buf[0] << 8) | buf[1];
    data->temperature = -46.85 + 175.72 * (float)temp_raw / 65536.0;

    // Measure humidity
    result = i2cWriteByte(i2c_handle, HTU21D_MEASURE_HUMIDITY);
    if (result != 0) {
        fprintf(stderr, "Error writing humidity command: %d\n", result);
        return -1;
    }
    gpioDelay(50); // Wait for measurement (at least 45ms)

    result = i2cReadDevice(i2c_handle, buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading humidity data: %d\n", result);
        return -1;
    }

    // Convert humidity
    uint16_t humidity_raw = (buf[0] << 8) | buf[1];
    data->humidity = -6.0 + 125.0 * (float)humidity_raw / 65536.0;

    return 0;
}

// Validate sensor data
void validate_data(sensor_data_t *data) {
    if (data->temperature < -40.0 || data->temperature > 125.0) {
        fprintf(stderr, "Error: Temperature out of range: %.2f\n", data->temperature);
        data->temperature = -999.0; // Indicate invalid data
    }
    if (data->humidity < 0.0 || data->humidity > 100.0) {
        fprintf(stderr, "Error: Humidity out of range: %.2f\n", data->humidity);
        data->humidity = -999.0; // Indicate invalid data
    }
}

// Print sensor data
void print_data(sensor_data_t data) {
    if (data.temperature != -999.0) {
        printf("Temperature: %.2f C\n", data.temperature);
    }
    if (data.humidity != -999.0) {
        printf("Humidity: %.2f %%\n", data.humidity);
    }
}

// Cleanup resources before exiting
void cleanup() {
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_htu21d(&sensor_data) == 0) {
            // Validate data
            validate_data(&sensor_data);

            // Print data
            print_data(sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 60 seconds
        sleep(60);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

