#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define POWER_CTL 0x2D
#define DATAX0 0x32
#define DATAX1 0x33
#define DATAY0 0x34
#define DATAY1 0x35
#define DATAZ0 0x36
#define DATAZ1 0x37

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to initialize the ADXL345
int adxl345_init(int i2c_handle) {
    // Set data rate to 100 Hz and enable measurement mode
    if (i2cWriteByteData(i2c_handle, POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing to POWER_CTL register\n");
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from two registers
int16_t read_16bit_value(int i2c_handle, uint8_t reg_low, uint8_t reg_high) {
    int16_t value = i2cReadWordData(i2c_handle, reg_low);
    if (value < 0) {
        fprintf(stderr, "Error reading 16-bit value from register 0x%02X\n", reg_low);
        return 0; // Return 0 on error
    }
    return value;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read accelerometer data
        int16_t x = read_16bit_value(i2c_handle, DATAX0, DATAX1);
        int16_t y = read_16bit_value(i2c_handle, DATAY0, DATAY1);
        int16_t z = read_16bit_value(i2c_handle, DATAZ0, DATAZ1);

        // Print the data
        printf("X: %6d, Y: %6d, Z: %6d\n", x, y, z);

        // Wait for 0.1 seconds
        gpioDelay(100000); // 100 ms
    }

    // Close I2C device and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

