        gpiod_chip_close(chip);
        gpiod_line_release(line);
        gpiod_line_release(line2);
        return 1;
    }

    printf("GPIO %d and GPIO %d control program started. Press Ctrl+C to exit.\n", GPIO_PIN, GPIO_PIN_2);

    // Main loop
    while (program_running) {
        // Set GPIO 17 HIGH
        ret = gpiod_line_set_value(line, 1);
