#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define the GPIO pin for PWM output
#define PWM_PIN 18

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pin as an output
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Set PWM frequency to 1 kHz
    gpioSetPWMfrequency(PWM_PIN, 1000);

    // Set PWM range to 1000 (0-1000)
    gpioSetPWMrange(PWM_PIN, 1000);

    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop to control the PWM output
    while (program_running) {
        // Set the PWM duty cycle to 500 (50%)
        gpioPWM(PWM_PIN, 500);
        printf("PWM Duty Cycle: 50%%\n");

        // Wait for 0.02 seconds
        gpioDelay(200000); // 200 ms

        // Set the PWM duty cycle to 0 (0%)
        gpioPWM(PWM_PIN, 0);
        printf("PWM Duty Cycle: 0%%\n");

        // Wait for 0.02 seconds
        gpioDelay(200000); // 200 ms
    }

    // Stop the PWM output
    gpioPWM(PWM_PIN, 0);

    // Release the GPIO pin
    gpioSetMode(PWM_PIN, PI_INPUT); // Set to input to avoid floating output

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define GPIO_17 17
#define GPIO_22 22
#define GPIO_23 23
#define GPIO_24 24

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the state of a GPIO pin
int set_gpio_state(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO state: %d\n", ret);
        return -1;
    }
    return 0;
}

// Function to export a GPIO pin
int export_gpio(struct gpiod_chip *chip, int pin) {
    int ret = gpiod_chip_export_line(chip, pin);
    if (ret < 0) {
        fprintf(stderr, "Error exporting GPIO %d: %d\n", pin, ret);
        return -1;
    }
    return 0;
}

// Function to unexport a GPIO pin
int unexport_gpio(struct gpiod_chip *chip, int pin) {
    int ret = gpiod_chip_unexport_line(chip, pin);
    if (ret < 0) {
        fprintf(stderr, "Error unexporting GPIO %d: %d\n", pin, ret);
        return -1;
    }
    return 0;
}

// Function to open a GPIO line
struct gpiod_line *open_gpio_line(struct gpiod_chip *chip, int pin) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d\n", pin);
        return NULL;
    }
    return line;
}

// Function to set the direction of a GPIO line
int set_gpio_direction(struct gpiod_line *line, const char *direction) {
    int ret = gpiod_line_set_direction(line, direction);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO direction to %s: %d\n", direction, ret);
        return -1;
    }
    return 0;
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return 1;
    }

    // Export GPIO pins
    if (export_gpio(chip, GPIO_17) || export_gpio(chip, GPIO_22) ||
        export_gpio(chip, GPIO_23) || export_gpio(chip, GPIO_24)) {
        gpiod_chip_close(chip);
        return 1;
    }

    // Open GPIO lines
    struct gpiod_line *line_17 = open_gpio_line(chip, GPIO_17);
    struct gpiod_line *line_22 = open_gpio_line(chip, GPIO_22);
    struct gpiod_line *line_23 = open_gpio_line(chip, GPIO_23);
    struct gpiod_line *line_24 = open_gpio_line(chip, GPIO_24);

    if (!line_17 || !line_22 || !line_23 || !line_24) {
        // Cleanup already exported pins
        unexport_gpio(chip, GPIO_17);
        unexport_gpio(chip, GPIO_22);
        unexport_gpio(chip, GPIO_23);
        unexport_gpio(chip, GPIO_24);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set GPIO directions to output
    if (set_gpio_direction(line_17, "out") || set_gpio_direction(line_22, "out") ||
        set_gpio_direction(line_23, "out") || set_gpio_direction(line_24, "out")) {
        // Cleanup already opened lines and exported pins
        gpiod_line_release(line_17);
        gpiod_line_release(line_22);
        gpiod_line_release(line_23);
        gpiod_line_release(line_24);
        unexport_gpio(chip, GPIO_17);
        unexport_gpio(chip, GPIO_22);
        unexport_gpio(chip, GPIO_23);
        unexport_gpio(chip, GPIO_24);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Set GPIO states
        if (set_gpio_state(line_17, 1) || set_gpio_state(line_22, 0) ||
            set_gpio_state(line_23, 1) || set_gpio_state(line_24, 0)) {
            // Cleanup already opened lines and exported pins
            gpiod_line_release(line_17);
            gpiod_line_release(line_22);
            gpiod_line_release(line_23);
            gpiod_line_release(line_24);
            unexport_gpio(chip, GPIO_17);
            unexport_gpio(chip, GPIO_22);
            unexport_gpio(chip, GPIO_23);
            unexport_gpio(chip, GPIO_24);
            gpiod_chip_close(chip);
            return 1;
        }

        // Wait for 0.2 seconds
        sleep(0.2);

        // Set GPIO states
        if (set_gpio_state(line_17, 0) || set_gpio_state(line_22, 1) ||
            set_gpio_state(line_23, 0) || set_gpio_state(line_24, 1)) {
            // Cleanup already opened lines and exported pins
            gpiod_line_release(line_17);
            gpiod_line_release(line_22);
            gpiod_line_release(line_23);
            gpiod_line_release(line_24);
            unexport_gpio(chip, GPIO_17);
            unexport_gpio(chip, GPIO_22);
            unexport_gpio(chip, GPIO_23);
            unexport_gpio(chip, GPIO_24);
            gpiod_chip_close(chip);
            return 1;
        }

        // Wait for 0.2 seconds
        sleep(0.2);
    }

    // Cleanup: Release GPIO lines and unexport pins
    gpiod_line_release(line_17);
    gpiod_line_release(line_22);
    gpiod_line_release(line_23);
    gpiod_line_release(line_24);
    unexport_gpio(chip, GPIO_17);
    unexport_gpio(chip, GPIO_22);
    unexport_gpio(chip, GPIO_23);
    unexport_gpio(chip, GPIO_24);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

// TCS34725 I2C address
#define TCS34725_ADDRESS 0x29

// TCS34725 register addresses
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CONTROL 0x8F
#define TCS34725_CDATA 0x94
#define TCS34725_RDATA 0x96
#define TCS34725_GDATA 0x98
#define TCS34725_BDATA 0x9A

// Enable register values
#define TCS34725_ENABLE_PON 0x01
#define TCS34725_ENABLE_AEN 0x02
#define TCS34725_ENABLE_AIEN 0x10

// Integration time values
#define TCS34725_INTEGRATIONTIME_2_4MS 0xFF
#define TCS34725_INTEGRATIONTIME_24MS 0xF6
#define TCS34725_INTEGRATIONTIME_101MS 0xD5
#define TCS34725_INTEGRATIONTIME_154MS 0xC0
#define TCS34725_INTEGRATIONTIME_700MS 0x96

// Gain values
#define TCS34725_GAIN_1X 0x00
#define TCS34725_GAIN_4X 0x01
#define TCS34725_GAIN_16X 0x02
#define TCS34725_GAIN_60X 0x03

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int tcs34725_init(int fd);
int tcs34725_read_data(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the TCS34725 sensor
int tcs34725_init(int fd) {
    // Enable power and ALS
    if (i2c_smbus_write_byte_data(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0) {
        fprintf(stderr, "Error writing to ENABLE register: %s\n", strerror(errno));
        return -1;
    }

    // Set integration time
    if (i2c_smbus_write_byte_data(fd, TCS34725_ATIME, TCS34725_INTEGRATIONTIME_24MS) < 0) {
        fprintf(stderr, "Error writing to ATIME register: %s\n", strerror(errno));
        return -1;
    }

    // Set gain
    if (i2c_smbus_write_byte_data(fd, TCS34725_CONTROL, TCS34725_GAIN_1X) < 0) {
        fprintf(stderr, "Error writing to CONTROL register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read data from the TCS34725 sensor
int tcs34725_read_data(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t buffer[8];

    if (i2c_smbus_read_i2c_block_data(fd, TCS34725_CDATA, (char *)buffer, 8) != 8) {
        fprintf(stderr, "Error reading data from sensor: %s\n", strerror(errno));
        return -1;
    }

    *clear = (buffer[1] << 8) | buffer[0];
    *red = (buffer[3] << 8) | buffer[2];
    *green = (buffer[5] << 8) | buffer[4];
    *blue = (buffer[7] << 8) | buffer[6];

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize the sensor
    if (tcs34725_init(i2c_fd) < 0) {
        fprintf(stderr, "Error initializing TCS34725 sensor.\n");
        close(i2c_fd);
        return 1;
    }

    uint16_t clear, red, green, blue;

    // Main loop
    while (program_running) {
        // Read data from the sensor
        if (tcs34725_read_data(i2c_fd, &clear, &red, &green, &blue) == 0) {
            // Print the data
            printf("Clear: %u, Red: %u, Green: %u, Blue: %u\n", clear, red, green, blue);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        // Wait for 0.2 seconds
        usleep(200000); // 200ms
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
