// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to set the state of a GPIO pin
int set_gpio_state(struct gpiod_chip *chip, int pin, int value) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get GPIO line for pin %d\n", pin);
        return -1;
    }

    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set GPIO line for pin %d to value %d\n", pin, value);
        gpiod_line_release(line);
        return -1;
    }

    gpiod_line_release(line);
    return 0;
}

// Function to read the state of a GPIO pin
int read_gpio_state(struct gpiod_chip *chip, int pin) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get GPIO line for pin %d\n", pin);
        return -1;
    }

    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error: Could not get GPIO line for pin %d value\n", pin);
        gpiod_line_release(line);
        return -1;
    }

    gpiod_line_release(line);
    return value;
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip %s\n", GPIO_CHIP);
        return 1;
    }

    // Request GPIO lines as outputs
    struct gpiod_line *line_18 = gpiod_chip_get_line(chip, GPIO_18);
    struct gpiod_line *line_21 = gpiod_chip_get_line(chip, GPIO_21);
    struct gpiod_line *line_22 = gpiod_chip_get_line(chip, GPIO_22);

    if (!line_18 || !line_21 || !line_22) {
        fprintf(stderr, "Error: Could not get GPIO line for pin %d\n", GPIO_18);
        fprintf(stderr, "Error: Could not get GPIO line for pin %d\n", GPIO_21);
        fprintf(stderr, "Error: Could not get GPIO line for pin %d\n", GPIO_22);
        gpiod_chip_close(chip);
        return 1;
    }

    int ret = gpiod_line_request_output(line_18, "gpio_18", 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request GPIO line for pin %d as output\n", GPIO_18);
        gpiod_line_release(line_18);
        gpiod_line_release(line_21);
        gpiod_line_release(line_22);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line_21, "gpio_21", 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request GPIO line for pin %d as output\n", GPIO_21);
        gpiod_line_release(line_18);
        gpiod_line_release(line_21);
        gpiod_line_release(line_22);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line_22, "gpio_22", 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request GPIO line for pin %d as output\n", GPIO_22);
        gpiod_line_release(line_18);
        gpiod_line_release(line_21);
        gpiod_line_release(line_22);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Set GPIO states
        if (set_gpio_state(chip, GPIO_18, 1) < 0) {
            fprintf(stderr, "Error setting GPIO 18 to HIGH\n");
        }
        if (set_gpio_state(chip, GPIO_21, 0) < 0) {
            fprintf(stderr, "Error setting GPIO 21 to LOW\n");
        }
        if (set_gpio_state(chip, GPIO_22, 1) < 0) {
            fprintf(stderr, "Error setting GPIO 22 to HIGH\n");
        }

        // Read GPIO states
        int state_18 = read_gpio_state(chip, GPIO_18);
        int state_21 = read_gpio_state(chip, GPIO_21);
        int state_22 = read_gpio_state(chip, GPIO_22);

        if (state_18 < 0 || state_21 < 0 || state_22 < 0) {
            fprintf(stderr, "Error reading GPIO states\n");
        } else {
            printf("GPIO 18: %d, GPIO 21: %d, GPIO 22: %d\n", state_18, state_21, state_22);
        }

        // Wait for 1 second
        sleep(1);
    }

    // Release GPIO lines
    gpiod_line_release(line_18);
    gpiod_line_release(line_21);
    gpiod_line_release(line_22);

