#include <signal.h>
#include <errno.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_FORMAT V4L2_PIX_FMT_MJPEG
#define IMAGE_SIZE (IMAGE_WIDTH * IMAGE_HEIGHT * 3 / 2) // MJPEG format

static int fd = -1; // File descriptor for the device
static FILE *image_file = NULL; // File pointer for the image file

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (fd != -1) {
        close(fd);
    }
    if (image_file != NULL) {
        fclose(image_file);
    }
    exit(0);
}

// Function to initialize the camera device
int init_camera() {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;

    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return -1;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        close(fd);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = IMAGE_FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return -1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("Error querying buffer");
        close(fd);
        return -1;
    }

    char *buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("Error mapping buffer");
        close(fd);
        return -1;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        munmap(buffer, buf.length);
        close(fd);
        return -1;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        munmap(buffer, buf.length);
        close(fd);
        return -1;
    }

    return 0;
}

// Function to capture an image
int capture_image(char *filename) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    image_file = fopen(filename, "wb");
    if (image_file == NULL) {
        perror("Error opening image file");
        ioctl(fd, VIDIOC_QBUF, &buf);
        return -1;
    }

    size_t bytes_written = fwrite(buffer, 1, buf.bytesused, image_file);
    if (bytes_written != buf.bytesused) {
        fprintf(stderr, "Error writing to image file\n");
        fclose(image_file);
        image_file = NULL;
        ioctl(fd, VIDIOC_QBUF, &buf);
        return -1;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        fclose(image_file);
        image_file = NULL;
        return -1;
    }

    return 0;
}

// Function to uninitialize the camera device
void uninit_camera() {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
    }

    if (image_file != NULL) {
        fclose(image_file);
        image_file = NULL;
    }

    if (fd != -1) {
        close(fd);
        fd = -1;
    }
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize the camera
    if (init_camera() < 0) {
        fprintf(stderr, "Failed to initialize camera. Exiting.\n");
        return 1;
    }

    // Capture the image
    if (capture_image("image.jpg") < 0) {
        fprintf(stderr, "Failed to capture image. Exiting.\n");
        uninit_camera();
        return 1;
    }

    // Uninitialize the camera
    uninit_camera();

    printf("Image captured successfully. Image saved as image.jpg\n");
    return 0;
}

