static volatile int running = 1;

// Function prototypes
void triggerSensor();
long pulseIn(int gpio, int level, uint32_t timeout);
float calculateDistance(long pulseWidth);
void signalHandler(int signal);

// Signal handler for graceful shutdown
void signalHandler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the pulse width of the echo signal
long pulseIn(int gpio, int level, uint32_t timeout) {
    uint32_t start = 0, end = 0;

    // Wait for the signal to go high
    int count = 0;
    while (gpioRead(gpio) != level && count < timeout) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= timeout) {
        return -1; // Timeout
    }

    start = gpioTick();

    // Wait for the signal to go low
    count = 0;
    while (gpioRead(gpio) == level && count < timeout) {
        count++;
        gpioDelay(1);
    }

    if (count >= timeout) {
        return -1; // Timeout
    }

    end = gpioTick();

    return end - start;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulseWidth) {
    if (pulseWidth < 0) {
        return -1.0; // Indicate error
    }
    return (pulseWidth * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 for one-way distance
}

