    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    printf("Ultrasonic sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        triggerSensor();
        long pulseWidth = pulseIn(ECHO_PIN, 1, TIMEOUT_US);

        if (pulseWidth > 0) {
            float distance = calculateDistance(pulseWidth);
            if (distance >= 0) {
                printf("Distance: %.2f cm\n", distance);
            } else {
                fprintf(stderr, "Error: Invalid distance measurement\n");
            }
        } else {
