    int ret;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIO_CHIP);
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %d\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(line, GPIO_DIRECTION, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line for output: %d\n", ret);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("GPIO %d initialized as output. Press Ctrl+C to exit.\n", GPIO_PIN);

    // Main loop
    while (!terminate) {
        // Set GPIO line to HIGH
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line value to HIGH: %d\n", ret);
            break;
        }
        printf("GPIO %d set to HIGH\n", GPIO_PIN);
        sleep(1);

        // Set GPIO line to LOW
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line value to LOW: %d\n", ret);
            break;
        }
        printf("GPIO %d set to LOW\n", GPIO_PIN);
        sleep(1);
