// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register settings
#define CONFIG_OS_SINGLE 0x8000  // Start a single conversion
#define CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define CONFIG_PGA_4_096V 0x0000 // +/-4.096V range
#define CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define CONFIG_DR_128SPS 0x0080  // 128 SPS
#define CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define CONFIG_COMP_POL_LOW 0x0000 // Active low comparator
#define CONFIG_COMP_LAT_NON 0x0000 // Non-latching comparator
#define CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a byte to an ADS1115 register
int write_register(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;

    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read a word from an ADS1115 register
int read_register(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[1];
    buf[0] = reg;

    if (write(fd, buf, 1) != 1) {
        fprintf(stderr, "Error writing register address for read: %s\n", strerror(errno));
        return -1;
    }

    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    *value = (buf[0] << 8) | buf[1];
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Specify slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        uint16_t config_value = 0;
        uint16_t conversion_value;

        // Configure ADS1115 for single-shot mode, +/-4.096V, 128 SPS
        config_value |= CONFIG_OS_SINGLE;
        config_value |= CONFIG_MUX_SINGLE_0;
        config_value |= CONFIG_PGA_4_096V;
        config_value |= CONFIG_MODE_SINGLE;
        config_value |= CONFIG_DR_128SPS;
        config_value |= CONFIG_COMP_MODE_TRAD;
        config_value |= CONFIG_COMP_POL_LOW;
        config_value |= CONFIG_COMP_LAT_NON;
        config_value |= CONFIG_COMP_QUE_DISABLE;

        // Write configuration to the ADS1115
        if (write_register(i2c_fd, ADS1115_REG_CONFIG, config_value) != 0) {
            fprintf(stderr, "Error writing configuration to ADS1115\n");
            close(i2c_fd);
            return 1;
        }

        // Wait for conversion to complete (at least 8ms for 128 SPS)
        usleep(10000); // 10ms

        // Read conversion result
        if (read_register(i2c_fd, ADS1115_REG_CONVERT, &conversion_value) != 0) {
            fprintf(stderr, "Error reading conversion result from ADS1115\n");
            close(i2c_fd);
            return 1;
        }

        // Convert raw value to voltage (assuming +/-4.096V range)
        float voltage = (float)conversion_value * 4.096 / 32768.0;

        // Print the voltage reading
