    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpio_handle = gpioSetMode(GPIO_PIN, PI_OUTPUT);
    if (gpio_handle < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output: %d\n", GPIO_PIN, gpio_handle);
        gpioTerminate();
        return 1;
    }

    printf("GPIO %d set as output. Press Ctrl+C to exit.\n", GPIO_PIN);

    // Main loop to toggle the GPIO pin
    while (program_running) {
        // Read the current GPIO value
        gpio_value = gpioRead(GPIO_PIN);
        if (gpio_value < 0) {
            fprintf(stderr, "Failed to read GPIO %d: %d\n", GPIO_PIN, gpio_value);
            break; // Exit loop on error
        }

        // Toggle the GPIO value
        gpio_value = !gpio_value;

        // Write the new GPIO value
        if (gpioWrite(GPIO_PIN, gpio_value) < 0) {
            fprintf(stderr, "Failed to write GPIO %d: %d\n", GPIO_PIN, gpio_value);
            break; // Exit loop on error
        }

        // Print the current GPIO value
        printf("GPIO %d is now %s\n", GPIO_PIN, gpio_value ? "HIGH" : "LOW");

        // Wait for 0.05 seconds
        gpioDelay(500000); // 500000 microseconds = 0.05 seconds
    }

    // Release GPIO resources before exiting
    gpioWrite(GPIO_PIN, 0); // Set GPIO to LOW before exiting
    gpioTerminate();

    printf("GPIO %d released. Exiting.\n", GPIO_PIN);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

// Define the I2C address of the HD44780 display
#define HD44780_I2C_ADDR 0x27

// Define the GPIO pin connected to the backlight (BCM numbering)
#define HD44780_BACKLIGHT_PIN 18

// Define the GPIO pin connected to the RS pin (BCM numbering)
#define HD44780_RS_PIN 23

// Define the GPIO pin connected to the EN pin (BCM numbering)
#define HD44780_EN_PIN 24

// Define the GPIO pin connected to the D4 pin (BCM numbering)
#define HD44780_D4_PIN 25

// Define the GPIO pin connected to the D5 pin (BCM numbering)
#define HD44780_D5_PIN 26

// Define the GPIO pin connected to the D6 pin (BCM numbering)
#define HD44780_D6_PIN 19

// Define the GPIO pin connected to the D7 pin (BCM numbering)
#define HD44780_D7_PIN 20

// Define the number of characters in the display
#define DISPLAY_WIDTH 16

// Global variable to store the I2C file descriptor
int i2c_fd;

// Function prototypes
int hd44780_init();
void hd44780_send_command(unsigned char command);
void hd44780_send_data(unsigned char data);
void hd44780_clear_display();
void hd44780_set_cursor(int row, int col);
void hd44780_display_string(const char *string);
void display_random_number();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    // Turn off the backlight
    hd44780_send_command(0x08); // Function set: Display off

    // Close the I2C device
    close(i2c_fd);

    // Terminate the program
    exit(0);
}

// Function to initialize the HD44780 display
int hd44780_init() {
    // Set the GPIO pins as output
    if (gpioSetMode(HD44780_BACKLIGHT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting backlight pin as output\n");
        return -1;
    }
    if (gpioSetMode(HD44780_RS_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting RS pin as output\n");
        return -1;
    }
    if (gpioSetMode(HD44780_EN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting EN pin as output\n");
        return -1;
    }
    if (gpioSetMode(HD44780_D4_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting D4 pin as output\n");
        return -1;
    }
    if (gpioSetMode(HD44780_D5_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting D5 pin as output\n");
        return -1;
    }
    if (gpioSetMode(HD44780_D6_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting D6 pin as output\n");
        return -1;
    }
    if (gpioSetMode(HD44780_D7_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting D7 pin as output\n");
        return -1;
    }

    // Initialize the display (4-bit mode, 2 lines, 5x8 font)
    hd44780_send_command(0x33); // Initialize
    usleep(5000);               // Wait for 5ms
    hd44780_send_command(0x32); // Initialize
    usleep(5000);               // Wait for 5ms
    hd44780_send_command(0x28); // Function set: 4-bit mode, 2 lines, 5x8 font
    usleep(5000);               // Wait for 5ms
    hd44780_send_command(0x0C); // Display control: Display on, cursor off, blink off
    usleep(5000);               // Wait for 5ms
    hd44780_send_command(0x06); // Entry mode set: Increment cursor, no shift
    usleep(5000);               // Wait for 5ms

    return 0;
}

// Function to send a command to the HD44780 display
void hd44780_send_command(unsigned char command) {
    // Send the upper nibble of the command
    gpioWrite(HD44780_RS_PIN, 0); // RS = 0 for command
    gpioWrite(HD44780_D4_PIN, (command >> 4) & 0x01);
    gpioWrite(HD44780_D5_PIN, (command >> 5) & 0x01);
    gpioWrite(HD44780_D6_PIN, (command >> 6) & 0x01);
    gpioWrite(HD44780_D7_PIN, (command >> 7) & 0x01);
    gpioWrite(HD44780_EN_PIN, 1);
    usleep(1); // Enable pulse width >= 450ns
    gpioWrite(HD44780_EN_PIN, 0);
    usleep(100); // Wait for 100us

    // Send the lower nibble of the command
    gpioWrite(HD44780_RS_PIN, 0); // RS = 0 for command
    gpioWrite(HD44780_D4_PIN, command & 0x01);
    gpioWrite(HD44780_D5_PIN, (command >> 1) & 0x01);
    gpioWrite(HD44780_D6_PIN, (command >> 2) & 0x01);
    gpioWrite(HD44780_D7_PIN, (command >> 3) & 0x01);
    gpioWrite(HD44780_EN_PIN, 1);
    usleep(1); // Enable pulse width >= 450ns
    gpioWrite(HD44780_EN_PIN, 0);
    usleep(100); // Wait for 100us
}

// Function to send data to the HD44780 display
void hd44780_send_data(unsigned char data) {
    // Send the upper nibble of the data
    gpioWrite(HD44780_RS_PIN, 1); // RS = 1 for data
    gpioWrite(HD44780_D4_PIN, (data >> 4) & 0x01);
    gpioWrite(HD44780_D5_PIN, (data >> 5) & 0x01);
    gpioWrite(HD44780_D6_PIN, (data >> 6) & 0x01);
    gpioWrite(HD44780_D7_PIN, (data >> 7) & 0x01);
    gpioWrite(HD44780_EN_PIN, 1);
    usleep(1); // Enable pulse width >= 450ns
    gpioWrite(HD44780_EN_PIN, 0);
    usleep(100); // Wait for 100us

    // Send the lower nibble of the data
    gpioWrite(HD44780_RS_PIN, 1); // RS = 1 for data
    gpioWrite(HD44780_D4_PIN, data & 0x01);
    gpioWrite(HD44780_D5_PIN, (data >> 1) & 0x01);
    gpioWrite(HD44780_D6_PIN, (data >> 2) & 0x01);
    gpioWrite(HD44780_D7_PIN, (data >> 3) & 0x01);
    gpioWrite(HD44780_EN_PIN, 1);
    usleep(1); // Enable pulse width >= 450ns
    gpioWrite(HD44780_EN_PIN, 0);
    usleep(100); // Wait for 100us
}

// Function to clear the display
void hd44780_clear_display() {
    hd44780_send_command(0x01); // Clear display command
    usleep(2000);               // Wait for 2ms
}

// Function to set the cursor position
void hd44780_set_cursor(int row, int col) {
    int address;
    if (row == 0) {
        address = 0x00 + col;
    } else {
        address = 0x40 + col;
    }
    hd44780_send_command(0x80 | address); // Set DDRAM address command
}

// Function to display a string on the display
void hd44780_display_string(const char *string) {
    while (*string) {
        hd44780_send_data(*string++);
    }
}

// Function to display a random number on the display
void display_random_number() {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

    hd44780_clear_display();
    hd44780_set_cursor(0, 0);
    hd44780_display_string(buffer);
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device\n");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, HD44780_I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address\n");
        close(i2c_fd);
        return 1;
    }

    // Initialize the HD44780 display
    if (hd44780_init() != 0) {
        fprintf(stderr, "Error initializing HD44780 display\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        display_random_number();
        sleep(10);
    }

    return 0;
}

#include <stdio.h>
