#include <errno.h>
#include <string.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    program_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to initialize the MPU6050
int init_mpu6050() {
    // Wake up the MPU6050 (clear sleep mode bit)
    if (i2c_smbus_write_byte_data(i2c_fd, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read raw accelerometer data
int read_raw_accelerometer(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    if (i2c_smbus_read_i2c_block_data(i2c_fd, ACCEL_XOUT_H, buf, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Function to convert raw accelerometer data to g-force units
void convert_to_g(int16_t raw_x, int16_t raw_y, int16_t raw_z, float *x_g, float *y_g, float *z_g) {
    // Sensitivity scale factor for +/- 2g range
    const float sensitivity = 16384.0f;

    *x_g = (float)raw_x / sensitivity;
    *y_g = (float)raw_y / sensitivity;
    *z_g = (float)raw_z / sensitivity;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050() < 0) {
        fprintf(stderr, "MPU6050 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    int16_t raw_x, raw_y, raw_z;
    float x_g, y_g, z_g;

    // Read and print accelerometer data 100 times
    for (int i = 0; i < 100 && program_running; ++i) {
        if (read_raw_accelerometer(&raw_x, &raw_y, &raw_z) == 0) {
            convert_to_g(raw_x, raw_y, raw_z, &x_g, &y_g, &z_g);
            printf("X: %.3f g, Y: %.3f g, Z: %.3f g\n", x_g, y_g, z_g);
        } else {
            fprintf(stderr, "Failed to read accelerometer data. Retrying...\n");
        }
        usleep(10000); // 10ms delay
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
