    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the state of an LED
int set_led_state(int gpio_pin, int state) {
    if (gpioWrite(gpio_pin, state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", gpio_pin);
        return -1;
    }
    return 0;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(LED1_PIN, PI_OUTPUT);
    gpioSetMode(LED2_PIN, PI_OUTPUT);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Program started. Press Ctrl+C to exit.\n");

    // Main loop to control the LEDs
    while (program_running) {
        // Turn on LED 1
        if (set_led_state(LED1_PIN, 1) != 0) {
            fprintf(stderr, "Error setting LED 1 state\n");
            break;
        }
        printf("LED 1 ON\n");

        // Wait for 5 seconds
        sleep(5);

        // Turn off LED 1
        if (set_led_state(LED1_PIN, 0) != 0) {
            fprintf(stderr, "Error setting LED 1 state\n");
            break;
        }
        printf("LED 1 OFF\n");

