#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <mosquitto.h>
#include <pigpio.h>

// Configuration
#define MQTT_BROKER_ADDRESS "localhost" // Replace with your MQTT broker address
#define MQTT_BROKER_PORT 1883
#define MQTT_CLIENT_ID "rpi_sensor_node"
#define MQTT_TOPIC "sensor_data"
#define GPIO_PIN 4
#define VALID_READING_MIN 0
#define VALID_READING_MAX 1023
#define READ_INTERVAL_MS 100

// Global variables
static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function prototypes
int read_sensor_data(int gpio_pin);
int validate_reading(int reading);
int publish_mqtt_message(struct mosquitto *mosq, const char *topic, const char *payload);
void signal_handler(int signum);

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Received SIGINT, shutting down...\n");
        running = 0;
    }
}

// Reads the sensor data from the specified GPIO pin
int read_sensor_data(int gpio_pin) {
    int reading = gpioRead(gpio_pin);
    if (reading < 0) {
        fprintf(stderr, "Error reading GPIO pin %d\n", gpio_pin);
        return -1; // Indicate error
    }
    return reading;
}

// Validates the sensor reading
int validate_reading(int reading) {
    if (reading < VALID_READING_MIN || reading > VALID_READING_MAX) {
        fprintf(stderr, "Invalid reading: %d\n", reading);
        return 0; // Indicate invalid
    }
    return 1; // Indicate valid
}

// Publishes the MQTT message
int publish_mqtt_message(struct mosquitto *mosq, const char *topic, const char *payload) {
    int ret = mosquitto_publish(mosq, NULL, topic, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing MQTT message: %s\n", mosquitto_strerror(ret));
        return -1; // Indicate error
    }
    return 0; // Indicate success
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Initialize libmosquitto
    mosquitto_lib_init();

    // Create a new Mosquitto client instance
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error creating Mosquitto client\n");
        gpioTerminate();
        return 1;
    }

    // Connect to the MQTT broker
    int ret = mosquitto_connect(mosq, MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Starting sensor node...\n");

    // Main loop
    while (running) {
        // Read sensor data
        int reading = read_sensor_data(GPIO_PIN);
        if (reading < 0) {
            fprintf(stderr, "Error reading sensor data, retrying in %d ms\n", READ_INTERVAL_MS);
            gpioDelay(READ_INTERVAL_MS * 1000); // Delay in microseconds
            continue;
        }

        // Validate reading
        if (!validate_reading(reading)) {
            fprintf(stderr, "Invalid reading, retrying in %d ms\n", READ_INTERVAL_MS);
            gpioDelay(READ_INTERVAL_MS * 1000); // Delay in microseconds
            continue;
        }

        // Format the reading as a string
        char payload[32];
        snprintf(payload, sizeof(payload), "%d", reading);

        // Publish the MQTT message
        if (publish_mqtt_message(mosq, MQTT_TOPIC, payload) != 0) {
            fprintf(stderr, "Error publishing MQTT message, retrying in %d ms\n", READ_INTERVAL_MS);
        }

        // Wait for the next reading
        gpioDelay(READ_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Clean up
    printf("Cleaning up...\n");
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 23
#define GPIO_DIRECTION "out"

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int main() {
    int ret;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIO_CHIP);
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %d\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set GPIO direction to output
    ret = gpiod_line_request_output(line, GPIO_DIRECTION, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO direction: %d\n", ret);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("GPIO %d set to output. Press Ctrl+C to exit.\n", GPIO_PIN);

    // Main loop
    while (!terminate) {
        // Read GPIO value
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO value: %d\n", value);
            break;
        }

        // Print GPIO value
        printf("GPIO %d value: %d\n", GPIO_PIN, value);

        // Set GPIO value to the opposite
        ret = gpiod_line_set_value(line, !value);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO value: %d\n", ret);
            break;
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Release GPIO line
    gpiod_line_release(line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    printf("GPIO %d released and chip closed.\n", GPIO_PIN);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the HC-SR04 sensors
#define TRIGGER_PIN_1 17
#define ECHO_PIN_1 22
#define TRIGGER_PIN_2 27
#define ECHO_PIN_2 23

// Define the speed of sound in cm/s
#define SPEED_OF_SOUND 34300.0

// Define the maximum distance in cm
#define MAX_DISTANCE 400.0

// Define the minimum distance in cm
#define MIN_DISTANCE 2.0

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to trigger the HC-SR04 sensor
void triggerSensor(int triggerPin) {
    gpioWrite(triggerPin, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(triggerPin, 0);
}

// Function to measure the echo pulse duration
long pulseIn(int echoPin, int level, int timeout) {
    long startTime = 0, endTime = 0;

    // Wait for the echo pin to go high (with timeout)
    int count = 0;
    while (gpioRead(echoPin) != level && count < timeout) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= timeout) {
        return -1; // Timeout
    }

    startTime = gpioTick();

    // Wait for the echo pin to go low (with timeout)
    count = 0;
    while (gpioRead(echoPin) == level && count < timeout) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= timeout) {
        return -1; // Timeout
    }

    endTime = gpioTick();

    return endTime - startTime;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulseDuration) {
    if (pulseDuration < 0) {
        return -1.0; // Indicate an error
    }
    return (pulseDuration * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 for one-way distance
}

// Function to validate the distance reading
int validateDistance(float distance) {
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return 0; // Invalid distance
    }
    return 1; // Valid distance
}

