#define DEBOUNCE_DELAY_MS 50

// Global variables
static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function prototypes
int init_gpio();
int read_sensor();
int publish_data(int sensor_value);
void signal_handler(int signum);
void cleanup();

// Structure to hold GPIO configuration
typedef struct {
    int pin;
    int last_state;
    unsigned long last_change_time;
} gpio_config_t;

gpio_config_t gpio_config = {GPIO_PIN, 0, 0};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        cleanup();
        return 1;
    }

    int rc = mosquitto_connect(mosq, MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: Could not connect to MQTT broker: %s\n", mosquitto_strerror(rc));
        cleanup();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        int sensor_value = read_sensor();
        if (sensor_value != -1) {
            if (publish_data(sensor_value) != 0) {
                fprintf(stderr, "Error: Failed to publish data\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read sensor value\n");
        }

        gpioDelay(1000); // Sleep for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize GPIO
int init_gpio() {
    gpioSetMode(gpio_config.pin, PI_INPUT);
    gpioSetPullUpDown(gpio_config.pin, PI_PUD_UP); // Enable pull-up resistor
    gpio_config.last_state = gpioRead(gpio_config.pin);
    gpio_config.last_change_time = gpioTick();
    return 0;
}

// Read sensor value with debouncing
int read_sensor() {
    int current_state = gpioRead(gpio_config.pin);
    unsigned long current_time = gpioTick();

    if (current_state != gpio_config.last_state) {
        if (current_time - gpio_config.last_change_time > DEBOUNCE_DELAY_MS * 1000) { // Convert ms to us
            gpio_config.last_state = current_state;
            gpio_config.last_change_time = current_time;
            return current_state;
        }
    }
    return -1; // Indicate no change
}

