    gpioSetPWMrange(PWM_PIN_3, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_4, PWM_RANGE);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Set PWM duty cycles for each GPIO pin
        set_pwm_duty_cycle(PWM_PIN_1, 100);
        set_pwm_duty_cycle(PWM_PIN_2, 150);
        set_pwm_duty_cycle(PWM_PIN_3, 200);
        set_pwm_duty_cycle(PWM_PIN_4, 255);

        // Print the PWM duty cycles to standard output
        printf("PWM Duty Cycle for GPIO %d: %d\n", PWM_PIN_1, 100);
        printf("PWM Duty Cycle for GPIO %d: %d\n", PWM_PIN_2, 150);
        printf("PWM Duty Cycle for GPIO %d: %d\n", PWM_PIN_3, 200);
        printf("PWM Duty Cycle for GPIO %d: %d\n", PWM_PIN_4, 255);

        // Wait for 0.1 seconds
        gpioDelay(100000); // 100000 microseconds = 0.1 seconds
    }

    // Stop PWM output on all GPIO pins
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioPWM(PWM_PIN_4, 0);

    // Release GPIO pins
    gpioSetMode(PWM_PIN_1, PI_INPUT); // Set to input to avoid floating
    gpioSetMode(PWM_PIN_2, PI_INPUT);
    gpioSetMode(PWM_PIN_3, PI_INPUT);
    gpioSetMode(PWM_PIN_4, PI_INPUT);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <mosquitto.h>

// Configuration
#define MQTT_BROKER_ADDRESS "localhost" // Replace with your MQTT broker address
#define MQTT_BROKER_PORT 1883
#define MQTT_CLIENT_ID "rpi_sensor_node"
#define MQTT_TOPIC "sensor_data"
#define GPIO_PIN 4
#define VALID_READING_MIN 0
#define VALID_READING_MAX 1023
#define SAMPLE_INTERVAL_MS 1000

// Global variables
static volatile int running = 1;
static struct mosquitto *mosq = NULL;

// Function prototypes
int read_sensor_data(int gpio_pin);
int validate_reading(int reading);
int publish_mqtt_message(struct mosquitto *mosq, const char *topic, int reading);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Function to read sensor data from GPIO pin
int read_sensor_data(int gpio_pin) {
    int reading = gpioRead(gpio_pin);
    if (reading < 0) {
        fprintf(stderr, "Error reading GPIO pin %d: %d\n", gpio_pin, reading);
        return -1; // Indicate error
    }
    return reading;
}

// Function to validate sensor reading
int validate_reading(int reading) {
    if (reading < VALID_READING_MIN || reading > VALID_READING_MAX) {
        fprintf(stderr, "Invalid reading: %d\n", reading);
        return 0; // Indicate invalid
    }
    return 1; // Indicate valid
}

// Function to publish MQTT message
int publish_mqtt_message(struct mosquitto *mosq, const char *topic, int reading) {
    char payload[32];
    snprintf(payload, sizeof(payload), "%d", reading);
    int ret = mosquitto_publish(mosq, NULL, topic, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing MQTT message: %s\n", mosquitto_strerror(ret));
        return -1; // Indicate error
    }
    return 0; // Indicate success
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }
    mosquitto_lib_cleanup();
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Initialize libmosquitto
    mosquitto_lib_init();

    // Create a new Mosquitto client instance
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error creating Mosquitto client instance\n");
        gpioTerminate();
        return 1;
    }

    // Connect to the MQTT broker
    int ret = mosquitto_connect(mosq, MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Sensor node started. Publishing to %s/%s\n", MQTT_BROKER_ADDRESS, MQTT_TOPIC);

    // Main loop
    while (running) {
        int reading = read_sensor_data(GPIO_PIN);
        if (reading >= 0) {
            if (validate_reading(reading)) {
                if (publish_mqtt_message(mosq, MQTT_TOPIC, reading) != 0) {
                    fprintf(stderr, "Failed to publish sensor data\n");
                }
            } else {
                fprintf(stderr, "Skipping invalid sensor reading\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for the specified interval
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>
#include <mosquitto.h>

// Configuration
#define MQTT_BROKER "localhost" // Replace with your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor_data"
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define SAMPLE_INTERVAL_MS 1000
#define MAX_RETRIES 3

// Global variables
static volatile int running = 1;
static int i2c_handle;
static struct mosquitto *mosq = NULL;

// Function prototypes
int init_i2c();
int init_ads1115();
int read_ads1115(int *value);
int publish_mqtt(int value);
void signal_handler(int signal);
void cleanup();

// Structure to hold configuration data
typedef struct {
    char broker[256];
    int port;
    char topic[256];
    int i2c_address;
    int config_register;
    int conversion_register;
    int sample_interval_ms;
    int max_retries;
} config_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0); // Bus 1, address 0x48, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to initialize ADS1115
int init_ads1115() {
    // Configure ADS1115 for single-ended AIN0, +/- 4.096V, single-shot mode, 128 SPS
    char config[3];
    config[0] = CONFIG_REG;
    config[1] = 0x40; // Single-shot mode, AIN0, +/- 4.096V, 128 SPS
    config[2] = 0x83; // Disable comparator, non-latching, single-shot

    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(i2c_handle, config, 3) == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error writing to ADS1115 (attempt %d): %d\n", retries + 1, i2c_handle);
            retries++;
            gpioDelay(10000); // Wait 10ms before retrying
        }
    }
    fprintf(stderr, "Failed to write to ADS1115 after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to read ADS1115 value
int read_ads1115(int *value) {
    char config[3];
    config[0] = CONVERSION_REG;
    config[1] = 0x00; // Dummy byte for reading
    config[2] = 0x00; // Dummy byte for reading

    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(i2c_handle, config, 3) == 0) {
            char buffer[2];
            if (i2cReadDevice(i2c_handle, buffer, 2) == 2) {
                *value = (buffer[0] << 8) | buffer[1];
                return 0; // Success
            } else {
                fprintf(stderr, "Error reading from ADS1115 (attempt %d): %d\n", retries + 1, i2c_handle);
                retries++;
                gpioDelay(10000); // Wait 10ms before retrying
            }
        } else {
            fprintf(stderr, "Error writing to ADS1115 (attempt %d): %d\n", retries + 1, i2c_handle);
            retries++;
            gpioDelay(10000); // Wait 10ms before retrying
        }
    }
    fprintf(stderr, "Failed to read from ADS1115 after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to publish MQTT message
int publish_mqtt(int value) {
    char payload[256];
    snprintf(payload, sizeof(payload), "%d", value);

    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing MQTT message: %s\n", mosquitto_strerror(ret));
        return -1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (mosq) {
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize ADS1115
    if (init_ads1115() != 0) {
        cleanup();
        return 1;
    }

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error creating mosquitto instance\n");
        cleanup();
        return 1;
    }

    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(rc));
        cleanup();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int value;
    int i;

    // Main loop
    while (running) {
        if (read_ads1115(&value) == 0) {
            if (value > 32767 || value < -32768) {
                fprintf(stderr, "Warning: Sensor reading out of range: %d\n", value);
            } else {
                if (publish_mqtt(value) != 0) {
                    fprintf(stderr, "Error publishing MQTT message\n");
                }
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for sample interval
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

