#define GPIO_PIN 17
#define GPIO_PIN_2 18

struct gpiod_chip *chip;
struct gpiod_line *line;
struct gpiod_line *line2;

volatile sig_atomic_t program_running = 1;

void signal_handler(int sig) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int main() {
    int ret;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %m\n");
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %m\n", GPIO_PIN, chip);
        gpiod_chip_close(chip);
        return 1;
    }

    // Get GPIO line 2
    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        fprintf(stderr, "Error getting GPIO line %d: %m\n", GPIO_PIN_2, chip);
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(line, "gpio_control", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output: %m\n", GPIO_PIN, ret);
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        gpiod_line_release(line2);
        return 1;
    }

    ret = gpiod_line_request_output(line2, "gpio_control_2", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output: %m\n", GPIO_PIN_2, ret);
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        gpiod_line_release(line2);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Set GPIO 17 HIGH
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line %d HIGH: %m\n", GPIO_PIN, ret);
            break;
        }
        printf("GPIO %d set HIGH\n", GPIO_PIN);

        // Set GPIO 18 LOW
        ret = gpiod_line_set_value(line2, 0);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line %d LOW: %m\n", GPIO_PIN_2, ret);
            break;
        }
        printf("GPIO %d set LOW\n", GPIO_PIN_2);

        // Wait 0.05 seconds
        sleep(0.05);
    }

    // Release GPIO lines
    gpiod_line_release(line);
    gpiod_line_release(line2);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

