#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    program_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to initialize the MPU6050
int init_mpu6050() {
    // Wake up the MPU6050 (clear sleep mode bit)
    if (i2c_smbus_write_byte_data(i2c_fd, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read raw accelerometer data
int read_raw_accelerometer(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    if (i2c_smbus_read_i2c_block_data(i2c_fd, ACCEL_XOUT_H, buf, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Function to convert raw accelerometer data to g-force units
void convert_to_g(int16_t raw_x, int16_t raw_y, int16_t raw_z, float *x_g, float *y_g, float *z_g) {
    // Sensitivity scale factor for +/- 2g range
    const float sensitivity = 16384.0f;

    *x_g = (float)raw_x / sensitivity;
    *y_g = (float)raw_y / sensitivity;
    *z_g = (float)raw_z / sensitivity;
}

