// Function to read data from DHT22 sensor
int read_dht22(int gpio, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int laststate = PI_HIGH;
    int j = 0;

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, PI_LOW);
    gpioDelay(1);
    gpioWrite(gpio, PI_HIGH);
    gpioDelay(30);
    gpioSetMode(gpio, PI_INPUT);

    // Read data
    for (int i = 0; i < 85; i++) {
        int counter = 0;
        while (gpioRead(gpio) == laststate) {
            counter++;
            gpioDelay(1);
            if (counter == 255) {
                return -1; // Timeout
            }
        }
        laststate = gpioRead(gpio);

        if (counter > 3) {
            data[j / 8] <<= 1;
            if (counter > 16)
                data[j / 8] |= 1;
            j++;
        }
    }

    // Check checksum
    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        return -2; // Checksum error
    }

    // Convert data to temperature and humidity
    *humidity = (float)(((data[0] << 8) + data[1])) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature *= -1;
    }

    return 0; // Success
}

// Function to set PWM duty cycle
void set_pwm_duty_cycle(int gpio, int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    gpioPWM(gpio, duty_cycle);
}

