    gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PWM_PIN, PWM_RANGE);

    // Set PWM mode to mark:space
    gpioSetPWMmode(PWM_PIN, PI_PWM_MODE_MS);

