#include <time.h>
#include <mosquitto.h>
#include <pigpio.h>

// Configuration
#define MQTT_BROKER "localhost" // Replace with your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor_data"
#define GPIO_PIN 4
#define SAMPLE_INTERVAL_MS 1000

// Global variables
static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function prototypes
int init_gpio();
int read_sensor();
int publish_data(int sensor_value);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    int sensor_value;
    time_t timestamp;
} sensor_data_t;

// Initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN); // Optional: Set pull-down resistor

    return 0;
}

// Read sensor value
int read_sensor() {
    return gpioRead(GPIO_PIN);
}

// Publish data to MQTT broker
int publish_data(int sensor_value) {
    char payload[10];
    snprintf(payload, sizeof(payload), "%d", sensor_value);

    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing data: %s\n", mosquitto_strerror(ret));
        return -1;
    }

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup resources
void cleanup() {
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }
    mosquitto_lib_cleanup();
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (init_gpio() != 0) {
        return 1;
    }

    // Initialize libmosquitto
    mosquitto_lib_init();

    // Create a new Mosquitto client instance
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        cleanup();
        return 1;
    }

    // Connect to the MQTT broker
    int ret = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(ret));
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting sensor data publishing...\n");

    // Main loop
    while (running) {
        int sensor_value = read_sensor();
        if (sensor_value >= 0) {
            if (publish_data(sensor_value) != 0) {
                fprintf(stderr, "Failed to publish sensor data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor value.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for the specified interval
    }

    // Cleanup and exit
    cleanup();
    printf("Exiting.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for PWM outputs
#define PWM_PIN_1 2
#define PWM_PIN_2 3
#define PWM_PIN_3 18
#define PWM_PIN_4 23
#define PWM_PIN_5 24

// PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// PWM range (0-255)
#define PWM_RANGE 255

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the PWM duty cycle for a given GPIO pin
int set_pwm_duty_cycle(int gpio_pin, int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > PWM_RANGE) {
        fprintf(stderr, "Error: Duty cycle must be between 0 and %d\n", PWM_RANGE);
        return -1;
    }
    gpioPWM(gpio_pin, duty_cycle);
    return 0;
}

// Function to set the PWM frequency for a given GPIO pin
int set_pwm_frequency(int gpio_pin, int frequency) {
    if (frequency <= 0) {
        fprintf(stderr, "Error: Frequency must be greater than 0\n");
        return -1;
    }
    gpioSetPWMfrequency(gpio_pin, frequency);
    return 0;
}

// Function to initialize a GPIO pin for PWM output
int initialize_gpio_pin(int gpio_pin) {
    if (gpioSetMode(gpio_pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", gpio_pin);
        return -1;
    }
    if (set_pwm_frequency(gpio_pin, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency for GPIO %d\n", gpio_pin);
        return -1;
    }
    return 0;
}

// Function to release a GPIO pin
int release_gpio_pin(int gpio_pin) {
    gpioPWM(gpio_pin, 0); // Stop PWM output
    gpioSetMode(gpio_pin, PI_INPUT); // Set to input to avoid floating output
    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO pins for PWM output
    if (initialize_gpio_pin(PWM_PIN_1) != 0 ||
        initialize_gpio_pin(PWM_PIN_2) != 0 ||
        initialize_gpio_pin(PWM_PIN_3) != 0 ||
        initialize_gpio_pin(PWM_PIN_4) != 0 ||
        initialize_gpio_pin(PWM_PIN_5) != 0) {
        // Release already initialized pins before exiting
        release_gpio_pin(PWM_PIN_1);
        release_gpio_pin(PWM_PIN_2);
        release_gpio_pin(PWM_PIN_3);
        release_gpio_pin(PWM_PIN_4);
        release_gpio_pin(PWM_PIN_5);

        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Set PWM duty cycles for each GPIO pin
        if (set_pwm_duty_cycle(PWM_PIN_1, 128) != 0 ||
            set_pwm_duty_cycle(PWM_PIN_2, 192) != 0 ||
            set_pwm_duty_cycle(PWM_PIN_3, 255) != 0 ||
            set_pwm_duty_cycle(PWM_PIN_4, 128) != 0 ||
            set_pwm_duty_cycle(PWM_PIN_5, 192) != 0) {
            fprintf(stderr, "Error: Failed to set PWM duty cycle\n");
            break; // Exit loop on error
        }

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 milliseconds = 100000 microseconds

        // Set PWM duty cycles for each GPIO pin to 0
        if (set_pwm_duty_cycle(PWM_PIN_1, 0) != 0 ||
            set_pwm_duty_cycle(PWM_PIN_2, 0) != 0 ||
            set_pwm_duty_cycle(PWM_PIN_3, 0) != 0 ||
            set_pwm_duty_cycle(PWM_PIN_4, 0) != 0 ||
            set_pwm_duty_cycle(PWM_PIN_5, 0) != 0) {
            fprintf(stderr, "Error: Failed to set PWM duty cycle to 0\n");
            break; // Exit loop on error
        }

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 milliseconds = 100000 microseconds
    }

    // Release GPIO pins before exiting
    release_gpio_pin(PWM_PIN_1);
    release_gpio_pin(PWM_PIN_2);
    release_gpio_pin(PWM_PIN_3);
    release_gpio_pin(PWM_PIN_4);
    release_gpio_pin(PWM_PIN_5);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for PWM output
#define PWM_PIN_1 17
#define PWM_PIN_2 22
#define PWM_PIN_3 27

// PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// PWM range (0-255)
#define PWM_RANGE 255

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PWM_PIN_1, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_2, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_3, PWM_RANGE);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Set PWM duty cycle for GPIO 17 (50%)
        gpioPWM(PWM_PIN_1, PWM_RANGE / 2);

        // Set PWM duty cycle for GPIO 22 (75%)
        gpioPWM(PWM_PIN_2, PWM_RANGE * 3 / 4);

        // Set PWM duty cycle for GPIO 27 (25%)
        gpioPWM(PWM_PIN_3, PWM_RANGE / 4);

        // Wait for 0.05 seconds
        gpioDelay(500000); // 500000 microseconds = 0.05 seconds
    }

    // Release GPIO pins
    gpioWrite(PWM_PIN_1, 0);
    gpioWrite(PWM_PIN_2, 0);
    gpioWrite(PWM_PIN_3, 0);
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <errno.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_FORMAT V4L2_PIX_FMT_MJPEG
#define IMAGE_SIZE (IMAGE_WIDTH * IMAGE_HEIGHT * 3 / 2) // MJPEG format
#define CAPTURE_INTERVAL_SEC 1

static int fd = -1; // File descriptor for the device
static volatile sig_atomic_t keep_running = 1;

// Signal handler for Ctrl+C
void int_handler(int dummy) {
    keep_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to initialize the camera device
int init_camera(const char *device_name) {
    int fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return -1;
    }

    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device %s is not a video capture device\n", device_name);
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device %s does not support streaming i/o\n", device_name);
        close(fd);
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = IMAGE_FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return -1;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return -1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("Error querying buffer");
        close(fd);
        return -1;
    }

    void *buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("Error mapping buffer");
        close(fd);
        return -1;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        munmap(buffer, buf.length);
        close(fd);
        return -1;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        munmap(buffer, buf.length);
        close(fd);
        return -1;
    }

    return fd;
}

// Function to capture an image from the camera
int capture_image(int fd, unsigned char *buffer, size_t buffer_size) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    if (buf.bytesused > buffer_size) {
        fprintf(stderr, "Error: Buffer size too small (%zu bytes, expected %d)\n", buf.bytesused, buffer_size);
        return -1;
    }

    memcpy(buffer, buffer, buf.bytesused);

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        return -1;
    }

    return 0;
}

// Function to save the image to a file
int save_image(const char *filename, const unsigned char *buffer, size_t buffer_size) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("Error opening file for writing");
        return -1;
    }

    size_t bytes_written = fwrite(buffer, 1, buffer_size, fp);
    if (bytes_written != buffer_size) {
        fprintf(stderr, "Error writing to file (%zu bytes written, expected %zu)\n", bytes_written, buffer_size);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, int_handler);

    // Initialize the camera
    fd = init_camera(DEVICE_NAME);
    if (fd < 0) {
        fprintf(stderr, "Failed to initialize camera. Exiting.\n");
        return 1;
    }

    unsigned char *image_buffer = (unsigned char *)malloc(IMAGE_SIZE);
    if (image_buffer == NULL) {
        perror("Error allocating memory for image buffer");
        close(fd);
        return 1;
    }

    printf("Capturing images every %d seconds...\n", CAPTURE_INTERVAL_SEC);

    // Capture images until Ctrl+C is pressed
    while (keep_running) {
        if (capture_image(fd, image_buffer, IMAGE_SIZE) == 0) {
            char filename[64];
            snprintf(filename, sizeof(filename), "image_%06d.jpg", time(NULL));
            printf("Saving image to %s\n", filename);

            if (save_image(filename, image_buffer, IMAGE_SIZE) != 0) {
                fprintf(stderr, "Failed to save image.\n");
            }
        } else {
            fprintf(stderr, "Failed to capture image.\n");
        }

        sleep(CAPTURE_INTERVAL_SEC);
    }

    // Clean up
    printf("Cleaning up...\n");
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
    }

    munmap(image_buffer, IMAGE_SIZE);
    close(fd);

    free(image_buffer);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_SIZE (IMAGE_WIDTH * IMAGE_HEIGHT * 2) // YUYV format
#define NUM_BUFFERS 4

// Global variables
static int fd = -1;
static void *buffers[NUM_BUFFERS];
static unsigned int buffer_count = 0;
static volatile sig_atomic_t running = 1;

// Structure to hold image data
typedef struct {
    unsigned char *data;
    size_t size;
} image_t;

// Function prototypes
int init_camera();
int capture_image(image_t *image);
int save_image(const image_t *image, const char *filename);
void cleanup();
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", sig);
}

// Initialize the camera device
int init_camera() {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned int i;

    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return -1;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture.\n");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O.\n");
        close(fd);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return -1;
    }

    if (req.count < NUM_BUFFERS) {
        fprintf(stderr, "Insufficient buffer memory\n");
        close(fd);
        return -1;
    }

    for (i = 0; i < req.count; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Error querying buffer");
            close(fd);
            return -1;
        }

        buffers[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[i] == MAP_FAILED) {
            perror("Error mapping buffer");
            close(fd);
            return -1;
        }

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queuing buffer");
            close(fd);
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        close(fd);
        return -1;
    }

    return 0;
}

// Capture an image from the camera
int capture_image(image_t *image) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    image->data = buffers[buf.index];
    image->size = buf.bytesused;

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        return -1;
    }

    return 0;
}

// Save the image to a file
int save_image(const image_t *image, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("Error opening file for writing");
        return -1;
    }

    size_t bytes_written = fwrite(image->data, 1, image->size, fp);
    if (bytes_written != image->size) {
        fprintf(stderr, "Error writing to file: wrote %zu bytes, expected %zu\n", bytes_written, image->size);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (fd != -1) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
            perror("Error stopping stream");
        }

        for (unsigned int i = 0; i < buffer_count; ++i) {
            if (munmap(buffers[i], buffers[i]) < 0) {
                perror("Error unmapping buffer");
            }
        }

        close(fd);
    }
}

int main() {
    image_t image;

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the camera
    if (init_camera() < 0) {
        fprintf(stderr, "Camera initialization failed. Exiting.\n");
        return 1;
    }

    buffer_count = NUM_BUFFERS;

    // Capture and save the image
    if (capture_image(&image) == 0 && save_image(&image, "image.yuyv") == 0) {
        printf("Image saved to image.yuyv\n");
    } else {
        fprintf(stderr, "Failed to capture or save image.\n");
    }

    // Cleanup resources
    cleanup();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_PIN 2
#define GPIO_PIN_3 3

struct gpiod_chip *chip;
struct gpiod_line *line;
struct gpiod_line *line3;

volatile sig_atomic_t program_running = 1;

void signal_handler(int sig) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int main() {
    int ret;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %m\n");
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %m\n", GPIO_PIN, chip);
        gpiod_chip_close(chip);
        return 1;
    }

    // Get GPIO line 3
    line3 = gpiod_chip_get_line(chip, GPIO_PIN_3);
    if (!line3) {
        fprintf(stderr, "Error getting GPIO line %d: %m\n", GPIO_PIN_3, chip);
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(line, "gpio_control", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output: %m\n", GPIO_PIN, chip);
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        gpiod_line_release(line3);
        return 1;
    }

    // Request GPIO line 3 for input
    ret = gpiod_line_request_input(line3, "gpio_input");
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for input: %m\n", GPIO_PIN_3, chip);
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        gpiod_line_release(line3);
        gpiod_line_release(line);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read GPIO line 3
        int value = gpiod_line_get_value(line3);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO line %d: %m\n", GPIO_PIN_3, chip);
            break;
        }

        // Set GPIO line 2 based on GPIO line 3 value
        ret = gpiod_line_set_value(line, value);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line %d: %m\n", GPIO_PIN, chip);
            break;
        }

        // Print GPIO line 2 state
        printf("GPIO %d: %d\n", GPIO_PIN, value);

        // Wait for 0.5 seconds
        sleep(0.5);
    }

    // Release GPIO lines
    gpiod_line_release(line);
    gpiod_line_release(line3);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

