#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define UART_PORT "/dev/ttyS0" // Or /dev/ttyAMA0
#define BAUD_RATE B9600
#define DATA_BITS 8
#define STOP_BITS 1
#define PARITY_NONE 'N'

int uart_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (uart_fd != -1) {
        close(uart_fd);
    }
    exit(0);
}

// Function to initialize the UART port
int init_uart(const char *port, speed_t baud_rate, int data_bits, int stop_bits, char parity) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud_rate);
    cfsetispeed(&tty, baud_rate);

    tty.c_cflag &= ~PARENB; // No parity
    tty.c_cflag &= ~CSTOPB; // 1 stop bit
    tty.c_cflag &= ~CSIZE;  // Clear data size bits
    tty.c_cflag |= CS8;   // 8 data bits

    tty.c_lflag &= ~ICANON; // Disable canonical mode
    tty.c_lflag &= ~ECHO;   // Disable echo
    tty.c_lflag &= ~ECHOE;  // Disable erasure
    tty.c_lflag &= ~ECHONL; // Disable new-line echo
    tty.c_lflag &= ~ISIG;   // Disable interpretation of INTR, QUIT and SUSP

    tty.c_iflag &= ~(IXON | IXOFF | IXANY); // Turn off software flow control
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);

    tty.c_oflag &= ~OPOST; // Prevent special interpretation of output bytes (e.g. newline chars)

    tty.c_cc[VMIN] = 0;  // Read non-blocking
    tty.c_cc[VTIME] = 5; // Wait for 0.5 seconds (5 * 0.1s)

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read data from the UART port
int read_uart_data(int fd, char *buffer, size_t buffer_size) {
    ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
    if (bytes_read == -1) {
        perror("Error reading from UART port");
        return -1;
    } else if (bytes_read == 0) {
        // No data available
        return 0;
    }

    buffer[bytes_read] = '\0'; // Null-terminate the buffer
    return bytes_read;
}

// Function to parse the received data and validate it
int parse_data(const char *data) {
    int value = atoi(data);
    if (value < -100 || value > 100) {
        fprintf(stderr, "Error: Invalid data value: %s\n", data);
        return -1;
    }
    return value;
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize UART
    uart_fd = init_uart(UART_PORT, BAUD_RATE, DATA_BITS, STOP_BITS, PARITY_NONE);
    if (uart_fd == -1) {
        return 1;
    }

    char buffer[256];
    int bytes_read;

    printf("UART initialized. Reading data...\n");

    while (1) {
        bytes_read = read_uart_data(uart_fd, buffer, sizeof(buffer));
        if (bytes_read > 0) {
            int parsed_value = parse_data(buffer);
            if (parsed_value != -1) {
                printf("Received: %s, Parsed: %d\n", buffer, parsed_value);
            }
        } else if (bytes_read < 0) {
            // Error already handled by read_uart_data
            break; // Exit loop on error
        }
        usleep(100000); // Sleep for 100ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    close(uart_fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define GPIO_18 18
#define GPIO_23 23
#define GPIO_24 24

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to export a GPIO pin
int export_gpio(int gpio) {
    char buffer[64];
    int len;
    int fd;

    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening /sys/class/gpio/export: %m\n", errno);
        return -1;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", gpio);
    if (write(fd, buffer, len) != len) {
        fprintf(stderr, "Error writing to /sys/class/gpio/export: %m\n", errno);
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to unexport a GPIO pin
int unexport_gpio(int gpio) {
    char buffer[64];
    int len;
    int fd;

    fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening /sys/class/gpio/unexport: %m\n", errno);
        return -1;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", gpio);
    if (write(fd, buffer, len) != len) {
        fprintf(stderr, "Error writing to /sys/class/gpio/unexport: %m\n", errno);
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to set the direction of a GPIO pin (in or out)
int set_gpio_direction(int gpio, const char *direction) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", gpio);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %m\n", path, errno);
        return -1;
    }

    if (write(fd, direction, strlen(direction)) != strlen(direction)) {
        fprintf(stderr, "Error writing to %s: %m\n", path, errno);
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to read the value of a GPIO pin
int read_gpio_value(int gpio) {
    char path[64];
    char value_str[3];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", gpio);
    fd = open(path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %m\n", path, errno);
        return -1;
    }

    if (read(fd, value_str, 3) < 0) {
        fprintf(stderr, "Error reading from %s: %m\n", path, errno);
        close(fd);
        return -1;
    }

    close(fd);
    return atoi(value_str);
}

// Function to write a value to a GPIO pin
int write_gpio_value(int gpio, int value) {
    char path[64];
    char value_str[3];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", gpio);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %m\n", path, errno);
        return -1;
    }

    snprintf(value_str, sizeof(value_str), "%d", value);
    if (write(fd, value_str, strlen(value_str)) != strlen(value_str)) {
        fprintf(stderr, "Error writing to %s: %m\n", path, errno);
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int value;

    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %m\n", GPIO_CHIP, errno);
        return 1;
    }

    // Export GPIO pins
    if (export_gpio(GPIO_18) < 0 || export_gpio(GPIO_23) < 0 || export_gpio(GPIO_24) < 0) {
        fprintf(stderr, "Error exporting GPIO pins. Exiting.\n");
        goto cleanup;
    }

    // Set GPIO directions to output
    if (set_gpio_direction(GPIO_18, "out") < 0 || set_gpio_direction(GPIO_23, "out") < 0 || set_gpio_direction(GPIO_24, "out") < 0) {
        fprintf(stderr, "Error setting GPIO directions. Exiting.\n");
        goto cleanup;
    }

    // Main loop
    while (program_running) {
        // Read GPIO values
        value = read_gpio_value(GPIO_18);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO %d. Continuing.\n", GPIO_18);
        } else {
            printf("GPIO %d: %d\n", GPIO_18, value);
        }

        value = read_gpio_value(GPIO_23);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO %d. Continuing.\n", GPIO_23);
        } else {
            printf("GPIO %d: %d\n", GPIO_23, value);
        }

        value = read_gpio_value(GPIO_24);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO %d. Continuing.\n", GPIO_24);
        } else {
            printf("GPIO %d: %d\n", GPIO_24, value);
        }

        // Wait for 1 second
        sleep(1);
    }

cleanup:
    // Unexport GPIO pins
    unexport_gpio(GPIO_18);
    unexport_gpio(GPIO_23);
    unexport_gpio(GPIO_24);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pin for PWM output
#define PWM_PIN 18

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Define PWM range (0-255)
#define PWM_RANGE 255

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 18 as output
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PWM_PIN, PWM_RANGE);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Set PWM duty cycle to 128 (50%)
        gpioPWM(PWM_PIN, 128);
        printf("PWM Duty Cycle: 128 (50%%)\n");

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds

        // Set PWM duty cycle to 0 (0%)
        gpioPWM(PWM_PIN, 0);
        printf("PWM Duty Cycle: 0 (0%%)\n");

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Release GPIO 18 (BCM numbering)
    gpioSetMode(PWM_PIN, PI_INPUT); // Set to input to avoid floating output
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 27
#define GPIO_DIRECTION "out"

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int main() {
    int ret;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIO_CHIP);
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %d\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set GPIO direction to output
    ret = gpiod_line_request_output(line, GPIO_DIRECTION, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO direction: %d\n", ret);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("GPIO %d set to %s\n", GPIO_PIN, GPIO_DIRECTION);

    // Main loop
    while (!terminate) {
        // Read GPIO value
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO value: %d\n", value);
            break;
        }

        // Print GPIO value
        printf("GPIO %d value: %d\n", GPIO_PIN, value);

        // Set GPIO value to the opposite
        ret = gpiod_line_set_value(line, !value);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO value: %d\n", ret);
            break;
        }

        // Wait for 2 seconds
        sleep(2);
    }

    // Release GPIO line
    gpiod_line_release(line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    printf("GPIO %d released and chip closed.\n", GPIO_PIN);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for PWM output
#define PWM_PIN_1 8
#define PWM_PIN_2 9
#define PWM_PIN_3 10
#define PWM_PIN_4 11
#define PWM_PIN_5 17

// PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// PWM range (0-255)
#define PWM_RANGE 255

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the PWM duty cycle for a given GPIO pin
void set_pwm_duty_cycle(int gpio_pin, int duty_cycle) {
    if (duty_cycle < 0) {
        duty_cycle = 0;
    } else if (duty_cycle > PWM_RANGE) {
        duty_cycle = PWM_RANGE;
    }
    gpioPWM(gpio_pin, duty_cycle);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);
    gpioSetMode(PWM_PIN_4, PI_OUTPUT);
    gpioSetMode(PWM_PIN_5, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_4, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_5, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PWM_PIN_1, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_2, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_3, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_4, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_5, PWM_RANGE);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Set PWM duty cycles for each GPIO pin
        set_pwm_duty_cycle(PWM_PIN_1, 128);
