// Function to read data from a DHT22 sensor
int read_dht22(int gpio_pin, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int laststate = PI_HIGH;
    int j = 0;

    gpioSetMode(gpio_pin, PI_OUTPUT);
    gpioWrite(gpio_pin, PI_LOW);
    gpioDelay(18);
    gpioWrite(gpio_pin, PI_HIGH);
    gpioDelay(40);

    gpioSetMode(gpio_pin, PI_INPUT);

    // Read data
    for (int i = 0; i < 85; i++) {
        int counter = 0;
        while (gpioRead(gpio_pin) == laststate) {
            counter++;
            gpioDelay(1);
            if (counter == 255) {
                return -1; // Timeout
            }
        }
        laststate = gpioRead(gpio_pin);

        if (counter > 3) {
            data[j / 8] <<= 1;
            if (counter > 16)
                data[j / 8] |= 1;
            j++;
        }
    }

    // Check checksum
    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        return -2; // Checksum error
    }

    // Convert data to temperature and humidity
    *humidity = (float)(((data[0] << 8) + data[1])) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature = -*temperature;
    }

    return 0; // Success
}

// Function to format data into a CSV string
char* format_data(float temperature1, float humidity1, float temperature2, float humidity2, float temperature3, float humidity3) {
    time_t rawtime;
