    static char csv_string[256]; // Static to retain value between calls

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    snprintf(csv_string, sizeof(csv_string), "%s,%.1f,%.1f,%.1f,%.1f,%.1f\n",
             timestamp, temperature1, humidity1, temperature2, humidity2, temperature3, humidity3);

    return csv_string;
}

