// Function to export a GPIO pin
int export_gpio(int gpio) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip.\n");
        return -1;
    }

    line = gpiod_chip_get_line(chip, gpio);
    if (!line) {
        fprintf(stderr, "Error: Could not get GPIO line %d.\n", gpio);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(line, "gpio_control", 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d as output.\n", gpio);
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

