#define PWM_RANGE 255

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the PWM duty cycle for a given GPIO pin
void set_pwm_duty_cycle(int gpio_pin, int duty_cycle) {
    if (duty_cycle < 0) {
        duty_cycle = 0;
    } else if (duty_cycle > PWM_RANGE) {
        duty_cycle = PWM_RANGE;
    }
    gpioPWM(gpio_pin, duty_cycle);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);
    gpioSetMode(PWM_PIN_4, PI_OUTPUT);
    gpioSetMode(PWM_PIN_5, PI_OUTPUT);
    gpioSetMode(PWM_PIN_6, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_4, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_5, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_6, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PWM_PIN_1, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_2, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_3, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_4, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_5, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_6, PWM_RANGE);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Set PWM duty cycles for each GPIO pin
        set_pwm_duty_cycle(PWM_PIN_1, 100);
        set_pwm_duty_cycle(PWM_PIN_2, 150);
        set_pwm_duty_cycle(PWM_PIN_3, 200);
        set_pwm_duty_cycle(PWM_PIN_4, 255);
        set_pwm_duty_cycle(PWM_PIN_5, 200);
        set_pwm_duty_cycle(PWM_PIN_6, 150);

        // Print the PWM duty cycles to standard output
        printf("PWM Duty Cycle 1: %d, PWM Duty Cycle 2: %d, PWM Duty Cycle 3: %d, PWM Duty Cycle 4: %d, PWM Duty Cycle 5: %d, PWM Duty Cycle 6: %d\n",
               gpioGetPWMdutycycle(PWM_PIN_1), gpioGetPWMdutycycle(PWM_PIN_2), gpioGetPWMdutycycle(PWM_PIN_3), gpioGetPWMdutycycle(PWM_PIN_4), gpioGetPWMdutycycle(PWM_PIN_5), gpioGetPWMdutycycle(PWM_PIN_6));

        // Wait for 1 second
        sleep(1);
    }

    // Stop PWM output on all GPIO pins
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioPWM(PWM_PIN_4, 0);
    gpioPWM(PWM_PIN_5, 0);
    gpioPWM(PWM_PIN_6, 0);

    // Release GPIO pins
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define GPIO_PIN_1 17
#define GPIO_PIN_2 18

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Global variables for GPIO lines
struct gpiod_line *gpio_line_1 = NULL;
struct gpiod_line *gpio_line_2 = NULL;

// Function prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_set_value(int pin, int value);
int gpio_get_value(int pin);
void cleanup(int signal);

// Signal handler for Ctrl+C
void cleanup(int signal) {
    printf("\nCleaning up and exiting...\n");

    // Unexport GPIO pins
    if (gpio_line_1) {
        gpiod_line_release(gpio_line_1);
    }
    if (gpio_line_2) {
        gpiod_line_release(gpio_line_2);
    }

    // Close GPIO chip
    gpiod_chip_close(gpio_line_1->chip);

    exit(0);
}

// Function to export a GPIO pin
int gpio_export(int pin) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request(line, "gpio_export", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

// Function to unexport a GPIO pin
int gpio_unexport(int pin) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_release(line);
    if (ret < 0) {
        perror("Error releasing GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

// Function to set the direction of a GPIO pin (in or out)
int gpio_set_direction(int pin, const char *direction) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_set_direction(line, direction);
    if (ret < 0) {
        perror("Error setting GPIO line direction");
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

// Function to set the value of a GPIO pin (0 or 1)
int gpio_set_value(int pin, int value) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        perror("Error setting GPIO line value");
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

// Function to get the value of a GPIO pin
int gpio_get_value(int pin) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_get_value(line);
    if (ret < 0) {
        perror("Error getting GPIO line value");
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return ret;
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, cleanup);

    // Export GPIO pins
    if (gpio_export(GPIO_PIN_1) < 0) {
        return 1;
    }
    if (gpio_export(GPIO_PIN_2) < 0) {
        gpio_unexport(GPIO_PIN_1);
        return 1;
    }

    // Set GPIO direction to output
    if (gpio_set_direction(GPIO_PIN_1, "out") < 0) {
        gpio_unexport(GPIO_PIN_1);
        gpio_unexport(GPIO_PIN_2);
        return 1;
    }
    if (gpio_set_direction(GPIO_PIN_2, "out") < 0) {
        gpio_unexport(GPIO_PIN_1);
        gpio_unexport(GPIO_PIN_2);
        return 1;
    }

    // Main loop
    for (int i = 0; i < 3; i++) {
        // Set GPIO value to 1
        if (gpio_set_value(GPIO_PIN_1, 1) < 0) {
            cleanup(0);
            return 1;
        }
        if (gpio_set_value(GPIO_PIN_2, 1) < 0) {
            cleanup(0);
            return 1;
        }

        // Wait for 1 second
        sleep(1);

        // Set GPIO value to 0
        if (gpio_set_value(GPIO_PIN_1, 0) < 0) {
            cleanup(0);
            return 1;
        }
        if (gpio_set_value(GPIO_PIN_2, 0) < 0) {
            cleanup(0);
            return 1;
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    cleanup(0);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define GPIO_DIRECTION "out"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

int main() {
    int ret;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIO_CHIP);
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %d\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(line, GPIO_DIRECTION, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line for output: %d\n", ret);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("GPIO %d initialized as output. Press Ctrl+C to exit.\n", GPIO_PIN);

    // Main loop
    while (!terminate) {
        // Set GPIO line to HIGH
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line value to HIGH: %d\n", ret);
            break;
        }
        printf("GPIO %d set to HIGH\n", GPIO_PIN);

        // Wait for 5 seconds
        sleep(5);

        // Set GPIO line to LOW
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line value to LOW: %d\n", ret);
            break;
        }
        printf("GPIO %d set to LOW\n", GPIO_PIN);

        // Wait for 5 seconds
        sleep(5);
    }

    // Release GPIO line
    gpiod_line_release(line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    printf("GPIO %d terminated.\n", GPIO_PIN);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <stdint.h>

// Define the I2C address of the PCF8574
#define PCF8574_ADDR 0x48

// Define the I2C bus (usually /dev/i2c-1 on Raspberry Pi)
#define I2C_BUS "/dev/i2c-1"

// Global variable to store the I2C file descriptor
int i2c_fd;

// Function to handle Ctrl+C signal
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    // Close the I2C file descriptor
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the PCF8574
int pcf8574_init(int fd) {
    // Set all pins to output mode (0x00)
    if (write(fd, "\x00", 1) != 1) {
        perror("Error writing to PCF8574");
        return -1;
    }
    return 0;
}

// Function to display a value on the PCF8574
int pcf8574_display(int fd, int value) {
    // Ensure the value is within the valid range (0-255)
    if (value < 0 || value > 255) {
        fprintf(stderr, "Error: Invalid value for PCF8574: %d\n", value);
        return -1;
    }

    // Write the value to the PCF8574
    if (write(fd, &value, 1) != 1) {
        perror("Error writing to PCF8574");
        return -1;
    }
    return 0;
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, PCF8574_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize the PCF8574
    if (pcf8574_init(i2c_fd) != 0) {
        close(i2c_fd);
        return 1;
    }

    // Main loop to display values
    while (1) {
        // Display values from 0 to 255
        for (int i = 0; i <= 255; i++) {
            if (pcf8574_display(i2c_fd, i) != 0) {
                close(i2c_fd);
                return 1;
            }
            usleep(500000); // 0.5 seconds
        }

        // Display values from 255 to 0
        for (int i = 255; i >= 0; i--) {
            if (pcf8574_display(i2c_fd, i) != 0) {
                close(i2c_fd);
                return 1;
            }
            usleep(500000); // 0.5 seconds
        }
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    close(i2c_fd);
    return 0;
}

