#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define GPIO_4 4
#define GPIO_17 17
#define GPIO_22 22
#define GPIO_23 23
#define GPIO_24 24
#define GPIO_27 27

// Global variable to track if the program should exit
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to set the state of a GPIO pin
int set_gpio_state(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d state: %d\n", line->number, ret);
        return -1;
    }
    return 0;
}

// Function to export a GPIO pin
int export_gpio(struct gpiod_chip *chip, int pin) {
    int ret = gpiod_chip_export_line(chip, pin);
    if (ret < 0) {
        fprintf(stderr, "Error exporting GPIO %d: %d\n", pin, ret);
        return -1;
    }
    return 0;
}

// Function to unexport a GPIO pin
int unexport_gpio(struct gpiod_chip *chip, int pin) {
    int ret = gpiod_chip_unexport_line(chip, pin);
    if (ret < 0) {
        fprintf(stderr, "Error unexporting GPIO %d: %d\n", pin, ret);
        return -1;
    }
    return 0;
}

// Function to open a GPIO line
struct gpiod_line *open_gpio_line(struct gpiod_chip *chip, int pin) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error getting GPIO %d line\n", pin);
        return NULL;
    }
    return line;
}

// Function to set the direction of a GPIO line (in or out)
int set_gpio_direction(struct gpiod_line *line, const char *direction) {
    int ret = gpiod_line_set_direction(line, direction);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d direction to %s: %d\n", line->number, direction, ret);
        return -1;
    }
    return 0;
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return 1;
    }

    // Export GPIO pins
    if (export_gpio(chip, GPIO_4) ||
        export_gpio(chip, GPIO_17) ||
        export_gpio(chip, GPIO_22) ||
        export_gpio(chip, GPIO_23) ||
        export_gpio(chip, GPIO_24) ||
        export_gpio(chip, GPIO_27)) {
        gpiod_chip_close(chip);
        return 1;
    }

    // Open GPIO lines
    struct gpiod_line *gpio4_line = open_gpio_line(chip, GPIO_4);
    struct gpiod_line *gpio17_line = open_gpio_line(chip, GPIO_17);
    struct gpiod_line *gpio22_line = open_gpio_line(chip, GPIO_22);
    struct gpiod_line *gpio23_line = open_gpio_line(chip, GPIO_23);
    struct gpiod_line *gpio24_line = open_gpio_line(chip, GPIO_24);
    struct gpiod_line *gpio27_line = open_gpio_line(chip, GPIO_27);

    if (!gpio4_line || !gpio17_line || !gpio22_line || !gpio23_line || !gpio24_line || !gpio27_line) {
        // Cleanup already exported pins
        unexport_gpio(chip, GPIO_4);
        unexport_gpio(chip, GPIO_17);
        unexport_gpio(chip, GPIO_22);
        unexport_gpio(chip, GPIO_23);
        unexport_gpio(chip, GPIO_24);
        unexport_gpio(chip, GPIO_27);

        gpiod_chip_close(chip);
        return 1;
    }

    // Set GPIO directions to output
    if (set_gpio_direction(gpio4_line, "out") ||
        set_gpio_direction(gpio17_line, "out") ||
        set_gpio_direction(gpio22_line, "out") ||
        set_gpio_direction(gpio23_line, "out") ||
        set_gpio_direction(gpio24_line, "out") ||
        set_gpio_direction(gpio27_line, "out")) {
        // Cleanup already exported pins
        unexport_gpio(chip, GPIO_4);
        unexport_gpio(chip, GPIO_17);
        unexport_gpio(chip, GPIO_22);
        unexport_gpio(chip, GPIO_23);
        unexport_gpio(chip, GPIO_24);
        unexport_gpio(chip, GPIO_27);

        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Set GPIO states
        if (set_gpio_state(gpio4_line, 1) ||
            set_gpio_state(gpio17_line, 0) ||
            set_gpio_state(gpio22_line, 1) ||
            set_gpio_state(gpio23_line, 0) ||
            set_gpio_state(gpio24_line, 1) ||
            set_gpio_state(gpio27_line, 0)) {
            break; // Exit loop on error
        }

        // Print GPIO states to standard output
        printf("GPIO %d: %d, GPIO %d: %d, GPIO %d: %d, GPIO %d: %d, GPIO %d: %d, GPIO %d: %d\n",
               GPIO_4, gpiod_line_get_value(gpio4_line),
               GPIO_17, gpiod_line_get_value(gpio17_line),
               GPIO_22, gpiod_line_get_value(gpio22_line),
               GPIO_23, gpiod_line_get_value(gpio23_line),
               GPIO_24, gpiod_line_get_value(gpio24_line),
               GPIO_27, gpiod_line_get_value(gpio27_line));

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup: Unexport GPIO pins
    unexport_gpio(chip, GPIO_4);
    unexport_gpio(chip, GPIO_17);
    unexport_gpio(chip, GPIO_22);
    unexport_gpio(chip, GPIO_23);
    unexport_gpio(chip, GPIO_24);
    unexport_gpio(chip, GPIO_27);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

