    struct gpiod_line *line17 = gpiod_chip_get_line(chip, GPIO_17);
    struct gpiod_line *line18 = gpiod_chip_get_line(chip, GPIO_18);
    struct gpiod_line *line24 = gpiod_chip_get_line(chip, GPIO_24);

    if (!line17 || !line18 || !line24) {
        fprintf(stderr, "Error: Could not get GPIO line for pin %d, %d, or %d\n", GPIO_17, GPIO_18, GPIO_24);
        gpiod_chip_close(chip);
        return 1;
    }

    int ret = gpiod_line_request_output(line17, "gpio_control", 0);
    if (ret < 0) {
