#include <pigpio.h>

// Define the GPIO pin for the PWM output
#define PWM_PIN 18

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pin as an output
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Set the PWM frequency (e.g., 1 kHz)
    gpioSetPWMfrequency(PWM_PIN, 1000);

    // Set the PWM range (0-255)
    gpioSetPWMrange(PWM_PIN, 255);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop to control the PWM output
    while (program_running) {
        // Set the PWM duty cycle to 128 (50%)
        gpioPWM(PWM_PIN, 128);
        printf("PWM Duty Cycle: 128 (50%%)\n");

        // Wait for 5 seconds
        sleep(5);

        // Set the PWM duty cycle to 0 (0%)
        gpioPWM(PWM_PIN, 0);
        printf("PWM Duty Cycle: 0 (0%%)\n");

        // Wait for 5 seconds
        sleep(5);
    }

    // Stop the PWM output
    gpioPWM(PWM_PIN, 0);

    // Release the GPIO pin
    gpioSetMode(PWM_PIN, PI_INPUT); // Set to input to avoid floating output

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

