// Define the I2C address of the PCF8574
#define PCF8574_ADDR 0x48

// Define the I2C bus (usually /dev/i2c-1 on Raspberry Pi)
#define I2C_BUS "/dev/i2c-1"

// Global variable to store the I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the PCF8574
int pcf8574_init(int fd) {
    // Set all pins as output (optional, but good practice)
    if (ioctl(fd, I2C_SLAVE, PCF8574_ADDR) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }
    return 0;
}

// Function to read a byte from the PCF8574
int pcf8574_read_byte(int fd) {
    int value = i2c_smbus_read_byte_data(fd, PCF8574_ADDR);
    if (value < 0) {
        perror("Error reading from PCF8574");
        return -1;
    }
    return value;
}

// Function to display a byte on the PCF8574
void pcf8574_display_byte(int fd, int value) {
    if (ioctl(fd, I2C_SLAVE, PCF8574_ADDR) < 0) {
        perror("Error setting I2C slave address");
        return;
    }
    if (i2c_smbus_write_byte_data(fd, PCF8574_ADDR, value) < 0) {
        perror("Error writing to PCF8574");
    }
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Initialize the PCF8574
    if (pcf8574_init(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Main loop to display values
    while (1) {
        // Read a byte from the PCF8574
        int value = pcf8574_read_byte(i2c_fd);
        if (value < 0) {
            // Handle the error, perhaps retry or exit
            fprintf(stderr, "Error reading byte, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Display the byte on the PCF8574
        pcf8574_display_byte(i2c_fd, value);

        // Wait for a short period
        usleep(100000); // 100ms
    }

    // The program should never reach here due to the infinite loop,
    // but it's good practice to include cleanup code.
    close(i2c_fd);
    return 0;
}

