#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for PWM output
#define PWM_PIN_1 18
#define PWM_PIN_2 23
#define PWM_PIN_3 24

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define PWM range
#define PWM_RANGE 1000

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the PWM duty cycle for a given GPIO pin
int set_pwm_duty_cycle(int gpio_pin, int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > PWM_RANGE) {
        fprintf(stderr, "Error: Duty cycle value out of range (0-%d).  Setting to 0.\n", PWM_RANGE);
        duty_cycle = 0;
    }
    gpioPWM(gpio_pin, duty_cycle);
    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PWM_PIN_1, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_2, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_3, PWM_RANGE);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Set PWM duty cycles for each GPIO pin
        set_pwm_duty_cycle(PWM_PIN_1, 500);
        set_pwm_duty_cycle(PWM_PIN_2, 750);
        set_pwm_duty_cycle(PWM_PIN_3, 250);

        // Wait for 0.1 seconds
        gpioDelay(100000); // 100000 microseconds = 0.1 seconds
    }

    // Stop PWM output on all GPIO pins
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);

    // Release GPIO pins
    gpioSetMode(PWM_PIN_1, PI_INPUT); // Set to input to avoid floating
    gpioSetMode(PWM_PIN_2, PI_INPUT);
    gpioSetMode(PWM_PIN_3, PI_INPUT);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the HC-SR04 sensors
#define TRIGGER_PIN_1 17
#define ECHO_PIN_1 18
#define TRIGGER_PIN_2 22
#define ECHO_PIN_2 23
#define TRIGGER_PIN_3 24
#define ECHO_PIN_3 25

// Define the speed of sound in cm/s
#define SOUND_SPEED 34300.0

// Define the timeout for the echo pulse in microseconds
#define TIMEOUT 500000 // 0.5 seconds

// Global variables for echo start and end times
volatile uint32_t echo_start_1 = 0;
volatile uint32_t echo_end_1 = 0;
volatile uint32_t echo_start_2 = 0;
volatile uint32_t echo_end_2 = 0;
volatile uint32_t echo_start_3 = 0;
volatile uint32_t echo_end_3 = 0;

// Function prototypes
void trigger_sensor(int trigger_pin);
float get_distance(int echo_pin);
void echo_callback(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

// Function to trigger the HC-SR04 sensor
void trigger_sensor(int trigger_pin) {
    gpioWrite(trigger_pin, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(trigger_pin, 0);
}

// Function to measure the distance using the HC-SR04 sensor
float get_distance(int echo_pin) {
    uint32_t start_tick, end_tick;

    // Wait for the echo pin to go high (with timeout)
    int count = 0;
    while (gpioRead(echo_pin) == 0 && count < TIMEOUT) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }
    if (count >= TIMEOUT) {
        fprintf(stderr, "Error: Echo pin %d did not go high (timeout).\n", echo_pin);
        return -1.0; // Indicate error
    }
    start_tick = gpioTick();

    // Wait for the echo pin to go low (with timeout)
    count = 0;
    while (gpioRead(echo_pin) == 1 && count < TIMEOUT) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }
    if (count >= TIMEOUT) {
        fprintf(stderr, "Error: Echo pin %d did not go low (timeout).\n", echo_pin);
        return -1.0; // Indicate error
    }
    end_tick = gpioTick();

    // Calculate the pulse duration in microseconds
    uint32_t pulse_duration = end_tick - start_tick;

    // Calculate the distance in centimeters
    float distance = (pulse_duration * SOUND_SPEED) / 2000000.0; // Divide by 2 for one-way distance

    return distance;
}

// Callback function for echo pin changes
void echo_callback(int gpio, int level, uint32_t tick, void *user_data) {
    if (gpio == ECHO_PIN_1) {
        if (level == 1) {
            echo_start_1 = tick;
        } else if (level == 0) {
            echo_end_1 = tick;
        }
    } else if (gpio == ECHO_PIN_2) {
        if (level == 1) {
            echo_start_2 = tick;
        } else if (level == 0) {
            echo_end_2 = tick;
        }
    } else if (gpio == ECHO_PIN_3) {
        if (level == 1) {
            echo_start_3 = tick;
        } else if (level == 0) {
            echo_end_3 = tick;
        }
    }
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN_1, PI_OUTPUT);
    gpioSetMode(ECHO_PIN_1, PI_INPUT);
    gpioSetMode(TRIGGER_PIN_2, PI_OUTPUT);
    gpioSetMode(ECHO_PIN_2, PI_INPUT);
    gpioSetMode(TRIGGER_PIN_3, PI_OUTPUT);
    gpioSetMode(ECHO_PIN_3, PI_INPUT);

    // Set pull-up/down resistors (optional, adjust as needed)
    gpioSetPullUpDown(ECHO_PIN_1, PI_PUD_UP);
    gpioSetPullUpDown(ECHO_PIN_2, PI_PUD_UP);
    gpioSetPullUpDown(ECHO_PIN_3, PI_PUD_UP);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Register callback functions for echo pins
    gpioSetAlertFuncEx(ECHO_PIN_1, echo_callback, NULL);
    gpioSetAlertFuncEx(ECHO_PIN_2, echo_callback, NULL);
    gpioSetAlertFuncEx(ECHO_PIN_3, echo_callback, NULL);

    // Main loop
    while (1) {
        // Trigger sensors
        trigger_sensor(TRIGGER_PIN_1);
        trigger_sensor(TRIGGER_PIN_2);
        trigger_sensor(TRIGGER_PIN_3);

        // Wait for a short period to allow the sensors to measure
        gpioDelay(100); // 100ms

        // Get distances
        float distance1 = get_distance(ECHO_PIN_1);
        float distance2 = get_distance(ECHO_PIN_2);
