        if (distance1 < 0 || distance2 < 0 || distance3 < 0) {
            fprintf(stderr, "Error: Invalid distance reading from one or more sensors.\n");
        }

        // Delay before next measurement
        gpioDelay(1000); // 1 second
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness and to avoid compiler warnings.
    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 23
#define GPIO_DIRECTION "out"

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

int main() {
    int ret;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIO_CHIP);
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %d\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set GPIO direction to output
    ret = gpiod_line_request_output(line, GPIO_DIRECTION, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO direction: %d\n", ret);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("GPIO %d set to %s\n", GPIO_PIN, GPIO_DIRECTION);

    // Main loop
    while (!terminate) {
        // Read GPIO value
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO value: %d\n", value);
            break;
        }

        // Print GPIO value
        printf("GPIO %d value: %d\n", GPIO_PIN, value);

        // Set GPIO value to the opposite
        ret = gpiod_line_set_value(line, !value);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO value: %d\n", ret);
            break;
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Release GPIO line
    gpiod_line_release(line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    printf("GPIO %d released and chip closed.\n", GPIO_PIN);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    program_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to initialize the MPU6050
int init_mpu6050() {
    // Wake up the MPU6050 (clear sleep mode bit)
    if (i2c_smbus_write_byte_data(i2c_fd, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read raw accelerometer data
int read_raw_accelerometer(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    if (read(i2c_fd, buf, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Function to convert raw accelerometer data to g-force units
void convert_to_g(int16_t raw_x, int16_t raw_y, int16_t raw_z, float *x, float *y, float *z) {
    // Sensitivity scale factor for +/- 2g range
    const float sensitivity = 16384.0f;

    *x = (float)raw_x / sensitivity;
    *y = (float)raw_y / sensitivity;
    *z = (float)raw_z / sensitivity;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050() < 0) {
        fprintf(stderr, "MPU6050 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    printf("MPU6050 initialized successfully.\n");

    // Main loop
    int16_t raw_x, raw_y, raw_z;
    float x_g, y_g, z_g;

    while (program_running) {
        // Read raw accelerometer data
        if (read_raw_accelerometer(&raw_x, &raw_y, &raw_z) == 0) {
            // Convert to g-force units
            convert_to_g(raw_x, raw_y, raw_z, &x_g, &y_g, &z_g);

            // Print the accelerometer data
            printf("X: %.3f g, Y: %.3f g, Z: %.3f g\n", x_g, y_g, z_g);
        } else {
            fprintf(stderr, "Failed to read accelerometer data. Attempting to re-initialize...\n");
            close(i2c_fd);
            i2c_fd = open("/dev/i2c-1", O_RDWR);
            if (i2c_fd < 0) {
                fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
                program_running = 0; // Exit loop if re-initialization fails
            } else {
                if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
                    fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
                    close(i2c_fd);
                    program_running = 0;
                } else {
                    if (init_mpu6050() < 0) {
                        fprintf(stderr, "MPU6050 re-initialization failed.\n");
                        program_running = 0;
                    }
                }
            }
        }

        // Wait for 0.1 seconds
        usleep(100000); // 100 milliseconds
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
