#include <gpiod.h>

// Define GPIO pins
#define GPIO_PIN_1 2
#define GPIO_PIN_2 3
#define GPIO_PIN_3 17

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the state of a GPIO pin
int set_gpio_state(struct gpiod_chip *chip, int pin, int value) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get GPIO line for pin %d\n", pin);
        return -1;
    }

    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set GPIO line for pin %d to value %d\n", pin, value);
        gpiod_line_release(line);
        return -1;
    }

    gpiod_line_release(line);
    return 0;
}

// Function to read the state of a GPIO pin
int read_gpio_state(struct gpiod_chip *chip, int pin) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get GPIO line for pin %d\n", pin);
        return -1;
    }

    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error: Could not get GPIO line for pin %d value\n", pin);
        gpiod_line_release(line);
        return -1;
    }

    gpiod_line_release(line);
    return value;
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip %s\n", GPIO_CHIP);
        return 1;
    }

    // Request GPIO pins as outputs
    struct gpiod_line *line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    struct gpiod_line *line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    struct gpiod_line *line3 = gpiod_chip_get_line(chip, GPIO_PIN_3);

    if (!line1 || !line2 || !line3) {
        fprintf(stderr, "Error: Could not get GPIO line for pin %d\n", GPIO_PIN_1);
        fprintf(stderr, "Error: Could not get GPIO line for pin %d\n", GPIO_PIN_2);
        fprintf(stderr, "Error: Could not get GPIO line for pin %d\n", GPIO_PIN_3);
        gpiod_chip_close(chip);
        return 1;
    }

    int ret = gpiod_line_request_output(line1, "gpio_control", 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request GPIO line for pin %d as output\n", GPIO_PIN_1);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_line_release(line3);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line2, "gpio_control", 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request GPIO line for pin %d as output\n", GPIO_PIN_2);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_line_release(line3);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line3, "gpio_control", 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request GPIO line for pin %d as output\n", GPIO_PIN_3);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_line_release(line3);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Cycle through states
        for (int i = 0; i < 3; i++) {
            // Set GPIO 1 to HIGH
            if (set_gpio_state(chip, GPIO_PIN_1, 1) != 0) {
                fprintf(stderr, "Error setting GPIO 1 to HIGH\n");
                break;
            }
            printf("GPIO 1 set to HIGH\n");
            sleep(5);

            // Set GPIO 1 to LOW
            if (set_gpio_state(chip, GPIO_PIN_1, 0) != 0) {
                fprintf(stderr, "Error setting GPIO 1 to LOW\n");
                break;
            }
            printf("GPIO 1 set to LOW\n");
            sleep(5);

            // Set GPIO 2 to HIGH
            if (set_gpio_state(chip, GPIO_PIN_2, 1) != 0) {
                fprintf(stderr, "Error setting GPIO 2 to HIGH\n");
                break;
            }
            printf("GPIO 2 set to HIGH\n");
            sleep(5);

            // Set GPIO 2 to LOW
            if (set_gpio_state(chip, GPIO_PIN_2, 0) != 0) {
                fprintf(stderr, "Error setting GPIO 2 to LOW\n");
                break;
            }
            printf("GPIO 2 set to LOW\n");
            sleep(5);

            // Set GPIO 3 to HIGH
            if (set_gpio_state(chip, GPIO_PIN_3, 1) != 0) {
                fprintf(stderr, "Error setting GPIO 3 to HIGH\n");
                break;
            }
            printf("GPIO 3 set to HIGH\n");
            sleep(5);

            // Set GPIO 3 to LOW
            if (set_gpio_state(chip, GPIO_PIN_3, 0) != 0) {
                fprintf(stderr, "Error setting GPIO 3 to LOW\n");
                break;
            }
            printf("GPIO 3 set to LOW\n");
            sleep(5);
        }

        // Read GPIO 1
        int value1 = read_gpio_state(chip, GPIO_PIN_1);
        if (value1 < 0) {
            fprintf(stderr, "Error reading GPIO 1\n");
        } else {
            printf("GPIO 1 read value: %d\n", value1);
        }

        // Read GPIO 2
        int value2 = read_gpio_state(chip, GPIO_PIN_2);
        if (value2 < 0) {
            fprintf(stderr, "Error reading GPIO 2\n");
        } else {
            printf("GPIO 2 read value: %d\n", value2);
        }

        // Read GPIO 3
        int value3 = read_gpio_state(chip, GPIO_PIN_3);
        if (value3 < 0) {
            fprintf(stderr, "Error reading GPIO 3\n");
        } else {
            printf("GPIO 3 read value: %d\n", value3);
        }

        sleep(1); // Small delay to prevent busy-waiting
    }

    // Release GPIO lines and close chip
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_line_release(line3);
    gpiod_chip_close(chip);

    return 0;
}

