// Function to export a GPIO pin
int export_gpio(struct gpiod_chip *chip, int pin) {
    char buffer[3];
    int len;
    int fd;

    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error: Could not open /sys/class/gpio/export for writing\n");
        return -1;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, len) != len) {
        fprintf(stderr, "Error: Could not write to /sys/class/gpio/export\n");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to unexport a GPIO pin
int unexport_gpio(struct gpiod_chip *chip, int pin) {
    char buffer[3];
    int len;
    int fd;

    fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error: Could not open /sys/class/gpio/unexport for writing\n");
        return -1;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, len) != len) {
        fprintf(stderr, "Error: Could not write to /sys/class/gpio/unexport\n");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to set the direction of a GPIO pin (in or out)
int set_gpio_direction(struct gpiod_chip *chip, int pin, const char *direction) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get GPIO line for pin %d\n", pin);
        return -1;
    }

    int ret = gpiod_line_request_output(line, direction, 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request GPIO line for pin %d as output\n", pin);
        gpiod_line_release(line);
        return -1;
    }

    gpiod_line_release(line);
    return 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip %s\n", GPIO_CHIP);
        return 1;
    }

    // Export GPIO pins
    if (export_gpio(chip, GPIO_17) < 0 ||
        export_gpio(chip, GPIO_22) < 0 ||
        export_gpio(chip, GPIO_27) < 0) {
        fprintf(stderr, "Error: Failed to export GPIO pins\n");
        goto cleanup;
    }

    // Set GPIO directions to output
    if (set_gpio_direction(chip, GPIO_17, "out") < 0 ||
        set_gpio_direction(chip, GPIO_22, "out") < 0 ||
        set_gpio_direction(chip, GPIO_27, "out") < 0) {
        fprintf(stderr, "Error: Failed to set GPIO directions\n");
        goto cleanup;
    }

    // Main loop
    while (program_running) {
        // Set GPIO states
        if (set_gpio_state(chip, GPIO_17, 1) < 0 ||
            set_gpio_state(chip, GPIO_22, 0) < 0 ||
            set_gpio_state(chip, GPIO_27, 1) < 0) {
            fprintf(stderr, "Error: Failed to set GPIO states\n");
            break;
        }

        // Print GPIO states to standard output
        printf("GPIO 17: %d, GPIO 22: %d, GPIO 27: %d\n",
               gpiod_line_get_value(gpiod_chip_get_line(chip, GPIO_17)),
               gpiod_line_get_value(gpiod_chip_get_line(chip, GPIO_22)),
               gpiod_line_get_value(gpiod_chip_get_line(chip, GPIO_27)));

        // Wait for 1 second
        sleep(1);

        // Set GPIO states
        if (set_gpio_state(chip, GPIO_17, 0) < 0 ||
            set_gpio_state(chip, GPIO_22, 1) < 0 ||
            set_gpio_state(chip, GPIO_27, 0) < 0) {
            fprintf(stderr, "Error: Failed to set GPIO states\n");
            break;
        }

        // Print GPIO states to standard output
        printf("GPIO 17: %d, GPIO 22: %d, GPIO 27: %d\n",
               gpiod_line_get_value(gpiod_chip_get_line(chip, GPIO_17)),
               gpiod_line_get_value(gpiod_chip_get_line(chip, GPIO_22)),
               gpiod_line_get_value(gpiod_chip_get_line(chip, GPIO_27)));

        // Wait for 1 second
        sleep(1);
    }

cleanup:
    // Unexport GPIO pins
    unexport_gpio(chip, GPIO_17);
    unexport_gpio(chip, GPIO_22);
    unexport_gpio(chip, GPIO_27);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

