// SHT31 I2C address
#define SHT31_ADDR 0x44

// Measurement command (High repeatability, clock stretching disabled)
#define MEASURE_CMD 0x2C06

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read data from SHT31
int read_sht31(int fd, float *temperature, float *humidity) {
    uint8_t cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    uint8_t data[6];
    int result;

    // Send measurement command
    result = write(fd, cmd, 2);
    if (result != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Wait for measurement (at least 10 ms)
    usleep(10000);

    // Read 6 bytes of data
    result = read(fd, data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Convert data to temperature and humidity
    int temperature_raw = (data[0] << 8) | data[1];
    int humidity_raw = (data[3] << 8) | data[4];

    *temperature = -45.0 + (175.0 * (float)temperature_raw / 65535.0);
    *humidity = 100.0 * (float)humidity_raw / 65535.0;

    // Basic data validation
    if (*temperature < -40.0 || *temperature > 125.0 || *humidity < 0.0 || *humidity > 100.0) {
        fprintf(stderr, "Invalid sensor data: Temperature=%.2f, Humidity=%.2f\n", *temperature, *humidity);
        return -1;
    }

    return 0;
}

int main() {
    float temperature, humidity;
    int result;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SHT31_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        result = read_sht31(i2c_fd, &temperature, &humidity);
        if (result == 0) {
            printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        sleep(5);
    }

    // The following lines will never be reached due to the infinite loop.
    close(i2c_fd);
    return 0;
}

