#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the LED strip
#define LED_PIN_1 18
#define LED_PIN_2 23
#define LED_PIN_3 24

// Define the number of LEDs in the strip
#define NUM_LEDS 10

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the colour of a single LED
void set_led_colour(int gpio_pin, int red, int green, int blue) {
    gpioPWM(gpio_pin, red);
    gpioPWM(gpio_pin + 1, green);
    gpioPWM(gpio_pin + 2, blue);
}

// Function to set the colour of all LEDs in the strip
void set_strip_colour(int red, int green, int blue) {
    for (int i = 0; i < NUM_LEDS; i++) {
        set_led_colour(LED_PIN_1 + i * 3, red, green, blue);
    }
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(LED_PIN_1, PI_OUTPUT);
    gpioSetMode(LED_PIN_2, PI_OUTPUT);
    gpioSetMode(LED_PIN_3, PI_OUTPUT);

    // Set PWM range for each LED (0-255)
    gpioSetPWMrange(LED_PIN_1, 255);
    gpioSetPWMrange(LED_PIN_2, 255);
    gpioSetPWMrange(LED_PIN_3, 255);

    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Cycle through the colours
        for (int i = 0; i < 3; i++) {
            // Red
            set_strip_colour(255, 0, 0);
            gpioDelay(500000); // 0.5 seconds

            // Green
            set_strip_colour(0, 255, 0);
            gpioDelay(500000);

            // Blue
            set_strip_colour(0, 0, 255);
            gpioDelay(500000);
        }
    }

    // Release GPIO resources before exiting
    gpioTerminate();

    return 0;
}

