#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define GPIO_PIN_1 8
#define GPIO_PIN_2 17

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Global variables for GPIO lines
struct gpiod_line *gpio_line_1 = NULL;
struct gpiod_line *gpio_line_2 = NULL;

// Function prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_set_value(int pin, int value);
int gpio_get_value(int pin);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Unexport GPIO pins
    if (gpio_line_1) {
        gpiod_line_release(gpio_line_1);
    }
    if (gpio_line_2) {
        gpiod_line_release(gpio_line_2);
    }

    // Close GPIO chip
    gpiod_chip_close(gpio_line_1 ? gpio_line_1->chip : gpio_line_2->chip);

    exit(0);
}

// Function to export a GPIO pin
int gpio_export(int pin) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s\n", GPIO_CHIP);
        return -1;
    }

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d\n", pin);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request(line, "gpio_export", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %d\n", pin, ret);
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

// Function to unexport a GPIO pin
int gpio_unexport(int pin) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s\n", GPIO_CHIP);
        return -1;
    }

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d\n", pin);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_release(line);
    if (ret < 0) {
        fprintf(stderr, "Error releasing GPIO line %d: %d\n", pin, ret);
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

// Function to set the direction of a GPIO pin (in or out)
int gpio_set_direction(int pin, const char *direction) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s\n", GPIO_CHIP);
        return -1;
    }

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d\n", pin);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_set_direction(line, direction);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line %d direction to %s: %d\n", pin, direction, ret);
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

// Function to set the value of a GPIO pin (0 or 1)
int gpio_set_value(int pin, int value) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s\n", GPIO_CHIP);
        return -1;
    }

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d\n", pin);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line %d value to %d: %d\n", pin, value, ret);
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

// Function to get the value of a GPIO pin
int gpio_get_value(int pin) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int value;
    int ret;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s\n", GPIO_CHIP);
        return -1;
    }

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d\n", pin);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_get_value(line);
    if (ret < 0) {
        fprintf(stderr, "Error getting GPIO line %d value: %d\n", pin, ret);
        gpiod_chip_close(chip);
        return -1;
    }

    value = ret;
    gpiod_chip_close(chip);
    return value;
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Export GPIO pins
    if (gpio_export(GPIO_PIN_1) < 0 || gpio_export(GPIO_PIN_2) < 0) {
        fprintf(stderr, "Failed to export GPIO pins. Exiting.\n");
        return 1;
    }

    // Set GPIO direction to output
    if (gpio_set_direction(GPIO_PIN_1, "out") < 0 || gpio_set_direction(GPIO_PIN_2, "out") < 0) {
        fprintf(stderr, "Failed to set GPIO direction. Exiting.\n");
        gpio_unexport(GPIO_PIN_1);
        gpio_unexport(GPIO_PIN_2);
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO 1 to HIGH
        if (gpio_set_value(GPIO_PIN_1, 1) < 0) {
            fprintf(stderr, "Failed to set GPIO 1 value. Continuing.\n");
        }

        // Get GPIO 1 value
        int value_1 = gpio_get_value(GPIO_PIN_1);
        if (value_1 < 0) {
            fprintf(stderr, "Failed to get GPIO 1 value. Continuing.\n");
        } else {
            printf("GPIO 1: %d\n", value_1);
        }

        // Set GPIO 2 to LOW
        if (gpio_set_value(GPIO_PIN_2, 0) < 0) {
            fprintf(stderr, "Failed to set GPIO 2 value. Continuing.\n");
        }

        // Get GPIO 2 value
        int value_2 = gpio_get_value(GPIO_PIN_2);
        if (value_2 < 0) {
            fprintf(stderr, "Failed to get GPIO 2 value. Continuing.\n");
        } else {
            printf("GPIO 2: %d\n", value_2);
        }

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

