}

// Function to set the GPIO direction (in or out)
int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (write(fd, direction, strlen(direction)) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Function to write a value to the GPIO pin
int gpio_write(int pin, int value) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (value != 0 && value != 1) {
        fprintf(stderr, "Invalid GPIO value: %d\n", value);
        close(fd);
        return -1;
    }
    char val_str[2];
    snprintf(val_str, sizeof(val_str), "%d", value);
    if (write(fd, val_str, 1) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Function to read a value from the GPIO pin
int gpio_read(int pin) {
    char path[64];
    int fd;
    char value_str[3];

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fd = open(path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (read(fd, value_str, 3) < 0) {
        fprintf(stderr, "Error reading from %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return atoi(value_str);
}

// Function to read the w1_slave file for a given device ID
int read_w1_slave(const char *device_id, char *data, int max_length) {
    int fd;
    ssize_t bytes_read;

    snprintf(data, max_length, "/sys/bus/w1/devices/%s/w1_slave", device_id);
    fd = open(data, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", data, strerror(errno));
        return -1;
    }

    bytes_read = read(fd, data, max_length - 1);
    if (bytes_read < 0) {
        fprintf(stderr, "Error reading from %s: %s\n", data, strerror(errno));
        close(fd);
        return -1;
    }
    data[bytes_read] = '\0'; // Null-terminate the string

    close(fd);
    return 0;
}

