float convert_to_celsius(const char *data) {
    unsigned long raw_temperature;
    float temperature;

    if (sscanf(data, "YES\n\tTemperature=%lu\n", &raw_temperature) != 1) {
        fprintf(stderr, "Error parsing temperature data\n");
        return -1000.0; // Indicate an error
    }

    temperature = (float)raw_temperature / 1000.0;
    return temperature;
}

