#define PWM_PIN_3 18

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define PWM range
#define PWM_RANGE 1000

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins for PWM output
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);

    gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQUENCY);

    gpioSetPWMrange(PWM_PIN_1, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_2, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_3, PWM_RANGE);

    return 0;
}

// Function to generate PWM signal on a given GPIO pin
void generate_pwm(int gpio_pin, int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > PWM_RANGE) {
        fprintf(stderr, "Invalid duty cycle: %d\n", duty_cycle);
        return;
    }

    gpioPWM(gpio_pin, duty_cycle);
}

// Function to release GPIO pins and terminate pigpio
void cleanup_gpio() {
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioTerminate();
}

