        // Generate PWM signals with varying duty cycles
        generate_pwm(PWM_PIN_1, 500);
        generate_pwm(PWM_PIN_2, 750);
        generate_pwm(PWM_PIN_3, 250);

        // Wait for 0.1 seconds
        gpioDelay(100000); // 100000 microseconds = 0.1 seconds
    }

    // Cleanup GPIO pins before exiting
    cleanup_gpio();

    return 0;
}

