// Define GPIO pins
#define GPIO_17 17
#define GPIO_22 22
#define GPIO_23 23
#define GPIO_24 24

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to export a GPIO pin
int export_gpio(int gpio) {
    char buffer[64];
    int len;
    int fd;

    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening /sys/class/gpio/export: %m\n", errno);
        return -1;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", gpio);
    if (write(fd, buffer, len) != len) {
        fprintf(stderr, "Error writing to /sys/class/gpio/export: %m\n", errno);
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to unexport a GPIO pin
int unexport_gpio(int gpio) {
    char buffer[64];
    int len;
    int fd;

    fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening /sys/class/gpio/unexport: %m\n", errno);
        return -1;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", gpio);
    if (write(fd, buffer, len) != len) {
        fprintf(stderr, "Error writing to /sys/class/gpio/unexport: %m\n", errno);
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to set the direction of a GPIO pin (in or out)
int set_gpio_direction(int gpio, const char *direction) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", gpio);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %m\n", path, errno);
        return -1;
    }

    if (write(fd, direction, strlen(direction)) != strlen(direction)) {
        fprintf(stderr, "Error writing to %s: %m\n", path, errno);
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to write a value to a GPIO pin (0 or 1)
int write_gpio_value(int gpio, int value) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", gpio);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %m\n", path, errno);
        return -1;
    }

    if (value != 0 && value != 1) {
        fprintf(stderr, "Invalid GPIO value: %d\n", value);
        close(fd);
        return -1;
    }

    char val_str[2];
    snprintf(val_str, sizeof(val_str), "%d", value);

    if (write(fd, val_str, 1) != 1) {
        fprintf(stderr, "Error writing to %s: %m\n", path, errno);
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to read the value of a GPIO pin
int read_gpio_value(int gpio) {
    char path[64];
    int fd;
    char value_str[3];

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", gpio);
    fd = open(path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %m\n", path, errno);
        return -1;
    }

    if (read(fd, value_str, 3) < 0) {
        fprintf(stderr, "Error reading from %s: %m\n", path, errno);
        close(fd);
        return -1;
    }

    close(fd);
    return atoi(value_str);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %m\n", GPIO_CHIP, errno);
        return 1;
    }

    // Export GPIO pins
    if (export_gpio(GPIO_17) < 0 ||
        export_gpio(GPIO_22) < 0 ||
        export_gpio(GPIO_23) < 0 ||
        export_gpio(GPIO_24) < 0) {
        fprintf(stderr, "Error exporting GPIO pins. Exiting.\n");
        goto cleanup;
    }

    // Set GPIO directions to output
    if (set_gpio_direction(GPIO_17, "out") < 0 ||
        set_gpio_direction(GPIO_22, "out") < 0 ||
        set_gpio_direction(GPIO_23, "out") < 0 ||
        set_gpio_direction(GPIO_24, "out") < 0) {
        fprintf(stderr, "Error setting GPIO directions. Exiting.\n");
        goto cleanup;
    }

    // Main loop
    while (program_running) {
        // Read GPIO values
        int value_17 = read_gpio_value(GPIO_17);
        int value_22 = read_gpio_value(GPIO_22);
        int value_23 = read_gpio_value(GPIO_23);
        int value_24 = read_gpio_value(GPIO_24);

        // Check for errors during GPIO read
        if (value_17 < 0 || value_22 < 0 || value_23 < 0 || value_24 < 0) {
            fprintf(stderr, "Error reading GPIO values. Retrying.\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Print GPIO values to standard output
        printf("GPIO 17: %d, GPIO 22: %d, GPIO 23: %d, GPIO 24: %d\n", value_17, value_22, value_23, value_24);

        // Wait for 10 seconds
        sleep(10);
    }

cleanup:
    // Unexport GPIO pins
    unexport_gpio(GPIO_17);
    unexport_gpio(GPIO_22);
    unexport_gpio(GPIO_23);
    unexport_gpio(GPIO_24);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

