int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip %s\n", GPIO_CHIP);
        return 1;
    }

    // Get GPIO lines
    struct gpiod_line *line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    struct gpiod_line *line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    struct gpiod_line *line3 = gpiod_chip_get_line(chip, GPIO_PIN_3);

    if (!line1 || !line2 || !line3) {
        fprintf(stderr, "Error: Could not get GPIO line for one or more pins\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines as output
    if (gpiod_line_request_output(line1, "gpio_control", 0) < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d as output\n", GPIO_PIN_1);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_line_release(line3);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(line2, "gpio_control", 0) < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d as output\n", GPIO_PIN_2);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_line_release(line3);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(line3, "gpio_control", 0) < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d as output\n", GPIO_PIN_3);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_line_release(line3);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Set GPIO states
        if (set_gpio_state(chip, GPIO_PIN_1, 1) < 0) {
            fprintf(stderr, "Error setting GPIO %d to HIGH\n", GPIO_PIN_1);
            program_running = 0; // Exit loop on error
        }
        if (set_gpio_state(chip, GPIO_PIN_2, 0) < 0) {
            fprintf(stderr, "Error setting GPIO %d to LOW\n", GPIO_PIN_2);
            program_running = 0; // Exit loop on error
        }
        if (set_gpio_state(chip, GPIO_PIN_3, 1) < 0) {
            fprintf(stderr, "Error setting GPIO %d to HIGH\n", GPIO_PIN_3);
            program_running = 0; // Exit loop on error
        }

        // Read GPIO states
        int state1 = read_gpio_state(chip, GPIO_PIN_1);
        int state2 = read_gpio_state(chip, GPIO_PIN_2);
        int state3 = read_gpio_state(chip, GPIO_PIN_3);

        if (state1 < 0 || state2 < 0 || state3 < 0) {
            fprintf(stderr, "Error reading GPIO states\n");
            program_running = 0; // Exit loop on error
        }

        // Print GPIO states
        printf("GPIO %d: %d, GPIO %d: %d, GPIO %d: %d\n", GPIO_PIN_1, state1, GPIO_PIN_2, state2, GPIO_PIN_3, state3);

        // Wait for 0.05 seconds
        usleep(500000); // 500000 microseconds = 0.05 seconds
    }

    // Release GPIO lines
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_line_release(line3);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
