// Define GPIO pins for PWM output
#define PWM_PIN_1 17
#define PWM_PIN_2 27

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Define PWM range (0-255)
#define PWM_RANGE 255

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the PWM duty cycle on a given GPIO pin
void set_pwm_duty_cycle(int gpio_pin, int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    gpioPWM(gpio_pin, duty_cycle);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PWM_PIN_1, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_2, PWM_RANGE);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Set PWM duty cycles for GPIO 17 and GPIO 27
        set_pwm_duty_cycle(PWM_PIN_1, 128); // 50% duty cycle
        set_pwm_duty_cycle(PWM_PIN_2, 128); // 50% duty cycle

        // Print PWM duty cycles to standard output
        printf("PWM Duty Cycle on GPIO %d: %d\n", PWM_PIN_1, 128);
        printf("PWM Duty Cycle on GPIO %d: %d\n", PWM_PIN_2, 128);

        // Wait for 1 second
        sleep(1);

        // Set PWM duty cycles for GPIO 17 and GPIO 27 to 0
        set_pwm_duty_cycle(PWM_PIN_1, 0);
        set_pwm_duty_cycle(PWM_PIN_2, 0);

        // Print PWM duty cycles to standard output
        printf("PWM Duty Cycle on GPIO %d: %d\n", PWM_PIN_1, 0);
        printf("PWM Duty Cycle on GPIO %d: %d\n", PWM_PIN_2, 0);

        // Wait for 1 second
        sleep(1);
    }

    // Release GPIO pins
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

// Define GPIO pins
#define GPIO_PIN_1 4
#define GPIO_PIN_2 17
#define GPIO_PIN_3 22
#define GPIO_PIN_4 23
#define GPIO_PIN_5 24
#define GPIO_PIN_6 25
#define GPIO_PIN_7 27

// Define the number of cycles to run
#define CYCLE_COUNT 100

// Global variable to track if the program should exit
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to set the state of a GPIO pin
int set_gpio_state(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d state: %s\n", line->number, strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to read the state of a GPIO pin
int read_gpio_state(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d state: %s\n", line->number, strerror(-value));
        return -1;
    }
    return value;
}

int main() {
    // Register the signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    // Open the GPIO chip
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Get the lines for each GPIO pin
    struct gpiod_line *lines[8];
    lines[0] = gpiod_chip_get_line(chip, GPIO_PIN_1);
    lines[1] = gpiod_chip_get_line(chip, GPIO_PIN_2);
    lines[2] = gpiod_chip_get_line(chip, GPIO_PIN_3);
    lines[3] = gpiod_chip_get_line(chip, GPIO_PIN_4);
    lines[4] = gpiod_chip_get_line(chip, GPIO_PIN_5);
    lines[5] = gpiod_chip_get_line(chip, GPIO_PIN_6);
    lines[6] = gpiod_chip_get_line(chip, GPIO_PIN_7);
    lines[7] = NULL; // Terminate the array

    // Check if all lines were successfully retrieved
    if (!lines[0] || !lines[1] || !lines[2] || !lines[3] || !lines[4] || !lines[5] || !lines[6]) {
        fprintf(stderr, "Error getting GPIO lines\n");
        goto cleanup;
    }

    // Request the lines as outputs
    for (int i = 0; lines[i]; i++) {
        int ret = gpiod_line_request_output(lines[i], "gpio_control", 0);
        if (ret < 0) {
            fprintf(stderr, "Error requesting GPIO %d as output: %s\n", lines[i]->number, strerror(-ret));
            goto cleanup;
        }
    }

    // Main loop to control the GPIO pins
    for (int i = 0; i < CYCLE_COUNT && program_running; i++) {
        // Set GPIO 4 to HIGH
        if (set_gpio_state(lines[0], 1) != 0) {
            goto cleanup;
        }
        printf("GPIO %d set to HIGH\n", GPIO_PIN_1);

        // Set GPIO 17 to LOW
        if (set_gpio_state(lines[1], 0) != 0) {
            goto cleanup;
        }
        printf("GPIO %d set to LOW\n", GPIO_PIN_2);

        // Set GPIO 22 to HIGH
        if (set_gpio_state(lines[2], 1) != 0) {
            goto cleanup;
        }
        printf("GPIO %d set to HIGH\n", GPIO_PIN_3);

        // Set GPIO 23 to LOW
        if (set_gpio_state(lines[3], 0) != 0) {
            goto cleanup;
        }
        printf("GPIO %d set to LOW\n", GPIO_PIN_4);

        // Set GPIO 24 to HIGH
        if (set_gpio_state(lines[4], 1) != 0) {
            goto cleanup;
        }
        printf("GPIO %d set to HIGH\n", GPIO_PIN_5);

        // Set GPIO 25 to LOW
        if (set_gpio_state(lines[5], 0) != 0) {
            goto cleanup;
        }
        printf("GPIO %d set to LOW\n", GPIO_PIN_6);

        // Set GPIO 27 to HIGH
        if (set_gpio_state(lines[6], 1) != 0) {
            goto cleanup;
        }
        printf("GPIO %d set to HIGH\n", GPIO_PIN_7);

        // Wait for 0.5 seconds
        sleep(0.5);
    }

    // Cleanup and exit
cleanup:
    // Release the lines
    for (int i = 0; lines[i]; i++) {
        gpiod_line_release(lines[i]);
    }

    // Close the GPIO chip
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

