int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %m\n");
        return 1;
    }

    // Get GPIO lines for each pin
    struct gpiod_line *line_17 = gpiod_chip_get_line(chip, GPIO_17);
    struct gpiod_line *line_18 = gpiod_chip_get_line(chip, GPIO_18);
    struct gpiod_line *line_23 = gpiod_chip_get_line(chip, GPIO_23);

    if (!line_17 || !line_18 || !line_23) {
        fprintf(stderr, "Error getting GPIO line: %m\n");
        goto cleanup;
    }

    // Request GPIO lines as output
    int ret = gpiod_line_request_output(line_17, "gpio_control", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %d\n", ret);
        goto cleanup;
    }

    ret = gpiod_line_request_output(line_18, "gpio_control", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %d\n", ret);
        goto cleanup;
    }

    ret = gpiod_line_request_output(line_23, "gpio_control", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %d\n", ret);
        goto cleanup;
    }

    // Main loop
    while (program_running) {
        // Set GPIO states
        if (set_gpio_state(line_17, 1) < 0) goto cleanup;
        if (set_gpio_state(line_18, 0) < 0) goto cleanup;
        if (set_gpio_state(line_23, 1) < 0) goto cleanup;

        // Read GPIO states
        int state_17 = read_gpio_state(line_17);
        int state_18 = read_gpio_state(line_18);
        int state_23 = read_gpio_state(line_23);

        if (state_17 < 0 || state_18 < 0 || state_23 < 0) goto cleanup;

        // Print GPIO states
        printf("GPIO 17: %d, GPIO 18: %d, GPIO 23: %d\n", state_17, state_18, state_23);

        // Wait for 0.1 seconds
        usleep(100000); // 100 milliseconds
    }

cleanup:
