void set_pwm_duty_cycle(int gpio_pin, int duty_cycle) {
    gpioPWM(gpio_pin, duty_cycle);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);
    gpioSetMode(PWM_PIN_4, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_4, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PWM_PIN_1, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_2, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_3, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_4, PWM_RANGE);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Apply PWM duty cycles to GPIO pins
        set_pwm_duty_cycle(PWM_PIN_1, 128);
        set_pwm_duty_cycle(PWM_PIN_2, 192);
        set_pwm_duty_cycle(PWM_PIN_3, 224);
        set_pwm_duty_cycle(PWM_PIN_4, 255);

        printf("PWM duty cycles applied to GPIO pins %d, %d, %d, %d\n", PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4);

        // Wait for 60 seconds
        sleep(60);

        // Stop PWM output by setting duty cycle to 0
        set_pwm_duty_cycle(PWM_PIN_1, 0);
        set_pwm_duty_cycle(PWM_PIN_2, 0);
        set_pwm_duty_cycle(PWM_PIN_3, 0);
        set_pwm_duty_cycle(PWM_PIN_4, 0);

        printf("PWM duty cycles stopped on GPIO pins %d, %d, %d, %d\n", PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4);
    }

    // Release GPIO pins
    gpioTerminate();

    return 0;
}

