    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Set PWM duty cycles (0-255)
        set_pwm_duty_cycle(PWM_PIN_1, 0);
        set_pwm_duty_cycle(PWM_PIN_2, 128);
        set_pwm_duty_cycle(PWM_PIN_3, 255);
        set_pwm_duty_cycle(PWM_PIN_4, 128);
