    // Main loop
    while (program_running) {
        float temperature1, humidity1, temperature2, humidity2;
        int result1, result2;

        // Read data from sensor 1
        result1 = read_dht22(DHT22_PIN_1, &temperature1, &humidity1);
        if (result1 == 0) {
