#include <linux/spi/spidev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

// Define SPI device and mode
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0

// Define MAX31855 register addresses
#define MAX31855_CONFIG_REG 0x00
#define MAX31855_RTD_MSB_REG 0x01
#define MAX31855_RTD_LSB_REG 0x02
#define MAX31855_FAULT_REG 0x03

// Define RTD reference resistor value (in ohms)
#define RTD_REFERENCE 430.0

// Define fault codes
#define MAX31855_FAULT_OPEN_CIRCUIT 0x01
#define MAX31855_FAULT_SHORT_TO_GND 0x02
#define MAX31855_FAULT_SHORT_TO_VCC 0x04
#define MAX31855_FAULT_OPEN_RTD 0x08

// Global variables
int spi_fd;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int spi_init(void);
int read_max31855(int *rtd_raw, int *fault_status);
float convert_rtd_to_temperature(int rtd_raw);
void signal_handler(int signal);
void cleanup(void);

// Structure to hold configuration data
typedef struct {
    int spi_fd;
    int spi_mode;
} config_t;

// SPI initialization function
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure SPI bits per word
    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting SPI bits per word");
        close(spi_fd);
        return -1;
    }

    // Configure SPI max speed
    uint32_t speed = 1000000; // 1 MHz
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI max speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Function to read data from MAX31855
int read_max31855(int *rtd_raw, int *fault_status) {
    uint8_t tx_buf[4] = {0}; // Transmit buffer (dummy data)
    uint8_t rx_buf[4]; // Receive buffer

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 4,
        .speed_hz = 1000000, // 1 MHz
        .bits_per_word = 8,
    };

    // Read configuration register
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        perror("Error reading configuration register");
        return -1;
    }

    // Read RTD MSB register
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        perror("Error reading RTD MSB register");
        return -1;
    }

    // Read RTD LSB register
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        perror("Error reading RTD LSB register");
        return -1;
    }

    // Read fault register
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        perror("Error reading fault register");
        return -1;
    }

    // Extract RTD raw value
    *rtd_raw = ((rx_buf[0] << 8) | rx_buf[1]) >> 2; // Shift right by 2 bits

    // Extract fault status
    *fault_status = rx_buf[3];

    return 0;
}

// Function to convert RTD raw value to temperature (Celsius)
float convert_rtd_to_temperature(int rtd_raw) {
    float rtd_resistance = (float)rtd_raw * RTD_REFERENCE / 32768.0; // Calculate RTD resistance
    float temperature = rtd_resistance / 430.0; // Calculate temperature in Celsius
    return temperature;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup(void) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
}

int main(void) {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize SPI
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    int rtd_raw, fault_status;
    float temperature;

    // Main loop
    while (program_running) {
        // Read data from MAX31855
        if (read_max31855(&rtd_raw, &fault_status) == 0) {
            // Check for fault conditions
            if (fault_status != 0) {
                fprintf(stderr, "Fault detected: 0x%02X\n", fault_status);
            } else {
                // Convert RTD raw value to temperature
                temperature = convert_rtd_to_temperature(rtd_raw);

                // Print temperature to standard output
                printf("Temperature: %.2f °C\n", temperature);
            }
        } else {
            fprintf(stderr, "Error reading MAX31855 data.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

