#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the HC-SR04 sensors
#define TRIGGER_PIN_1 4
#define ECHO_PIN_1 17
#define TRIGGER_PIN_2 18
#define ECHO_PIN_2 27

// Define the speed of sound in cm/s
#define SOUND_SPEED 34300.0

// Define the timeout for the echo pulse in microseconds
#define TIMEOUT 500000 // 0.5 seconds

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to trigger the HC-SR04 sensor
void triggerSensor(int triggerPin) {
    gpioWrite(triggerPin, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(triggerPin, 0);
}

// Function to measure the echo pulse duration
long pulseIn(int echoPin, int level, int timeout) {
    long startTime = 0, endTime = 0;

    // Wait for the echo pin to go high (with timeout)
    int count = 0;
    while (gpioRead(echoPin) != level && count < timeout) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= timeout) {
        return -1; // Timeout occurred
    }

    startTime = gpioTick();

    // Wait for the echo pin to go low (with timeout)
    count = 0;
    while (gpioRead(echoPin) == level && count < timeout) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= timeout) {
        return -1; // Timeout occurred
    }

    endTime = gpioTick();

    return endTime - startTime;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulseDuration) {
    if (pulseDuration < 0) {
        return -1.0; // Indicate error
    }
    return (pulseDuration * SOUND_SPEED) / 2000000.0; // Divide by 2 for one-way distance
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN_1, PI_OUTPUT);
    gpioSetMode(ECHO_PIN_1, PI_INPUT);
    gpioSetMode(TRIGGER_PIN_2, PI_OUTPUT);
    gpioSetMode(ECHO_PIN_2, PI_INPUT);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("HC-SR04 sensor interface started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Trigger sensor 1
        triggerSensor(TRIGGER_PIN_1);
        long pulseDuration1 = pulseIn(ECHO_PIN_1, 1, TIMEOUT);
        float distance1 = calculateDistance(pulseDuration1);

        // Trigger sensor 2
        triggerSensor(TRIGGER_PIN_2);
        long pulseDuration2 = pulseIn(ECHO_PIN_2, 1, TIMEOUT);
        float distance2 = calculateDistance(pulseDuration2);

        // Print the distances to standard output
        printf("Sensor 1: %.2f cm, Sensor 2: %.2f cm\n", distance1, distance2);

        // Delay for 100 milliseconds
        gpioDelay(100);
    }

    // Release GPIO resources before exiting
    gpioTerminate();

    return 0;
}

