    calib->dig_P1 = (uint16_t)data[6] | ((uint16_t)data[7] << 8);
    calib->dig_P2 = (int16_t)data[8] | ((int16_t)data[9] << 8);
    calib->dig_P3 = (int16_t)data[10] | ((int16_t)data[11] << 8);
    calib->dig_P4 = (int16_t)data[12] | ((int16_t)data[13] << 8);
    calib->dig_P5 = (int16_t)data[14] | ((int16_t)data[15] << 8);
    calib->dig_P6 = (int16_t)data[16] | ((int16_t)data[17] << 8);
    calib->dig_P7 = (int16_t)data[18] | ((int16_t)data[19] << 8);
    calib->dig_P8 = (int16_t)data[20] | ((int16_t)data[21] << 8);
    calib->dig_P9 = (int16_t)data[22] | ((int16_t)data[23] << 8);

    return 0;
}

// Read raw temperature and pressure data from the BMP280
int read_raw_data(int fd, int32_t *temperature, int32_t *pressure) {
    uint8_t data[6];
    if (read(fd, data, 6) != 6) {
        perror("Error reading raw data");
        return -1;
    }

    *pressure = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | ((int32_t)data[2] >> 4);
    *temperature = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | ((int32_t)data[5] >> 4);

    return 0;
}

// Compensate temperature using calibration data
double compensate_temperature(int32_t raw_temperature, struct bmp280_calib_data calib) {
    double var1, var2, T;
    var1 = (((double)raw_temperature) / 16384.0 - ((double)calib.dig_T1) / 1024.0) * ((double)calib.dig_T2);
    var2 = ((((double)raw_temperature) / 131072.0 - ((double)calib.dig_T1) / 8192.0) * (((double)raw_temperature) / 131072.0 - ((double)calib.dig_T1) / 8192.0)) * ((double)calib.dig_T3);
    double t_fine = (var1 + var2);
    T = (t_fine / 5120.0);
    return T;
}

// Compensate pressure using calibration data and temperature
double compensate_pressure(int32_t raw_pressure, int32_t raw_temperature, struct bmp280_calib_data calib) {
    double var1, var2, p;
    double t_fine = ((double)raw_temperature) / 16384.0 - ((double)calib.dig_T1) / 1024.0;
    var1 = ((double)t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * ((double)calib.dig_P6) / 32768.0;
    var2 = var2 + var1 * ((double)calib.dig_P5) * 2.0;
    var2 = (var2 / 4.0) + (((double)calib.dig_P4) * 65536.0);
    var1 = (((double)calib.dig_P3) * var1 * var1 / 524288.0 + ((double)calib.dig_P2) * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * ((double)calib.dig_P1);

    if (var1 == 0)
    {
        return 0;
    }

    p = 1048576.0 - (double)raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = ((double)calib.dig_P9) * p * p / 2147483648.0;
    var2 = p * ((double)calib.dig_P8) / 32768.0;
    p = p + (var1 + var2 + ((double)calib.dig_P7)) / 16.0;

    return p;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c(BMP280_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(i2c_fd, &calib) < 0) {
        fprintf(stderr, "Failed to read calibration data. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Set sensor control register (oversampling x1, normal mode)
    uint8_t ctrl_meas = (3 << 5) | (3 << 2) | 3; // Temperature x1, Pressure x1, Normal mode
    if (write(i2c_fd, &ctrl_meas, 1) != 1) {
        perror("Error writing to control register");
        close(i2c_fd);
        return 1;
    }

    // Set config register (t_sb = 0.5ms, filter off)
    uint8_t config = (0 << 5) | (0 << 2); // t_sb = 0.5ms, filter off
    if (write(i2c_fd, &config, 1) != 1) {
        perror("Error writing to config register");
        close(i2c_fd);
        return 1;
    }

    int32_t raw_temperature, raw_pressure;
    double temperature, pressure;

    // Read and print 3 readings
    for (int i = 0; i < 3 && program_running; ++i) {
        // Read raw data
        if (read_raw_data(i2c_fd, &raw_temperature, &raw_pressure) < 0) {
            fprintf(stderr, "Failed to read raw data. Retrying...\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        // Compensate temperature and pressure
        temperature = compensate_temperature(raw_temperature, calib);
        pressure = compensate_pressure(raw_pressure, raw_temperature, calib);

        // Print the results
        printf("Temperature: %.2f °C, Pressure: %.2f hPa\n", temperature, pressure / 100.0); // Convert Pa to hPa
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define GPIO_17 17
#define GPIO_22 22
#define GPIO_23 23
#define GPIO_24 24

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to set the state of a GPIO pin
int set_gpio_state(struct gpiod_chip *chip, int pin, int value) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get GPIO line for pin %d\n", pin);
        return -1;
    }

    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set GPIO line for pin %d to value %d\n", pin, value);
        gpiod_line_release(line);
        return -1;
    }

    gpiod_line_release(line);
    return 0;
}

// Function to export a GPIO pin
int export_gpio(struct gpiod_chip *chip, int pin) {
    char buffer[3];
    int len;
    int ret;

    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    ret = gpiod_chip_export(chip, len);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not export GPIO %d\n", pin);
        return -1;
    }

    return 0;
}

// Function to unexport a GPIO pin
int unexport_gpio(struct gpiod_chip *chip, int pin) {
    char buffer[3];
    int len;
    int ret;

    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    ret = gpiod_chip_unexport(chip, len);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not unexport GPIO %d\n", pin);
        return -1;
    }

    return 0;
}

// Function to set the direction of a GPIO pin
int set_gpio_direction(struct gpiod_chip *chip, int pin, const char *direction) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get GPIO line for pin %d\n", pin);
        return -1;
    }

    int ret = gpiod_line_request_output(line, direction, 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request GPIO line for pin %d as output\n", pin);
        gpiod_line_release(line);
        return -1;
    }

    gpiod_line_release(line);
    return 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip %s\n", GPIO_CHIP);
        return 1;
    }

    // Export GPIO pins
    if (export_gpio(chip, GPIO_17) < 0 ||
        export_gpio(chip, GPIO_22) < 0 ||
        export_gpio(chip, GPIO_23) < 0 ||
        export_gpio(chip, GPIO_24) < 0) {
        goto cleanup;
    }

    // Set GPIO directions to output
    if (set_gpio_direction(chip, GPIO_17, "out") < 0 ||
        set_gpio_direction(chip, GPIO_22, "out") < 0 ||
        set_gpio_direction(chip, GPIO_23, "out") < 0 ||
        set_gpio_direction(chip, GPIO_24, "out") < 0) {
        goto cleanup;
    }

    // Main loop
    while (program_running) {
        // Set GPIO states
        if (set_gpio_state(chip, GPIO_17, 1) < 0 ||
            set_gpio_state(chip, GPIO_22, 0) < 0 ||
            set_gpio_state(chip, GPIO_23, 1) < 0 ||
            set_gpio_state(chip, GPIO_24, 0) < 0) {
            goto cleanup;
        }

        // Print GPIO states to standard output
        printf("GPIO 17: %d, GPIO 22: %d, GPIO 23: %d, GPIO 24: %d\n",
               gpiod_line_get_value(gpiod_chip_get_line(chip, GPIO_17)),
               gpiod_line_get_value(gpiod_chip_get_line(chip, GPIO_22)),
               gpiod_line_get_value(gpiod_chip_get_line(chip, GPIO_23)),
               gpiod_line_get_value(gpiod_chip_get_line(chip, GPIO_24)));

        // Wait for 1 second
        sleep(1);
    }

cleanup:
    // Unexport GPIO pins
    unexport_gpio(chip, GPIO_17);
    unexport_gpio(chip, GPIO_22);
    unexport_gpio(chip, GPIO_23);
    unexport_gpio(chip, GPIO_24);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 18
#define GPIO_DIRECTION "out"

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

int main() {
    int ret;
    int value;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIO_CHIP);
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %d\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set GPIO direction to output
    ret = gpiod_line_request_output(line, GPIO_DIRECTION, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO direction: %d\n", ret);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("GPIO %d initialized as output. Press Ctrl+C to exit.\n", GPIO_PIN);

    // Main loop
    while (!terminate) {
        // Read GPIO value
        value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO value: %d\n", value);
            break; // Exit loop on error
        }

        // Validate GPIO value
        if (value != 0 && value != 1) {
            fprintf(stderr, "Invalid GPIO value: %d\n", value);
            break; // Exit loop on invalid value
        }

        // Set GPIO value
        ret = gpiod_line_set_value(line, value);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO value: %d\n", ret);
            break; // Exit loop on error
        }

        // Print GPIO value
        printf("GPIO %d set to %d\n", GPIO_PIN, value);

        // Wait for 1 second
        sleep(1);
    }

    // Release GPIO line
    gpiod_line_release(line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    printf("GPIO %d terminated.\n", GPIO_PIN);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Configuration
#define GPIO_PIN 17
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 5000
#define LOG_FILE "gpio_control.log"
#define DEBOUNCE_DELAY_MS 50

// Global variables
static volatile int running = 1;
static int gpio_fd = -1;
static FILE *log_file = NULL;

// Function prototypes
int gpio_init();
int gpio_read();
int gpio_write(int value);
int send_data(int value);
void signal_handler(int signal);
void log_message(const char *message);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_message("Received signal, shutting down...");
}

// Initialize GPIO using pigpio
int gpio_init() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpio_fd = gpioSetMode(GPIO_PIN, PI_OUTPUT);
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read the current state of the GPIO pin
int gpio_read() {
    int value = gpioRead(GPIO_PIN);
    if (value < 0) {
        fprintf(stderr, "Failed to read GPIO %d\n", GPIO_PIN);
        return -1;
    }
    return value;
}

// Write a value to the GPIO pin
int gpio_write(int value) {
    int result = gpioWrite(GPIO_PIN, value);
    if (result < 0) {
        fprintf(stderr, "Failed to write to GPIO %d\n", GPIO_PIN);
        return -1;
    }
    return 0;
}

// Send data to the server
int send_data(int value) {
    int sockfd;
    struct sockaddr_in servaddr;
    char buffer[10];

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("socket creation failed");
        log_message("Socket creation failed");
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(SERVER_PORT);

    if (inet_pton(AF_INET, SERVER_IP, &servaddr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        log_message("Invalid address/ Address not supported");
        close(sockfd);
        return -1;
    }

    if (connect(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("Connection Failed");
        log_message("Connection Failed");
        close(sockfd);
        return -1;
    }

    snprintf(buffer, sizeof(buffer), "%d", value);
    if (send(sockfd, buffer, strlen(buffer), 0) < 0) {
        perror("Send failed");
        log_message("Send failed");
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

// Log messages to a file
void log_message(const char *message) {
    if (log_file != NULL) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
        fflush(log_file); // Ensure immediate write
    }
}

int main() {
    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    // Initialize GPIO
    if (gpio_init() != 0) {
        log_message("GPIO initialization failed, exiting");
        fclose(log_file);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_value = -1; // Initialize to an invalid value
    time_t last_change_time = 0;

    log_message("GPIO control program started");

    while (running) {
        int current_value = gpio_read();
        if (current_value < 0) {
            log_message("Error reading GPIO, retrying...");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        if (current_value != last_value) {
            time_t now = time(NULL);
            if (difftime(now, last_change_time) * 1000 >= DEBOUNCE_DELAY_MS) {
                if (gpio_write(current_value) == 0) {
                    if (send_data(current_value) == 0) {
                        last_value = current_value;
                        last_change_time = now;
                        char log_buffer[100];
                        snprintf(log_buffer, sizeof(log_buffer), "Sent value: %d", current_value);
                        log_message(log_buffer);
                    } else {
                        log_message("Failed to send data to server");
                    }
                } else {
                    log_message("Failed to write to GPIO");
                }
            }
        }

        gpioDelay(10); // Check every 10ms
    }

    // Cleanup
    log_message("Cleaning up...");
    if (gpio_fd != -1) {
        gpioTerminate();
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    log_message("GPIO control program stopped");

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
