    time_t start_time;
    double elapsed_time;

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the UART port
    uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (uart_fd == -1) {
        perror("Error opening UART port");
        return 1;
    }

    // Configure the UART port
    if (tcgetattr(uart_fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(uart_fd);
        return 1;
    }

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;     // 8-bit chars
    tty.c_iflag &= ~IGNBRK;         // disable break processing
    tty.c_lflag = 0;                // no signaling chars, no echo, no canonical processing
    tty.c_oflag = 0;                // no remapping, no delays
    tty.c_cc[VMIN]  = 0;            // read doesn't block
    tty.c_cc[VTIME] = 5;            // 0.5 seconds read timeout

    tty.c_iflag &= ~(IXON | IXOFF | IXANY); // shut off xon/xoff ctrl

    tty.c_cflag |= (CLOCAL | CREAD);// ignore modem controls, enable reading
    tty.c_cflag &= ~(PARENB | PARODD);      // shut off parity
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    if (tcsetattr(uart_fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(uart_fd);
        return 1;
    }

    printf("UART port %s opened successfully. Reading data...\n", UART_DEVICE);

    while (program_running) {
        start_time = time(NULL);
        bytes_read = read(uart_fd, buffer, sizeof(buffer) - 1);

        if (bytes_read > 0) {
            buffer[bytes_read] = '\0'; // Null-terminate the buffer
            printf("%s", buffer);
        } else if (bytes_read < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                // Timeout occurred, no data received
                elapsed_time = difftime(time(NULL), start_time);
                if (elapsed_time >= READ_TIMEOUT_SEC) {
                    fprintf(stderr, "Timeout waiting for data. Assuming device is absent.\n");
                    break; // Exit the loop if timeout
                }
            } else {
                perror("Error reading from UART port");
                break;
            }
        } else {
            // No data received, but not an error
            break;
        }
    }

    // Close the UART port
    close(uart_fd);

    printf("UART port closed.\n");

    return 0;
}

