#define TIMEOUT 500000 // 0.5 seconds

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to trigger the HC-SR04 sensor
void triggerSensor(int triggerPin) {
    gpioWrite(triggerPin, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(triggerPin, 0);
}

// Function to measure the echo pulse duration
long pulseIn(int echoPin, int level, int timeout) {
    long startTime = 0, endTime = 0;

    // Wait for the echo pin to go high (with timeout)
    int count = 0;
    while (gpioRead(echoPin) != level && count < timeout) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= timeout) {
        return -1; // Timeout occurred
    }

    startTime = gpioTick();

    // Wait for the echo pin to go low (with timeout)
    count = 0;
    while (gpioRead(echoPin) == level && count < timeout) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= timeout) {
        return -1; // Timeout occurred
    }

    endTime = gpioTick();

    return endTime - startTime;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulseDuration) {
    if (pulseDuration < 0) {
        return -1.0; // Indicate an error
    }
    return (pulseDuration * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 for one-way distance
}

