// Define GPIO pins
#define GPIO_4 4
#define GPIO_17 17
#define GPIO_27 27

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to set the state of a GPIO pin
int set_gpio_state(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO state: %d\n", ret);
        return -1;
    }
    return 0;
}

// Function to read the state of a GPIO pin
int read_gpio_state(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO state: %d\n", value);
        return -1;
    }
    return value;
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open GPIO lines
    struct gpiod_chip *chip;
    struct gpiod_line *line4, *line17, *line27;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    line4 = gpiod_chip_get_line(chip, GPIO_4);
    if (!line4) {
        fprintf(stderr, "Error getting GPIO %d line: %s\n", GPIO_4, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        fprintf(stderr, "Error getting GPIO %d line: %s\n", GPIO_17, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(line4);
        return 1;
    }

    line27 = gpiod_chip_get_line(chip, GPIO_27);
    if (!line27) {
        fprintf(stderr, "Error getting GPIO %d line: %s\n", GPIO_27, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(line4);
        gpiod_line_release(line17);
        return 1;
    }

    // Request GPIO lines as output
    if (gpiod_line_request_output(line4, "gpio_control", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO %d as output: %s\n", GPIO_4, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(line4);
        gpiod_line_release(line17);
        gpiod_line_release(line27);
        return 1;
    }

    if (gpiod_line_request_output(line17, "gpio_control", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO %d as output: %s\n", GPIO_17, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(line4);
        gpiod_line_release(line17);
        gpiod_line_release(line27);
        return 1;
    }

    if (gpiod_line_request_output(line27, "gpio_control", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO %d as output: %s\n", GPIO_27, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(line4);
        gpiod_line_release(line17);
        gpiod_line_release(line27);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Set GPIO states
        if (set_gpio_state(line4, 1) < 0) {
            break;
        }
        if (set_gpio_state(line17, 0) < 0) {
            break;
        }
        if (set_gpio_state(line27, 1) < 0) {
            break;
        }

        // Read GPIO states
        int state4 = read_gpio_state(line4);
        int state17 = read_gpio_state(line17);
        int state27 = read_gpio_state(line27);

        if (state4 < 0 || state17 < 0 || state27 < 0) {
            break;
        }

        // Print GPIO states
        printf("GPIO %d: %d, GPIO %d: %d, GPIO %d: %d\n", GPIO_4, state4, GPIO_17, state17, GPIO_27, state27);

        // Wait for 0.5 seconds
        sleep(0.5);
    }

    // Release GPIO lines
    gpiod_line_release(line4);
    gpiod_line_release(line17);
    gpiod_line_release(line27);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

