#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Configuration
#define GPIO_PIN 24
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 12345
#define LOG_FILE "gpio_control.log"
#define DEBOUNCE_DELAY_MS 50

// Global variables
static volatile int running = 1;
static int gpio_fd = -1;
static FILE *log_file = NULL;

// Function prototypes
int gpio_init();
int gpio_read();
int gpio_write(int value);
int send_data(int value);
void signal_handler(int signal);
void log_message(const char *message);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_message("Received signal, shutting down...");
}

// Initialize GPIO using pigpio
int gpio_init() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpio_fd = gpioSetMode(GPIO_PIN, PI_OUTPUT);
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read the current state of the GPIO pin
int gpio_read() {
    int value = gpioRead(GPIO_PIN);
    if (value < 0) {
        fprintf(stderr, "Failed to read GPIO %d\n", GPIO_PIN);
        return -1;
    }
    return value;
}

// Write a value to the GPIO pin
int gpio_write(int value) {
    int result = gpioWrite(GPIO_PIN, value);
    if (result < 0) {
        fprintf(stderr, "Failed to write to GPIO %d\n", GPIO_PIN);
        return -1;
    }
    return 0;
}

// Send data to the server
int send_data(int value) {
    int sockfd;
    struct sockaddr_in servaddr;
    char buffer[10];

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("socket creation failed");
        log_message("Socket creation failed");
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(SERVER_PORT);

    if (inet_pton(AF_INET, SERVER_IP, &servaddr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        log_message("Invalid address/ Address not supported");
        close(sockfd);
        return -1;
    }

    if (connect(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("Connection Failed");
        log_message("Connection Failed");
        close(sockfd);
        return -1;
    }

    snprintf(buffer, sizeof(buffer), "%d", value);
    if (send(sockfd, buffer, strlen(buffer), 0) < 0) {
        perror("Send failed");
        log_message("Send failed");
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

// Log messages to a file
void log_message(const char *message) {
    if (log_file != NULL) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
        fflush(log_file); // Ensure immediate write
    }
}

int main() {
    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_init() != 0) {
        log_message("GPIO initialization failed, exiting");
        fclose(log_file);
        return 1;
    }

    log_message("GPIO control program started");

    int last_value = -1; // Initialize to an invalid value
    time_t last_change_time = 0;

    while (running) {
        int current_value = gpio_read();
        if (current_value < 0) {
            log_message("Failed to read GPIO, retrying...");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        if (current_value != last_value) {
            time_t now = time(NULL);
            if (difftime(now, last_change_time) * 1000 >= DEBOUNCE_DELAY_MS) {
                if (gpio_write(current_value) == 0) {
                    if (send_data(current_value) == 0) {
                        last_value = current_value;
                        last_change_time = now;
                        char log_buffer[100];
                        snprintf(log_buffer, sizeof(log_buffer), "Sent value %d to server", current_value);
                        log_message(log_buffer);
                    } else {
                        log_message("Failed to send data to server");
                    }
                } else {
                    log_message("Failed to write to GPIO");
                }
            }
        }

        gpioDelay(10); // Check every 10ms
    }

    // Cleanup
    log_message("Cleaning up...");
    gpio_write(0); // Set GPIO to LOW before exiting
    if (gpio_fd >= 0) {
        gpioTerminate();
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    log_message("GPIO control program stopped");

    return 0;
}

