#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define LED_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MAX_DISTANCE 400.0    // cm
#define MIN_DISTANCE 2.0      // cm
#define TIMEOUT_US 50000      // 50ms timeout

// Global variables
static volatile int running = 1;
static volatile unsigned int start_tick = 0;
static volatile unsigned int end_tick = 0;

// Function prototypes
void trigger_pulse();
float calculate_distance(unsigned int pulse_width);
void control_led(float distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to trigger the ultrasonic sensor
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to calculate the distance in centimeters
float calculate_distance(unsigned int pulse_width) {
    if (pulse_width == 0) return MAX_DISTANCE; // Avoid division by zero
    return (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Divide by 1000000.0 to convert us to s, then by 2 to get distance
}

// Function to control the LED based on the distance
void control_led(float distance) {
    if (distance < MIN_DISTANCE) {
        gpioWrite(LED_PIN, 1); // Turn LED on
    } else if (distance > MAX_DISTANCE) {
        gpioWrite(LED_PIN, 0); // Turn LED off
    } else {
        gpioWrite(LED_PIN, 1); // Turn LED on for a short duration
        gpioDelay(500);          // Wait 500ms
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Ultrasonic sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        trigger_pulse();

        // Wait for echo to start
        int timeout = 0;
        while (gpioRead(ECHO_PIN) == 0 && timeout < TIMEOUT_US) {
            timeout++;
            gpioDelay(1); // Small delay to prevent busy-waiting
        }

        if (timeout >= TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo start\n");
            continue; // Skip to the next iteration
        }

        start_tick = gpioTick();

        // Wait for echo to end
        timeout = 0;
        while (gpioRead(ECHO_PIN) == 1 && timeout < TIMEOUT_US) {
            timeout++;
            gpioDelay(1); // Small delay to prevent busy-waiting
        }

        if (timeout >= TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo end\n");
            continue; // Skip to the next iteration
        }

        end_tick = gpioTick();

        // Calculate pulse width
        unsigned int pulse_width = end_tick - start_tick;

        // Calculate distance
        float distance = calculate_distance(pulse_width);

        // Control LED
        control_led(distance);

        // Print distance to console
        printf("Distance: %.2f cm\n", distance);

        // Delay to avoid overwhelming the system
        gpioDelay(100); // 100ms delay
    }

    // Release GPIO resources
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

