// Function to initialize the TCS34725 sensor
int init_tcs34725() {
    // Enable power and ALS
    if (i2c_smbus_write_byte_data(i2c_fd, TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0) {
        perror("Error writing to ENABLE register");
        return -1;
    }

    // Set integration time
    if (i2c_smbus_write_byte_data(i2c_fd, TCS34725_ATIME, TCS34725_INTEGRATIONTIME_24MS) < 0) {
        perror("Error writing to ATIME register");
        return -1;
    }

    // Set gain
    if (i2c_smbus_write_byte_data(i2c_fd, TCS34725_CONTROL, 0x03) < 0) {
        perror("Error writing to CONTROL register");
        return -1;
    }

    return 0;
}

// Function to read the color data from the TCS34725 sensor
int read_color_data(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t data[8];

    if (i2c_smbus_read_i2c_block_data(i2c_fd, TCS34725_CDATA, (char *)data, 8) < 0) {
        perror("Error reading color data");
        return -1;
    }

    *clear = (data[1] << 8) | data[0];
    *red = (data[3] << 8) | data[2];
    *green = (data[5] << 8) | data[4];
    *blue = (data[7] << 8) | data[6];

    return 0;
}

