// Define GPIO pins
#define TRIGGER_PIN 18
#define ECHO_PIN 23

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 500000      // 0.5 seconds

// Global variables
static volatile int running = 1;
static volatile unsigned int start_tick = 0;
static volatile unsigned int end_tick = 0;

// Function prototypes
void trigger_pulse();
float calculate_distance(unsigned int start_tick, unsigned int end_tick);
void echo_callback(int gpio, int level, unsigned int tick);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to trigger a 10us pulse on the trigger pin
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin changes
void echo_callback(int gpio, int level, unsigned int tick) {
    if (level == 1) {
        start_tick = tick;
    } else if (level == 0) {
        end_tick = tick;
    }
}

// Function to calculate the distance in centimeters
float calculate_distance(unsigned int start_tick, unsigned int end_tick) {
    if (start_tick == 0 || end_tick == 0) {
        return -1.0; // Indicate error
    }

    unsigned int diff = end_tick - start_tick;
    if (diff > TIMEOUT_US) {
        return -1.0; // Timeout
    }

    float time_taken = (float)diff / 1000000.0; // Convert us to seconds
    float distance = (time_taken * SPEED_OF_SOUND) / 2.0; // Distance in cm

    return distance;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("HC-SR04 Distance Sensor\n");
    printf("Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        trigger_pulse();

        // Wait for echo to start (with timeout)
        int timeout = 0;
        while (gpioRead(ECHO_PIN) == 0 && timeout < 1000) {
            gpioDelay(1); // Small delay to prevent busy-waiting
            timeout++;
        }

        if (timeout >= 1000) {
            fprintf(stderr, "Timeout waiting for echo start\n");
            continue; // Skip to the next iteration
        }

        // Wait for echo to end (with timeout)
        timeout = 0;
        while (gpioRead(ECHO_PIN) == 1 && timeout < 1000) {
            gpioDelay(1); // Small delay to prevent busy-waiting
            timeout++;
        }

        if (timeout >= 1000) {
            fprintf(stderr, "Timeout waiting for echo end\n");
            continue; // Skip to the next iteration
        }

        // Calculate distance
        float distance = calculate_distance(start_tick, end_tick);

        if (distance < 0) {
            fprintf(stderr, "Error: Invalid distance measurement\n");
        } else {
            printf("Distance: %.2f cm\n", distance);
        }

        gpioDelay(100); // Delay between readings
    }

    // Release GPIO resources
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 18
#define GPIO_DIRECTION "out"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

int main() {
    int ret;
    int value;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set GPIO direction to output
    ret = gpiod_line_request_output(line, GPIO_DIRECTION, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO direction: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        // Read GPIO value
        value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO value: %s\n", strerror(errno));
            break; // Exit loop on error
        }

        // Validate GPIO value
        if (value != 0 && value != 1) {
            fprintf(stderr, "Invalid GPIO value: %d\n", value);
            break; // Exit loop on invalid value
        }

        // Set GPIO value
        ret = gpiod_line_set_value(line, value);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO value: %s\n", strerror(errno));
            break; // Exit loop on error
        }

        // Print GPIO value
        printf("GPIO %d set to %d\n", GPIO_PIN, value);

        // Wait for 1 second
        sleep(1);
    }

    // Release GPIO line
    gpiod_line_release(line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int pwm_value;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 18 as output
    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("PWM output on GPIO %d (frequency %d Hz, range %d) started. Press Ctrl+C to exit.\n", PWM_GPIO, PWM_FREQUENCY, PWM_RANGE);

    // Main loop
    while (program_running) {
        // Generate PWM values (0-1000)
        for (pwm_value = 0; pwm_value <= PWM_RANGE; pwm_value++) {
            gpioPWM(PWM_GPIO, pwm_value);
            printf("PWM value: %d\n", pwm_value);
            gpioDelay(20000); // 20ms delay
        }

        // Reverse PWM values (1000-0)
        for (pwm_value = PWM_RANGE; pwm_value >= 0; pwm_value--) {
            gpioPWM(PWM_GPIO, pwm_value);
            printf("PWM value: %d\n", pwm_value);
            gpioDelay(20000); // 20ms delay
        }
    }

    // Stop PWM output
    gpioPWM(PWM_GPIO, 0);

    // Release GPIO resources
    gpioTerminate();

    printf("PWM output stopped and GPIO resources released.\n");

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define GPIO_PIN_1 17
#define GPIO_PIN_2 18

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Global variables for GPIO lines
struct gpiod_line *gpio_line_1 = NULL;
struct gpiod_line *gpio_line_2 = NULL;

// Function prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_set_value(int pin, int value);
int gpio_get_value(int pin);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Unexport GPIO pins
    if (gpio_line_1 != NULL) {
        gpiod_line_release(gpio_line_1);
    }
    if (gpio_line_2 != NULL) {
        gpiod_line_release(gpio_line_2);
    }

    // Close GPIO chip
    gpiod_chip_close(gpio_line_1->chip);

    exit(0);
}

// Function to export a GPIO pin
int gpio_export(int pin) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIO_CHIP);
        return -1;
    }

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d\n", pin);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(line, "gpio_control", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %d\n", pin, ret);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    gpio_line_1 = line;
    gpio_line_2 = line; // Assign the same line for both pins

    return 0;
}

// Function to unexport a GPIO pin
int gpio_unexport(int pin) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIO_CHIP);
        return -1;
    }

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d\n", pin);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_release(line);
    if (ret < 0) {
        fprintf(stderr, "Error releasing GPIO line %d: %d\n", pin, ret);
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

// Function to set the direction of a GPIO pin (in or out)
int gpio_set_direction(int pin, const char *direction) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIO_CHIP);
        return -1;
    }

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d\n", pin);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_set_direction(line, direction);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line %d direction to %s: %d\n", pin, direction, ret);
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

// Function to set the value of a GPIO pin (0 or 1)
int gpio_set_value(int pin, int value) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIO_CHIP);
        return -1;
    }

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d\n", pin);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line %d value to %d: %d\n", pin, value, ret);
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

// Function to get the value of a GPIO pin
int gpio_get_value(int pin) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int value;
    int ret;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIO_CHIP);
        return -1;
    }

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d\n", pin);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_get_value(line);
    if (ret < 0) {
        fprintf(stderr, "Error getting GPIO line %d value: %d\n", pin, ret);
        gpiod_chip_close(chip);
        return -1;
    }

    value = ret;
    gpiod_chip_close(chip);
    return value;
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Export GPIO pins
    if (gpio_export(GPIO_PIN_1) < 0 || gpio_export(GPIO_PIN_2) < 0) {
        fprintf(stderr, "Failed to export GPIO pins. Exiting.\n");
        return 1;
    }

    // Set GPIO direction to output
    if (gpio_set_direction(GPIO_PIN_1, "out") < 0 || gpio_set_direction(GPIO_PIN_2, "out") < 0) {
        fprintf(stderr, "Failed to set GPIO direction. Exiting.\n");
        gpio_unexport(GPIO_PIN_1);
        gpio_unexport(GPIO_PIN_2);
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO 1 to HIGH
        if (gpio_set_value(GPIO_PIN_1, 1) < 0) {
            fprintf(stderr, "Failed to set GPIO 1 value. Continuing.\n");
        }

        // Set GPIO 2 to LOW
        if (gpio_set_value(GPIO_PIN_2, 0) < 0) {
            fprintf(stderr, "Failed to set GPIO 2 value. Continuing.\n");
        }

        // Wait for 1 second
        sleep(1);

        // Set GPIO 1 to LOW
        if (gpio_set_value(GPIO_PIN_1, 0) < 0) {
            fprintf(stderr, "Failed to set GPIO 1 value. Continuing.\n");
        }

        // Set GPIO 2 to HIGH
        if (gpio_set_value(GPIO_PIN_2, 1) < 0) {
            fprintf(stderr, "Failed to set GPIO 2 value. Continuing.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define GPIO_18 18
#define GPIO_23 23
#define GPIO_24 24

// Global variable to track if the program should exit
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to set the state of a GPIO pin
int set_gpio_state(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO state: %d\n", ret);
        return -1;
    }
    return 0;
}

// Function to read the state of a GPIO pin
int read_gpio_state(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO state: %d\n", value);
        return -1;
    }
    return value;
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %m\n");
        return 1;
    }

    // Get GPIO lines for each pin
    struct gpiod_line *line_18 = gpiod_chip_get_line(chip, GPIO_18);
    struct gpiod_line *line_23 = gpiod_chip_get_line(chip, GPIO_23);
    struct gpiod_line *line_24 = gpiod_chip_get_line(chip, GPIO_24);

    if (!line_18 || !line_23 || !line_24) {
        fprintf(stderr, "Error getting GPIO line: %m\n");
        goto cleanup;
    }

    // Request GPIO lines as output
    int ret = gpiod_line_request_output(line_18, "gpio_control", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %d\n", ret);
        goto cleanup;
    }

    ret = gpiod_line_request_output(line_23, "gpio_control", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %d\n", ret);
        goto cleanup;
    }

    ret = gpiod_line_request_output(line_24, "gpio_control", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %d\n", ret);
        goto cleanup;
    }

    // Main loop to control GPIO pins
    while (program_running) {
        // Set GPIO 18 to HIGH
        ret = set_gpio_state(line_18, 1);
        if (ret < 0) {
            goto cleanup;
        }
        printf("GPIO 18 set to HIGH\n");

        // Read GPIO 23
        int value = read_gpio_state(line_23);
        if (value < 0) {
            goto cleanup;
        }
        printf("GPIO 23 value: %d\n", value);

        // Set GPIO 24 to LOW
        ret = set_gpio_state(line_24, 0);
        if (ret < 0) {
            goto cleanup;
        }
        printf("GPIO 24 set to LOW\n");

        // Wait for 0.1 seconds
        sleep(1);
    }

cleanup:
    // Release GPIO lines
    if (line_18) {
        gpiod_line_release(line_18);
    }
    if (line_23) {
        gpiod_line_release(line_23);
    }
    if (line_24) {
        gpiod_line_release(line_24);
    }

    // Close the GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to initialize the MPU6050
int init_mpu6050() {
    // Wake up the MPU6050 (clear sleep mode bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU6050\n");
        return -1;
    }
    return 0;
}

// Function to read raw accelerometer data
int read_raw_accelerometer(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: Could not read accelerometer data\n");
        return -1;
    }

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Function to convert raw accelerometer data to g-force units
void convert_to_g(int16_t raw_x, int16_t raw_y, int16_t raw_z, float *x, float *y, float *z) {
    // Sensitivity scale factor for +/- 2g range
    const float sensitivity = 16384.0f;

    *x = (float)raw_x / sensitivity;
    *y = (float)raw_y / sensitivity;
    *z = (float)raw_z / sensitivity;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    int16_t raw_x, raw_y, raw_z;
    float x_g, y_g, z_g;

    while (!terminate) {
        // Read raw accelerometer data
        if (read_raw_accelerometer(&raw_x, &raw_y, &raw_z) == 0) {
            // Convert to g-force units
            convert_to_g(raw_x, raw_y, raw_z, &x_g, &y_g, &z_g);

            // Print the accelerometer data
            printf("X: %.3f g, Y: %.3f g, Z: %.3f g\n", x_g, y_g, z_g);
        } else {
            fprintf(stderr, "Error: Failed to read accelerometer data. Retrying...\n");
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Close I2C device and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

#include <stdio.h>
